// Nuvemath — 7-sinf, Geometriya (III qism) nazariyasi. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t1. Eng sodda shakllar. Kesmalarni o‘lchash ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Geometriya qayerdan boshlanadi?', 'С чего начинается геометрия?', 'Where does geometry begin?'), p: [
      L('Qalamni qog‘ozga bir marta tekkizing — nuqta hosil bo‘ldi. Chizg‘ichni qo‘yib, qalamni yurgizing — to‘g‘ri chiziq paydo bo‘ldi. Ana shu ikki oddiy harakatdan butun bir fan — <b>geometriya</b> boshlanadi. Siz ularni birinchi sinfdan beri chizasiz, lekin endi ularga olim ko‘zi bilan qaraymiz: nuqta nima, to‘g‘ri chiziq nima, ular bir-biri bilan qanday bog‘langan?', 'Коснитесь карандашом бумаги один раз — получилась точка. Приложите линейку и проведите карандашом — появилась прямая. С этих двух простых движений начинается целая наука — <b>геометрия</b>. Вы рисуете их с первого класса, но теперь посмотрим на них глазами учёного: что такое точка, что такое прямая и как они связаны друг с другом?', 'Touch the paper once with a pencil — you get a point. Put down a ruler and run the pencil along it — you get a straight line. From these two simple moves a whole science begins: <b>geometry</b>. You have drawn them since first grade, but now we look at them like scientists: what is a point, what is a line, and how are they connected?'),
      L('Geometriyaning boshqa fanlardan farqi shundaki, unda har bir gap <b>isbotlanadi</b>. Biz hech narsani «ko‘rinib turibdi-ku» deb qabul qilmaymiz. Faqat bir nechta eng sodda tasdiq — <b>aksiomalar</b> — isbotsiz qabul qilinadi, qolgan hamma narsa ulardan mantiq bilan keltirib chiqariladi. Bu mavzuda birinchi aksiomalar bilan tanishamiz va kesmalarni o‘lchashni o‘rganamiz.', 'Геометрия отличается от других наук тем, что в ней каждое утверждение <b>доказывается</b>. Мы ничего не принимаем «потому что и так видно». Лишь несколько самых простых утверждений — <b>аксиомы</b> — принимаются без доказательства, а всё остальное выводится из них логически. В этой теме мы познакомимся с первыми аксиомами и научимся измерять отрезки.', 'What makes geometry different from other subjects is that every statement in it is <b>proved</b>. We never accept something just because “you can see it”. Only a few very simple statements, the <b>axioms</b>, are accepted without proof; everything else is deduced from them by logic. In this topic we meet the first axioms and learn to measure segments.'),
      L('Nega bu kerak? Quruvchi devorning to‘g‘riligini, haydovchi yo‘lning uzunligini, dasturchi esa ekrandagi chiziqlarning joylashuvini aynan shu tushunchalar orqali hisoblaydi.', 'Зачем это нужно? Строитель проверяет ровность стены, водитель рассчитывает длину пути, а программист — положение линий на экране именно с помощью этих понятий.', 'Why do we need it? A builder checks that a wall is straight, a driver works out the length of a road, and a programmer places lines on a screen using exactly these ideas.')
    ] },
    { kind: 'def', h: L('Nuqta, to‘g‘ri chiziq, nur, kesma', 'Точка, прямая, луч, отрезок', 'Point, line, ray, segment'), p: [
      L('Geometriyaning asosiy shakllari ta’riflanmaydi — ular eng boshlang‘ich tushunchalar. Biz ularni faqat tasvirlab beramiz:', 'Основные фигуры геометрии не определяются — это самые первичные понятия. Мы можем их только описать:', 'The basic figures of geometry are not defined — they are the most primitive ideas. We can only describe them:')
    ], list: [
      L('<b>Nuqta</b> — o‘lchami yo‘q, faqat o‘rni bor. Bosh harflar bilan belgilanadi: A, B, C.', '<b>Точка</b> — не имеет размера, только положение. Обозначается заглавными буквами: A, B, C.', 'A <b>point</b> has no size, only a position. It is named with capital letters: A, B, C.'),
      L('<b>To‘g‘ri chiziq</b> — ikki tomonga cheksiz davom etadi, qalinligi yo‘q. Kichik harf bilan (a, b) yoki ikki nuqtasi bilan (AB) belgilanadi.', '<b>Прямая</b> — бесконечна в обе стороны, не имеет толщины. Обозначается строчной буквой (a, b) или двумя своими точками (AB).', 'A <b>line</b> goes on forever in both directions and has no thickness. It is named by a small letter (a, b) or by two of its points (AB).'),
      L('<b>Nur</b> — to‘g‘ri chiziqning bir nuqtadan boshlanib, bir tomonga cheksiz davom etuvchi qismi. OA nuri: O — boshi.', '<b>Луч</b> — часть прямой, которая начинается в точке и бесконечно продолжается в одну сторону. Луч OA: O — начало.', 'A <b>ray</b> is the part of a line that starts at a point and goes on forever in one direction. Ray OA: O is its endpoint.'),
      L('<b>Kesma</b> — to‘g‘ri chiziqning ikki nuqta orasidagi qismi, ikkala uchi ham kiradi. AB kesma: A va B — uchlari.', '<b>Отрезок</b> — часть прямой между двумя точками вместе с этими точками. Отрезок AB: A и B — концы.', 'A <b>segment</b> is the part of a line between two points, including both points. Segment AB: A and B are its endpoints.'),
      L('<b>Tekislik</b> — cheksiz tekis yuza; daftar varag‘i uning kichik bo‘lagi. Bu kursda hamma shakllar bitta tekislikda yotadi — shuning uchun u <b>planimetriya</b> deyiladi.', '<b>Плоскость</b> — бесконечная ровная поверхность; лист тетради — её маленький кусочек. В этом курсе все фигуры лежат в одной плоскости, поэтому он называется <b>планиметрией</b>.', 'A <b>plane</b> is an endless flat surface; a notebook page is a tiny piece of one. In this course all figures lie in one plane, which is why it is called <b>plane geometry</b>.')
    ], after: [
      L('Nuqta to‘g‘ri chiziqda <b>yotadi</b> yoki <b>yotmaydi</b>. Yozuvi: A ∈ a (A nuqta a chiziqda yotadi), B ∉ a (yotmaydi). Ikki to‘g‘ri chiziq umumiy nuqtaga ega bo‘lsa, ular <b>kesishadi</b>.', 'Точка <b>лежит</b> или <b>не лежит</b> на прямой. Запись: A ∈ a (точка A лежит на прямой a), B ∉ a (не лежит). Если у двух прямых есть общая точка, они <b>пересекаются</b>.', 'A point either <b>lies on</b> a line or it does not. Notation: A ∈ a (point A lies on line a), B ∉ a (it does not). If two lines share a point, they <b>intersect</b>.')
    ] },
    { kind: 'history', h: L('Yevklid va «Negizlar»', 'Евклид и «Начала»', 'Euclid and the Elements'), p: [
      L('«Geometriya» so‘zi yunoncha <i>geo</i> — yer va <i>metreo</i> — o‘lchayman so‘zlaridan tuzilgan. Qadimgi Misrda Nil daryosi har yili toshib, dalalarning chegaralarini yuvib ketardi. Suv qaytgach, maxsus o‘lchovchilar — «arqon tortuvchilar» — yer uchastkalarini qaytadan chizib chiqishardi. Ana shu amaliy ishdan geometriya tug‘ilgan.', 'Слово «геометрия» составлено из греческих <i>гео</i> — земля и <i>метрео</i> — измеряю. В Древнем Египте Нил каждый год разливался и смывал границы полей. Когда вода уходила, особые измерители — «натягиватели верёвок» — заново размечали участки. Из этой практической работы и родилась геометрия.', 'The word “geometry” comes from the Greek <i>geo</i> (earth) and <i>metreo</i> (I measure). In Ancient Egypt the Nile flooded every year and washed away the boundaries of the fields. When the water went down, special surveyors, the “rope-stretchers”, marked out the plots again. Geometry was born from this practical work.'),
      L('Miloddan avvalgi VI asrda yunon olimi <b>Fales</b> birinchi bo‘lib geometrik tasdiqlarni isbotlay boshlagan. U Misr piramidasining balandligini uning soyasi orqali o‘lchagan. Miloddan avvalgi 300-yillarda Iskandariyada yashagan <b>Yevklid</b> esa barcha ma’lum bilimlarni 13 kitobdan iborat «Negizlar» asarida to‘plagan. U nuqta, to‘g‘ri chiziq ta’riflaridan va bir nechta aksiomadan boshlab, yuzlab teoremani ketma-ket isbotlagan.', 'В VI веке до нашей эры греческий учёный <b>Фалес</b> первым стал доказывать геометрические утверждения. Он измерил высоту египетской пирамиды по её тени. А <b>Евклид</b>, живший в Александрии около 300 года до н. э., собрал все известные знания в сочинении «Начала» из 13 книг. Начав с описаний точки и прямой и нескольких аксиом, он последовательно доказал сотни теорем.', 'In the 6th century BC the Greek scholar <b>Thales</b> was the first to prove geometric statements. He measured the height of an Egyptian pyramid using its shadow. <b>Euclid</b>, who lived in Alexandria around 300 BC, collected all known knowledge in the <i>Elements</i>, a work of 13 books. Starting from descriptions of point and line and a few axioms, he proved hundreds of theorems one after another.'),
      L('«Negizlar» ikki ming yildan ortiq vaqt davomida darslik bo‘lib xizmat qildi. Sharqda uni <b>al-Xorazmiy</b>, <b>Beruniy</b>, <b>Umar Xayyom</b> o‘rgangan va sharhlagan. Bugun siz o‘rganayotgan aksiomalar aynan Yevklid tizimining davomi.', '«Начала» служили учебником более двух тысяч лет. На Востоке их изучали и комментировали <b>аль-Хорезми</b>, <b>Беруни</b>, <b>Омар Хайям</b>. Аксиомы, которые вы изучаете сегодня, — прямое продолжение системы Евклида.', 'The <i>Elements</i> served as a textbook for more than two thousand years. In the East it was studied and commented on by <b>al-Khwarizmi</b>, <b>Biruni</b> and <b>Omar Khayyam</b>. The axioms you study today are a direct continuation of Euclid’s system.')
    ] },
    { kind: 'rule', h: L('Birinchi aksiomalar', 'Первые аксиомы', 'The first axioms'), p: [
      L('<b>Aksioma</b> — isbotsiz qabul qilinadigan tasdiq. <b>Teorema</b> — isbotlanishi kerak bo‘lgan tasdiq. Mana to‘g‘ri chiziq va kesmalar haqidagi asosiy aksiomalar:', '<b>Аксиома</b> — утверждение, принимаемое без доказательства. <b>Теорема</b> — утверждение, которое нужно доказать. Вот основные аксиомы о прямых и отрезках:', 'An <b>axiom</b> is a statement accepted without proof. A <b>theorem</b> is a statement that must be proved. Here are the basic axioms about lines and segments:')
    ], list: [
      L('Har qanday to‘g‘ri chiziqda unga tegishli va tegishli bo‘lmagan nuqtalar bor.', 'На любой прямой есть точки, принадлежащие ей, и точки, ей не принадлежащие.', 'For any line there are points on it and points not on it.'),
      L('Ikki nuqta orqali <b>faqat bitta</b> to‘g‘ri chiziq o‘tadi.', 'Через две точки проходит <b>только одна</b> прямая.', 'Through two points there passes <b>exactly one</b> line.'),
      L('Har bir kesmaning musbat <b>uzunligi</b> bor. Agar C nuqta AB kesmada yotsa, <b>AB = AC + CB</b>.', 'У каждого отрезка есть положительная <b>длина</b>. Если точка C лежит на отрезке AB, то <b>AB = AC + CB</b>.', 'Every segment has a positive <b>length</b>. If point C lies on segment AB, then <b>AB = AC + CB</b>.'),
      L('Har qanday nurga uning boshidan boshlab berilgan uzunlikdagi kesmani <b>faqat bitta</b> usulda qo‘yish mumkin.', 'На любом луче от его начала можно отложить отрезок заданной длины, и <b>только один</b>.', 'On any ray, from its endpoint, a segment of a given length can be laid off in <b>exactly one</b> way.')
    ], after: [
      L('Ikkinchi aksiomadan muhim natija kelib chiqadi: <b>ikki to‘g‘ri chiziq ko‘pi bilan bitta umumiy nuqtaga ega</b>. Isbot g‘oyasi: agar ikki umumiy nuqta bo‘lsa, ular orqali ikkita turli to‘g‘ri chiziq o‘tgan bo‘lardi — bu aksiomaga zid.', 'Из второй аксиомы вытекает важное следствие: <b>две прямые имеют не более одной общей точки</b>. Идея доказательства: будь у них две общие точки, через эти точки проходили бы две разные прямые — противоречие с аксиомой.', 'The second axiom gives an important consequence: <b>two lines have at most one common point</b>. Idea of the proof: if they had two common points, two different lines would pass through those points — contradicting the axiom.'),
      L('<b>Kesmaning o‘rtasi</b> — uni ikki teng kesmaga bo‘luvchi nuqta. M nuqta AB ning o‘rtasi bo‘lsa, AM = MB = AB : 2. Ikki kesma uzunliklari teng bo‘lsa, kesmalar <b>teng</b> deyiladi.', '<b>Середина отрезка</b> — точка, делящая его на два равных отрезка. Если M — середина AB, то AM = MB = AB : 2. Отрезки с равными длинами называются <b>равными</b>.', 'The <b>midpoint</b> of a segment is the point that divides it into two equal segments. If M is the midpoint of AB, then AM = MB = AB : 2. Segments of equal length are called <b>equal</b>.')
    ] },
    { kind: 'steps', h: L('Kesmani o‘lchash va noma’lum qismni topish', 'Измерение отрезка и поиск неизвестной части', 'Measuring a segment and finding an unknown part'), p: [
      L('Kesma uzunligini topish uchun o‘lchov birligi tanlanadi (millimetr, santimetr, metr) va kesma shu birlik necha marta sig‘ishi hisoblanadi. Chizg‘ich bilan o‘lchash qadamlari:', 'Чтобы найти длину отрезка, выбирают единицу измерения (миллиметр, сантиметр, метр) и считают, сколько раз она укладывается в отрезке. Шаги измерения линейкой:', 'To find the length of a segment, choose a unit (millimetre, centimetre, metre) and count how many times it fits into the segment. Steps for measuring with a ruler:')
    ], list: [
      L('1-qadam. Chizg‘ichning <b>nol</b> belgisini kesmaning A uchiga aniq qo‘ying (chizg‘ich chetiga emas!).', 'Шаг 1. Приложите деление <b>ноль</b> линейки точно к концу A (не край линейки!).', 'Step 1. Place the <b>zero</b> mark of the ruler exactly on endpoint A (not the edge of the ruler!).'),
      L('2-qadam. Chizg‘ich kesma bo‘ylab yotganini tekshiring — qiyshaymasin.', 'Шаг 2. Проверьте, что линейка лежит вдоль отрезка, без перекоса.', 'Step 2. Check that the ruler lies along the segment without tilting.'),
      L('3-qadam. B uchi to‘g‘ri kelgan belgini o‘qing — bu uzunlik.', 'Шаг 3. Прочитайте деление напротив конца B — это и есть длина.', 'Step 3. Read the mark opposite endpoint B — that is the length.'),
      L('4-qadam. Masalada C nuqta AB ichida bo‘lsa, AB = AC + CB tenglikdan noma’lumni toping: CB = AB − AC.', 'Шаг 4. Если в задаче точка C лежит внутри AB, найдите неизвестное из равенства AB = AC + CB: CB = AB − AC.', 'Step 4. If in a problem point C lies inside AB, find the unknown from AB = AC + CB: CB = AB − AC.'),
      L('5-qadam. Javob mantiqan to‘g‘rimi, tekshiring: qism butundan katta bo‘lishi mumkin emas.', 'Шаг 5. Проверьте, разумен ли ответ: часть не может быть больше целого.', 'Step 5. Check that the answer makes sense: a part cannot be bigger than the whole.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Avval o‘zingiz yeching, keyin yechim bilan solishtiring.', 'Сначала решите сами, затем сравните с решением.', 'Solve each one yourself first, then compare with the solution.')
    ], ex: [
      { q: L('C nuqta AB kesmada yotadi. AB = 14 cm, AC = 5 cm. CB ni toping.', 'Точка C лежит на отрезке AB. AB = 14 см, AC = 5 см. Найдите CB.', 'Point C lies on segment AB. AB = 14 cm, AC = 5 cm. Find CB.'), s: L('Aksioma bo‘yicha AB = AC + CB. Demak, CB = AB − AC = 14 − 5 = <b>9 cm</b>. Tekshiramiz: 5 + 9 = 14. To‘g‘ri.', 'По аксиоме AB = AC + CB. Значит, CB = AB − AC = 14 − 5 = <b>9 см</b>. Проверка: 5 + 9 = 14. Верно.', 'By the axiom, AB = AC + CB. So CB = AB − AC = 14 − 5 = <b>9 cm</b>. Check: 5 + 9 = 14. Correct.') },
      { q: L('M nuqta AB kesmaning o‘rtasi, AM = 7,5 cm. AB ni toping.', 'M — середина отрезка AB, AM = 7,5 см. Найдите AB.', 'M is the midpoint of AB and AM = 7.5 cm. Find AB.'), s: L('O‘rta kesmani teng ikkiga bo‘ladi: AM = MB = 7,5 cm. AB = AM + MB = 7,5 + 7,5 = <b>15 cm</b>.', 'Середина делит отрезок пополам: AM = MB = 7,5 см. AB = AM + MB = 7,5 + 7,5 = <b>15 см</b>.', 'The midpoint halves the segment: AM = MB = 7.5 cm. AB = AM + MB = 7.5 + 7.5 = <b>15 cm</b>.') },
      { q: L('A, B, C nuqtalar bir to‘g‘ri chiziqda yotadi. AB = 6 cm, BC = 10 cm. AC qanday bo‘lishi mumkin?', 'Точки A, B, C лежат на одной прямой. AB = 6 см, BC = 10 см. Чему может равняться AC?', 'Points A, B, C lie on one line. AB = 6 cm and BC = 10 cm. What can AC be?'), s: L('Ikki hol bor. 1) B nuqta A va C orasida: AC = 6 + 10 = <b>16 cm</b>. 2) A nuqta B va C orasida: AC = 10 − 6 = <b>4 cm</b>. (C nuqta A va B orasida bo‘la olmaydi, chunki BC &gt; AB.) Javob: 16 cm yoki 4 cm.', 'Два случая. 1) B лежит между A и C: AC = 6 + 10 = <b>16 см</b>. 2) A лежит между B и C: AC = 10 − 6 = <b>4 см</b>. (C не может лежать между A и B, так как BC &gt; AB.) Ответ: 16 см или 4 см.', 'There are two cases. 1) B is between A and C: AC = 6 + 10 = <b>16 cm</b>. 2) A is between B and C: AC = 10 − 6 = <b>4 cm</b>. (C cannot be between A and B because BC &gt; AB.) Answer: 16 cm or 4 cm.') },
      { q: L('AB = 20 cm. C nuqta kesmani AC : CB = 2 : 3 nisbatda bo‘ladi. AC va CB ni toping.', 'AB = 20 см. Точка C делит отрезок в отношении AC : CB = 2 : 3. Найдите AC и CB.', 'AB = 20 cm. Point C divides it so that AC : CB = 2 : 3. Find AC and CB.'), s: L('Kesma 2 + 3 = 5 ulushga bo‘lingan. Bir ulush: 20 : 5 = 4 cm. AC = 2 · 4 = <b>8 cm</b>, CB = 3 · 4 = <b>12 cm</b>. Tekshiramiz: 8 + 12 = 20.', 'Отрезок разделён на 2 + 3 = 5 частей. Одна часть: 20 : 5 = 4 см. AC = 2 · 4 = <b>8 см</b>, CB = 3 · 4 = <b>12 см</b>. Проверка: 8 + 12 = 20.', 'The segment is split into 2 + 3 = 5 parts. One part is 20 : 5 = 4 cm. AC = 2 · 4 = <b>8 cm</b>, CB = 3 · 4 = <b>12 cm</b>. Check: 8 + 12 = 20.') }
    ] },
    { kind: 'table', h: L('Uzunlik birliklari', 'Единицы длины', 'Units of length'), p: [
      L('Kesma uzunligi har xil birliklarda ifodalanishi mumkin. Masalada hamma uzunliklarni bitta birlikka keltirib oling.', 'Длину отрезка можно выразить в разных единицах. В задаче приводите все длины к одной единице.', 'The length of a segment can be expressed in different units. In a problem, convert all lengths to the same unit.')
    ], table: { head: [L('Birlik', 'Единица', 'Unit'), L('Belgisi', 'Обозначение', 'Symbol'), L('Necha metr', 'Сколько метров', 'In metres'), L('Qayerda ishlatiladi', 'Где используется', 'Where it is used')], rows: [
      [L('millimetr', 'миллиметр', 'millimetre'), 'mm', '0,001', L('chizmachilik, detallar', 'черчение, детали', 'drawing, machine parts')],
      [L('santimetr', 'сантиметр', 'centimetre'), 'cm', '0,01', L('daftar, tikuvchilik', 'тетрадь, шитьё', 'notebooks, sewing')],
      [L('detsimetr', 'дециметр', 'decimetre'), 'dm', '0,1', L('kamdan-kam', 'редко', 'rarely')],
      [L('metr', 'метр', 'metre'), 'm', '1', L('qurilish, sport', 'строительство, спорт', 'building, sport')],
      [L('kilometr', 'километр', 'kilometre'), 'km', '1000', L('yo‘llar, geografiya', 'дороги, география', 'roads, geography')]
    ] }, after: [
      L('Eslatma: 1 cm = 10 mm, 1 m = 100 cm, 1 km = 1000 m. Qadimda odamlar tirsak, qarich, qadam kabi «tana» birliklaridan foydalangan; metr esa 1799-yili Fransiyada joriy qilingan va Yer meridiani uzunligiga bog‘lab aniqlangan.', 'Напоминание: 1 см = 10 мм, 1 м = 100 см, 1 км = 1000 м. В древности люди пользовались «телесными» единицами — локоть, пядь, шаг; метр же введён во Франции в 1799 году и был привязан к длине земного меридиана.', 'Reminder: 1 cm = 10 mm, 1 m = 100 cm, 1 km = 1000 m. In ancient times people used “body” units such as the cubit, span and pace; the metre was introduced in France in 1799 and was tied to the length of the Earth’s meridian.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), p: [
      L('Mavzu oddiy ko‘rinsa ham, aynan shu yerda ko‘p xato qilinadi.', 'Тема кажется простой, но именно здесь часто ошибаются.', 'The topic looks simple, yet this is exactly where many mistakes happen.')
    ], list: [
      L('<b>To‘g‘ri chiziq va kesmani aralashtirish.</b> To‘g‘ri chiziqning uzunligi yo‘q — u cheksiz. Uzunlik faqat kesmada bor.', '<b>Путать прямую и отрезок.</b> У прямой нет длины — она бесконечна. Длина есть только у отрезка.', '<b>Mixing up a line and a segment.</b> A line has no length — it is infinite. Only a segment has a length.'),
      L('<b>Chizg‘ichni chetidan qo‘yish.</b> Ko‘p chizg‘ichlarda nol chetdan bir oz ichkarida. Doim nol belgisiga qarang.', '<b>Прикладывать линейку краем.</b> На многих линейках ноль смещён от края. Всегда смотрите на деление ноль.', '<b>Placing the ruler by its edge.</b> On many rulers the zero is a little inside the edge. Always look for the zero mark.'),
      L('<b>Nuqtaning joyini tekshirmaslik.</b> «C nuqta AB da yotadi» deyilsa, AB = AC + CB. Agar C kesmadan tashqarida bo‘lsa, formula boshqacha. 3-namunadagi kabi ikki holni ko‘ring.', '<b>Не проверять положение точки.</b> Если сказано «C лежит на AB», то AB = AC + CB. Если C вне отрезка, формула другая. Разбирайте два случая, как в примере 3.', '<b>Not checking where the point is.</b> If “C lies on AB” is given, then AB = AC + CB. If C is outside the segment the formula changes. Consider both cases, as in example 3.'),
      L('<b>Birliklarni aralashtirish.</b> 1 m 20 cm va 35 cm qo‘shishdan oldin ikkalasini santimetrga o‘tkazing: 120 + 35 = 155 cm.', '<b>Смешивать единицы.</b> Прежде чем складывать 1 м 20 см и 35 см, переведите обе длины в сантиметры: 120 + 35 = 155 см.', '<b>Mixing units.</b> Before adding 1 m 20 cm and 35 cm, convert both to centimetres: 120 + 35 = 155 cm.'),
      L('<b>Nurning boshini unutish.</b> OA va AO — turli nurlar! Birinchisining boshi O, ikkinchisiniki A.', '<b>Забывать о начале луча.</b> OA и AO — разные лучи! У первого начало O, у второго — A.', '<b>Forgetting the endpoint of a ray.</b> OA and AO are different rays! The first starts at O, the second at A.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Qurilishda.</b> Usta devorning to‘g‘riligini tortilgan ip bilan tekshiradi — ip ikki nuqta orqali o‘tuvchi yagona to‘g‘ri chiziqni ko‘rsatadi. Lazerli nivelir ham aynan shu aksiomaga asoslangan.', '<b>В строительстве.</b> Мастер проверяет ровность стены натянутым шнуром — шнур показывает единственную прямую, проходящую через две точки. Лазерный нивелир основан на той же аксиоме.', '<b>In building.</b> A builder checks a wall with a stretched string — the string shows the only straight line through two points. A laser level relies on the same axiom.'),
      L('<b>Yo‘lda.</b> Toshkentdan Samarqandgacha 300 km, Samarqanddan Buxorogacha 270 km. Agar shaharlar bir yo‘lda ketma-ket joylashgan bo‘lsa, Toshkent–Buxoro masofasi AB = AC + CB qoidasi bilan topiladi.', '<b>В дороге.</b> От Ташкента до Самарканда 300 км, от Самарканда до Бухары 270 км. Если города лежат на одной дороге друг за другом, расстояние Ташкент–Бухара находится по правилу AB = AC + CB.', '<b>On the road.</b> Tashkent to Samarkand is 300 km, Samarkand to Bukhara is 270 km. If the cities lie one after another on the same road, the Tashkent–Bukhara distance follows from AB = AC + CB.'),
      L('<b>Tikuvchilikda va duradgorlikda.</b> Matoni yoki taxtani teng ikkiga bo‘lish — kesmaning o‘rtasini topish. Usta avval umumiy uzunlikni o‘lchab, ikkiga bo‘ladi.', '<b>В шитье и столярном деле.</b> Разделить ткань или доску пополам — значит найти середину отрезка. Мастер сначала измеряет всю длину, затем делит её на два.', '<b>In sewing and carpentry.</b> Cutting cloth or a board in half means finding the midpoint of a segment. The craftsman measures the whole length first, then halves it.'),
      L('<b>Kompyuter grafikasida.</b> Ekrandagi har bir chiziq ikki nuqtaning koordinatalari bilan beriladi — dastur ular orqali yagona to‘g‘ri chiziqni chizadi.', '<b>В компьютерной графике.</b> Каждая линия на экране задаётся координатами двух точек — программа проводит через них единственную прямую.', '<b>In computer graphics.</b> Every line on a screen is given by the coordinates of two points — the program draws the unique line through them.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Yorug‘lik bir jinsli muhitda to‘g‘ri chiziq bo‘ylab tarqaladi. Shuning uchun soyaning chegarasi to‘g‘ri va lazer nuri «to‘g‘ri chiziq» uchun eng yaxshi namuna.', 'Свет в однородной среде распространяется по прямой. Поэтому граница тени ровная, а луч лазера — лучший образец «прямой».', 'Light travels in a straight line through a uniform medium. That is why a shadow’s edge is straight and a laser beam is the best model of a “line”.'),
      L('<b>Beruniy</b> XI asrda Hindistonda tog‘ cho‘qqisidan ufqqa qarab, Yer radiusini hisoblagan — natijasi hozirgi qiymatdan atigi bir necha foiz farq qiladi. U faqat burchak va kesmalardan foydalangan!', '<b>Беруни</b> в XI веке, наблюдая горизонт с вершины горы в Индии, вычислил радиус Земли — результат отличается от современного всего на несколько процентов. Он использовал только углы и отрезки!', 'In the 11th century <b>Biruni</b>, observing the horizon from a mountain top in India, calculated the radius of the Earth — his result differs from today’s value by only a few percent. He used nothing but angles and segments!'),
      L('Samarqanddagi <b>Ulug‘bek rasadxonasi</b>da (1420-yillar) radiusi 40 metrga yaqin ulkan yoy — sekstant bo‘lgan. Uning har bir gradusi 70 sm ga yaqin bo‘lgani uchun yulduzlar o‘rni juda aniq o‘lchangan.', 'В <b>обсерватории Улугбека</b> в Самарканде (1420-е годы) находилась огромная дуга — секстант радиусом около 40 метров. Каждый градус на ней занимал около 70 см, поэтому положения звёзд измерялись очень точно.', 'The <b>Ulugh Beg observatory</b> in Samarkand (1420s) housed a giant arc, a sextant with a radius of about 40 metres. Each degree on it spanned about 70 cm, so star positions were measured very accurately.'),
      L('Yevklidning «Negizlar»i Injildan keyin eng ko‘p nashr etilgan kitoblardan biri — bir mingdan ortiq nashri bor.', '«Начала» Евклида — одна из самых издаваемых книг после Библии: более тысячи изданий.', 'Euclid’s <i>Elements</i> is one of the most printed books after the Bible, with more than a thousand editions.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), p: [
      L('Javob berishdan oldin chizma chizing — geometriyada chizma yechimning yarmi.', 'Перед ответом сделайте чертёж — в геометрии чертёж уже половина решения.', 'Draw a figure before answering — in geometry a drawing is half the solution.')
    ], list: [
      L('Uchta nuqta orqali nechta to‘g‘ri chiziq o‘tkazish mumkin? Ikki javob toping.', 'Сколько прямых можно провести через три точки? Найдите два ответа.', 'How many lines can be drawn through three points? Find two answers.'),
      L('AB = 18 cm, M — o‘rtasi, K — AM ning o‘rtasi. KB ni toping.', 'AB = 18 см, M — середина, K — середина AM. Найдите KB.', 'AB = 18 cm, M is its midpoint, K is the midpoint of AM. Find KB.'),
      L('To‘rtta to‘g‘ri chiziq ko‘pi bilan nechta nuqtada kesishishi mumkin?', 'В скольких точках могут пересечься четыре прямые (наибольшее число)?', 'What is the largest number of points at which four lines can intersect?'),
      L('Nega to‘g‘ri chiziqni «AB» deb ham, «BA» deb ham atash mumkin, nurni esa — yo‘q?', 'Почему прямую можно назвать и «AB», и «BA», а луч — нет?', 'Why can a line be called both “AB” and “BA”, but a ray cannot?')
    ], after: [
      L('Javoblar: 1) nuqtalar bir chiziqda bo‘lsa — 1, bo‘lmasa — 3. 2) AM = 9, KM = 4,5, KB = 4,5 + 9 = 13,5 cm. 3) 6 ta (har ikki chiziq bittadan). 4) Nurning boshi bor, shuning uchun birinchi harf — bosh nuqta.', 'Ответы: 1) если точки на одной прямой — 1, иначе — 3. 2) AM = 9, KM = 4,5, KB = 4,5 + 9 = 13,5 см. 3) 6 (каждая пара прямых — по одной точке). 4) У луча есть начало, поэтому первая буква — его начало.', 'Answers: 1) if the points are collinear — 1, otherwise — 3. 2) AM = 9, KM = 4.5, KB = 4.5 + 9 = 13.5 cm. 3) 6 (each pair of lines gives one point). 4) A ray has a starting point, so the first letter is its endpoint.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Nuqta, to‘g‘ri chiziq, tekislik — ta’riflanmaydigan boshlang‘ich tushunchalar.', 'Точка, прямая, плоскость — неопределяемые начальные понятия.', 'Point, line and plane are undefined basic ideas.'),
      L('<b>Nur</b> — bir boshi bor, bir tomonga cheksiz; <b>kesma</b> — ikki uchi bor, uzunligi bor.', '<b>Луч</b> имеет начало и бесконечен в одну сторону; <b>отрезок</b> имеет два конца и длину.', 'A <b>ray</b> has one endpoint and is infinite one way; a <b>segment</b> has two endpoints and a length.'),
      L('Aksioma isbotsiz qabul qilinadi, teorema isbotlanadi.', 'Аксиома принимается без доказательства, теорема доказывается.', 'An axiom is accepted without proof; a theorem is proved.'),
      L('Ikki nuqta orqali faqat bitta to‘g‘ri chiziq o‘tadi; ikki to‘g‘ri chiziq ko‘pi bilan bir nuqtada kesishadi.', 'Через две точки проходит только одна прямая; две прямые пересекаются не более чем в одной точке.', 'Exactly one line passes through two points; two lines meet in at most one point.'),
      L('C nuqta AB da yotsa: <b>AB = AC + CB</b>. O‘rta: AM = MB = AB : 2.', 'Если C лежит на AB: <b>AB = AC + CB</b>. Середина: AM = MB = AB : 2.', 'If C lies on AB: <b>AB = AC + CB</b>. Midpoint: AM = MB = AB : 2.'),
      L('O‘lchashda chizg‘ichning nolini uchga qo‘ying va birliklarni bir xil qiling.', 'При измерении ставьте ноль линейки на конец отрезка и приводите единицы к одной.', 'When measuring, put the ruler’s zero on the endpoint and use the same units.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t2. Burchak va uning turlari. Qo‘shni va vertikal burchaklar ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Burchak — ikki nurning uchrashuvi', 'Угол — встреча двух лучей', 'An angle is where two rays meet'), p: [
      L('Qaychini oching — pichoqlari orasida burchak paydo bo‘ladi. Soat millari, ochiq eshik, yo‘l chorrahasi, kitobning ochilgan varag‘i — hammasida burchak bor. Burchak qanchalik «keng» ochilganini biz <b>gradus</b>larda o‘lchaymiz. Bu mavzuda burchak nima, uning turlari qanday va ikkita to‘g‘ri chiziq kesishganda hosil bo‘lgan burchaklar o‘rtasida qanday bog‘lanish borligini o‘rganamiz.', 'Раскройте ножницы — между лезвиями появится угол. Стрелки часов, открытая дверь, перекрёсток дорог, раскрытая книга — везде есть углы. Насколько «широко» раскрыт угол, мы измеряем в <b>градусах</b>. В этой теме узнаем, что такое угол, какие бывают углы и как связаны между собой углы, образованные при пересечении двух прямых.', 'Open a pair of scissors — an angle appears between the blades. Clock hands, an open door, a road junction, an open book — angles are everywhere. How “wide” an angle opens is measured in <b>degrees</b>. In this topic we learn what an angle is, what kinds there are, and how the angles made by two crossing lines are related.'),
      L('Eng qizig‘i — bu mavzuda siz birinchi haqiqiy <b>teorema</b>ni isbotlaysiz: «vertikal burchaklar teng». Isbot atigi uch qatordan iborat, lekin u geometriyaning butun ruhini ko‘rsatadi: biz ko‘zga ishonmaymiz, mantiqqa ishonamiz.', 'Самое интересное — в этой теме вы докажете первую настоящую <b>теорему</b>: «вертикальные углы равны». Доказательство занимает всего три строки, но оно показывает весь дух геометрии: мы верим не глазам, а логике.', 'The most exciting part is that in this topic you will prove your first real <b>theorem</b>: “vertical angles are equal”. The proof takes only three lines, yet it shows the whole spirit of geometry: we trust logic, not our eyes.')
    ] },
    { kind: 'def', h: L('Burchak va uning elementlari', 'Угол и его элементы', 'An angle and its parts'), p: [
      L('<b>Burchak</b> — umumiy boshlang‘ich nuqtadan chiquvchi ikki nurdan iborat shakl. Umumiy nuqta burchakning <b>uchi</b>, nurlar esa <b>tomonlari</b> deyiladi. Belgilanishi: ∠AOB yoki ∠O (uchi o‘rtada yoziladi), ba’zan yunon harflari bilan: α, β, γ.', '<b>Угол</b> — фигура, состоящая из двух лучей с общим началом. Общая точка называется <b>вершиной</b> угла, лучи — его <b>сторонами</b>. Обозначение: ∠AOB или ∠O (вершина пишется в середине), иногда греческими буквами: α, β, γ.', 'An <b>angle</b> is a figure made of two rays with a common endpoint. The common point is the <b>vertex</b> of the angle, the rays are its <b>sides</b>. Notation: ∠AOB or ∠O (the vertex is written in the middle), sometimes Greek letters: α, β, γ.'),
      L('Burchak gradusda o‘lchanadi: yoyiq burchak 180° ga, uning 1/180 qismi 1° ga teng. Gradus 60 minutga (′), minut 60 sekundga (″) bo‘linadi. Burchakni <b>transportir</b> bilan o‘lchaymiz. Teng burchaklar — gradus o‘lchovi teng burchaklar.', 'Угол измеряется в градусах: развёрнутый угол равен 180°, его 1/180 часть — 1°. Градус делится на 60 минут (′), минута — на 60 секунд (″). Угол измеряют <b>транспортиром</b>. Равные углы — углы с равной градусной мерой.', 'Angles are measured in degrees: a straight angle is 180°, and 1/180 of it is 1°. A degree is divided into 60 minutes (′), a minute into 60 seconds (″). We measure angles with a <b>protractor</b>. Equal angles are angles with the same degree measure.')
    ], list: [
      L('<b>O‘tkir</b> burchak: 0° &lt; α &lt; 90°.', '<b>Острый</b> угол: 0° &lt; α &lt; 90°.', '<b>Acute</b> angle: 0° &lt; α &lt; 90°.'),
      L('<b>To‘g‘ri</b> burchak: α = 90°. Chizmada kichik kvadratcha bilan belgilanadi.', '<b>Прямой</b> угол: α = 90°. На чертеже отмечается маленьким квадратиком.', '<b>Right</b> angle: α = 90°. Marked with a small square in drawings.'),
      L('<b>O‘tmas</b> burchak: 90° &lt; α &lt; 180°.', '<b>Тупой</b> угол: 90° &lt; α &lt; 180°.', '<b>Obtuse</b> angle: 90° &lt; α &lt; 180°.'),
      L('<b>Yoyiq</b> burchak: α = 180°, tomonlari bitta to‘g‘ri chiziqni tashkil qiladi.', '<b>Развёрнутый</b> угол: α = 180°, стороны образуют одну прямую.', '<b>Straight</b> angle: α = 180°, the sides form one line.')
    ], after: [
      L('Burchakning ichidan chiqqan nur uni ikki burchakka bo‘ladi va ularning yig‘indisi butun burchakka teng: ∠AOB = ∠AOC + ∠COB. Burchakni teng ikkiga bo‘luvchi nur <b>bissektrisa</b> deyiladi.', 'Луч, выходящий из вершины внутрь угла, делит его на два угла, сумма которых равна всему углу: ∠AOB = ∠AOC + ∠COB. Луч, делящий угол пополам, называется <b>биссектрисой</b>.', 'A ray from the vertex into the angle splits it into two angles whose sum is the whole angle: ∠AOB = ∠AOC + ∠COB. The ray that halves an angle is called the <b>bisector</b>.')
    ] },
    { kind: 'history', h: L('Nega aylana 360 gradus?', 'Почему в окружности 360 градусов?', 'Why does a circle have 360 degrees?'), p: [
      L('Gradus tushunchasi qadimgi <b>Bobil</b>dan kelgan. Bobilliklar 60 lik sanoq sistemasidan foydalanishgan va yil taxminan 360 kun deb hisoblashgan — Quyosh osmonda har kuni taxminan bir «qadam» yurgan. Shuning uchun to‘liq aylanish 360 ga bo‘lingan. 360 soni juda qulay: u 2, 3, 4, 5, 6, 8, 9, 10, 12 ga qoldiqsiz bo‘linadi.', 'Понятие градуса пришло из древнего <b>Вавилона</b>. Вавилоняне пользовались шестидесятеричной системой счисления и считали год равным примерно 360 дням — Солнце каждый день делало на небе примерно один «шаг». Поэтому полный оборот разделили на 360 частей. Число 360 очень удобно: оно делится без остатка на 2, 3, 4, 5, 6, 8, 9, 10, 12.', 'The idea of the degree comes from ancient <b>Babylon</b>. The Babylonians used a base-60 number system and took the year to be about 360 days — the Sun made roughly one “step” across the sky each day. So a full turn was divided into 360 parts. The number 360 is very convenient: it divides evenly by 2, 3, 4, 5, 6, 8, 9, 10 and 12.'),
      L('Yunon olimi <b>Fales</b> (mil. avv. VI asr) vertikal burchaklarning tengligini birinchi bo‘lib isbotlagan deb hisoblanadi — bu tarixdagi eng qadimgi teoremalardan biri. Yevklid «Negizlar»ining birinchi kitobida bu tasdiq 15-teorema sifatida keltirilgan.', 'Считается, что греческий учёный <b>Фалес</b> (VI век до н. э.) первым доказал равенство вертикальных углов — это одна из самых древних теорем в истории. В первой книге «Начал» Евклида это утверждение приведено как предложение 15.', 'The Greek scholar <b>Thales</b> (6th century BC) is believed to be the first to prove that vertical angles are equal — one of the oldest theorems in history. In the first book of Euclid’s <i>Elements</i> this statement appears as Proposition 15.'),
      L('O‘rta Osiyo astronomlari burchaklarni juda aniq o‘lchashgan. <b>Ulug‘bek</b> va uning shogirdlari Samarqand rasadxonasida yil uzunligini bir necha sekund xatolik bilan aniqlagan — buning uchun yulduzlar orasidagi burchaklarni minut va sekundlargacha o‘lchash kerak edi.', 'Астрономы Средней Азии измеряли углы очень точно. <b>Улугбек</b> и его ученики в Самаркандской обсерватории определили длину года с ошибкой в несколько секунд — для этого нужно было измерять углы между звёздами с точностью до минут и секунд.', 'Central Asian astronomers measured angles with great precision. <b>Ulugh Beg</b> and his students at the Samarkand observatory found the length of the year with an error of only a few seconds — for that they had to measure angles between stars down to minutes and seconds.')
    ] },
    { kind: 'rule', h: L('Qo‘shni va vertikal burchaklar', 'Смежные и вертикальные углы', 'Adjacent and vertical angles'), p: [
      L('<b>Qo‘shni burchaklar</b> — bir tomoni umumiy, qolgan ikki tomoni esa bitta to‘g‘ri chiziqni tashkil etuvchi ikki burchak. <b>Teorema:</b> qo‘shni burchaklar yig‘indisi 180° ga teng.', '<b>Смежные углы</b> — два угла, у которых одна сторона общая, а две другие образуют одну прямую. <b>Теорема:</b> сумма смежных углов равна 180°.', '<b>Adjacent (supplementary) angles</b> are two angles that share one side while their other two sides form a line. <b>Theorem:</b> adjacent angles add up to 180°.'),
      L('<i>Isbot g‘oyasi.</i> ∠AOC va ∠COB qo‘shni bo‘lsin. OA va OB nurlar bitta to‘g‘ri chiziqda, demak ∠AOB — yoyiq, ya’ni 180°. OC nuri uni ikki burchakka bo‘ladi: ∠AOC + ∠COB = ∠AOB = 180°. Isbot tugadi.', '<i>Идея доказательства.</i> Пусть ∠AOC и ∠COB смежные. Лучи OA и OB лежат на одной прямой, значит ∠AOB — развёрнутый, то есть 180°. Луч OC делит его на два угла: ∠AOC + ∠COB = ∠AOB = 180°. Доказано.', '<i>Proof idea.</i> Let ∠AOC and ∠COB be adjacent. Rays OA and OB lie on one line, so ∠AOB is a straight angle, 180°. Ray OC splits it into two angles: ∠AOC + ∠COB = ∠AOB = 180°. Done.'),
      L('<b>Vertikal burchaklar</b> — ikki to‘g‘ri chiziq kesishganda hosil bo‘lgan, bir burchakning tomonlari ikkinchisining tomonlarini davom ettiruvchi burchaklar juftligi. <b>Teorema:</b> vertikal burchaklar teng.', '<b>Вертикальные углы</b> — пара углов, образованных при пересечении двух прямых, у которых стороны одного являются продолжениями сторон другого. <b>Теорема:</b> вертикальные углы равны.', '<b>Vertical angles</b> are a pair of angles formed by two crossing lines, where the sides of one are extensions of the sides of the other. <b>Theorem:</b> vertical angles are equal.'),
      L('<i>Isbot g‘oyasi.</i> a va b chiziqlar O nuqtada kesishib, ∠1 va ∠3 vertikal, ∠2 esa ular orasida bo‘lsin. ∠1 va ∠2 — qo‘shni, demak ∠1 = 180° − ∠2. ∠3 va ∠2 ham qo‘shni, demak ∠3 = 180° − ∠2. O‘ng tomonlar bir xil, demak ∠1 = ∠3. Ko‘rdingizmi — qo‘shni burchaklar teoremasidan vertikal burchaklar teoremasi kelib chiqdi!', '<i>Идея доказательства.</i> Пусть прямые a и b пересекаются в точке O, ∠1 и ∠3 — вертикальные, а ∠2 лежит между ними. ∠1 и ∠2 смежные, значит ∠1 = 180° − ∠2. ∠3 и ∠2 тоже смежные, значит ∠3 = 180° − ∠2. Правые части одинаковы, поэтому ∠1 = ∠3. Видите — из теоремы о смежных углах вытекла теорема о вертикальных!', '<i>Proof idea.</i> Let lines a and b meet at O, with ∠1 and ∠3 vertical and ∠2 between them. ∠1 and ∠2 are adjacent, so ∠1 = 180° − ∠2. ∠3 and ∠2 are also adjacent, so ∠3 = 180° − ∠2. The right-hand sides are the same, hence ∠1 = ∠3. See how the vertical-angle theorem follows from the adjacent-angle theorem!')
    ] },
    { kind: 'steps', h: L('Kesishgan chiziqlardagi burchaklarni topish', 'Как найти углы при пересечении прямых', 'Finding the angles at crossing lines'), p: [
      L('Ikki to‘g‘ri chiziq kesishganda to‘rtta burchak hosil bo‘ladi. Bittasi ma’lum bo‘lsa, qolganlarini quyidagicha topamiz:', 'При пересечении двух прямых образуются четыре угла. Если один известен, остальные находим так:', 'Two crossing lines make four angles. If one is known, find the others like this:')
    ], list: [
      L('1-qadam. Ma’lum burchakni chizmada belgilang, deylik ∠1 = α.', 'Шаг 1. Отметьте известный угол на чертеже, скажем ∠1 = α.', 'Step 1. Mark the known angle on the drawing, say ∠1 = α.'),
      L('2-qadam. Unga vertikal bo‘lgan burchak ham α ga teng (teorema).', 'Шаг 2. Вертикальный ему угол тоже равен α (теорема).', 'Step 2. The angle vertical to it also equals α (theorem).'),
      L('3-qadam. Qo‘shni burchaklar 180° − α ga teng. Ular ikkita va o‘zaro vertikal.', 'Шаг 3. Смежные углы равны 180° − α. Их два, и они вертикальны друг другу.', 'Step 3. The adjacent angles equal 180° − α. There are two of them, vertical to each other.'),
      L('4-qadam. Tekshiring: to‘rtta burchak yig‘indisi 360° bo‘lishi kerak: α + α + (180° − α) + (180° − α) = 360°.', 'Шаг 4. Проверьте: сумма четырёх углов должна быть 360°: α + α + (180° − α) + (180° − α) = 360°.', 'Step 4. Check: the four angles must sum to 360°: α + α + (180° − α) + (180° − α) = 360°.'),
      L('Agar burchaklar orasidagi munosabat berilgan bo‘lsa («biri ikkinchisidan 40° katta», «nisbati 2 : 7»), kichigini x deb belgilab, qo‘shni burchaklar uchun tenglama tuzing: x + (x + 40) = 180.', 'Если дано соотношение между углами («один больше другого на 40°», «относятся как 2 : 7»), обозначьте меньший через x и составьте уравнение для смежных углов: x + (x + 40) = 180.', 'If a relation between the angles is given (“one is 40° bigger”, “ratio 2 : 7”), call the smaller one x and write an equation for adjacent angles: x + (x + 40) = 180.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir masalada avval burchaklar qo‘shnimi yoki vertikalmi — shuni aniqlang.', 'В каждой задаче сначала определите: углы смежные или вертикальные.', 'In every problem, first decide whether the angles are adjacent or vertical.')
    ], ex: [
      { q: L('Qo‘shni burchaklardan biri 37°. Ikkinchisini toping.', 'Один из смежных углов равен 37°. Найдите второй.', 'One of two adjacent angles is 37°. Find the other.'), s: L('Qo‘shni burchaklar yig‘indisi 180°. Ikkinchisi: 180° − 37° = <b>143°</b>. Bu o‘tmas burchak.', 'Сумма смежных углов 180°. Второй: 180° − 37° = <b>143°</b>. Это тупой угол.', 'Adjacent angles add to 180°. The other is 180° − 37° = <b>143°</b>. It is obtuse.') },
      { q: L('Qo‘shni burchaklardan biri ikkinchisidan 4 marta katta. Ularni toping.', 'Один из смежных углов в 4 раза больше другого. Найдите их.', 'One adjacent angle is 4 times the other. Find both.'), s: L('Kichigi x bo‘lsin, kattasi 4x. x + 4x = 180, 5x = 180, x = <b>36°</b>. Kattasi: 4 · 36 = <b>144°</b>. Tekshiramiz: 36 + 144 = 180.', 'Пусть меньший x, больший 4x. x + 4x = 180, 5x = 180, x = <b>36°</b>. Больший: 4 · 36 = <b>144°</b>. Проверка: 36 + 144 = 180.', 'Let the smaller be x and the larger 4x. x + 4x = 180, 5x = 180, x = <b>36°</b>. The larger is 4 · 36 = <b>144°</b>. Check: 36 + 144 = 180.') },
      { q: L('Ikki to‘g‘ri chiziq kesishganda hosil bo‘lgan burchaklardan ikkitasining yig‘indisi 100°. To‘rtala burchakni toping.', 'При пересечении двух прямых сумма двух из образовавшихся углов равна 100°. Найдите все четыре угла.', 'Two lines cross; two of the resulting angles add up to 100°. Find all four angles.'), s: L('Yig‘indisi 100° bo‘lgan ikki burchak qo‘shni bo‘la olmaydi (qo‘shnilar 180° beradi), demak ular vertikal va teng: har biri 50°. Qolgan ikkitasi qo‘shni: 180° − 50° = 130°. Javob: <b>50°, 130°, 50°, 130°</b>.', 'Два угла с суммой 100° не могут быть смежными (смежные дают 180°), значит они вертикальные и равны: по 50°. Остальные два — смежные: 180° − 50° = 130°. Ответ: <b>50°, 130°, 50°, 130°</b>.', 'Two angles summing to 100° cannot be adjacent (adjacent ones give 180°), so they are vertical and equal: 50° each. The other two are adjacent: 180° − 50° = 130°. Answer: <b>50°, 130°, 50°, 130°</b>.') },
      { q: L('∠AOB = 120°, OC — uning bissektrisasi. ∠AOC ga qo‘shni burchakni toping.', '∠AOB = 120°, OC — его биссектриса. Найдите угол, смежный с ∠AOC.', '∠AOB = 120° and OC is its bisector. Find the angle adjacent to ∠AOC.'), s: L('Bissektrisa burchakni teng ikkiga bo‘ladi: ∠AOC = 120° : 2 = 60°. Unga qo‘shni burchak: 180° − 60° = <b>120°</b>.', 'Биссектриса делит угол пополам: ∠AOC = 120° : 2 = 60°. Смежный с ним угол: 180° − 60° = <b>120°</b>.', 'The bisector halves the angle: ∠AOC = 120° : 2 = 60°. The angle adjacent to it: 180° − 60° = <b>120°</b>.') }
    ] },
    { kind: 'table', h: L('Burchak turlari jadvali', 'Таблица видов углов', 'Table of angle types'), p: [
      L('Burchakning turini aniqlash uchun uni 90° va 180° bilan taqqoslash kifoya.', 'Чтобы определить вид угла, достаточно сравнить его с 90° и 180°.', 'To identify the type of an angle, compare it with 90° and 180°.')
    ], table: { head: [L('Turi', 'Вид', 'Type'), L('Gradus o‘lchovi', 'Градусная мера', 'Measure'), L('Misol', 'Пример', 'Example'), L('Qo‘shnisi', 'Смежный с ним', 'Its adjacent angle')], rows: [
      [L('o‘tkir', 'острый', 'acute'), L('0° dan 90° gacha', 'от 0° до 90°', 'between 0° and 90°'), '45°', L('o‘tmas (135°)', 'тупой (135°)', 'obtuse (135°)')],
      [L('to‘g‘ri', 'прямой', 'right'), '90°', '90°', L('to‘g‘ri (90°)', 'прямой (90°)', 'right (90°)')],
      [L('o‘tmas', 'тупой', 'obtuse'), L('90° dan 180° gacha', 'от 90° до 180°', 'between 90° and 180°'), '120°', L('o‘tkir (60°)', 'острый (60°)', 'acute (60°)')],
      [L('yoyiq', 'развёрнутый', 'straight'), '180°', '180°', L('0° (burchak yo‘q)', '0° (угла нет)', '0° (no angle)')]
    ] }, after: [
      L('Jadvaldan ko‘rinadi: o‘tkir burchakning qo‘shnisi doim o‘tmas, to‘g‘ri burchakning qo‘shnisi esa yana to‘g‘ri. Bu kichik kuzatish ko‘p masalada vaqtni tejaydi.', 'Из таблицы видно: смежный с острым углом всегда тупой, а смежный с прямым — снова прямой. Это маленькое наблюдение экономит время во многих задачах.', 'The table shows that the angle adjacent to an acute angle is always obtuse, and the one adjacent to a right angle is again right. This small observation saves time in many problems.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), p: [
      L('Burchaklar mavzusidagi xatolarning ko‘pi e’tiborsizlikdan kelib chiqadi.', 'Большинство ошибок в теме углов — от невнимательности.', 'Most mistakes with angles come from carelessness.')
    ], list: [
      L('<b>Qo‘shni va vertikalni aralashtirish.</b> Qo‘shnilar <i>yonma-yon</i>, yig‘indisi 180°. Vertikallar <i>qarama-qarshi</i>, o‘zaro teng.', '<b>Путать смежные и вертикальные.</b> Смежные лежат <i>рядом</i>, их сумма 180°. Вертикальные лежат <i>напротив</i>, они равны.', '<b>Confusing adjacent and vertical.</b> Adjacent angles lie <i>side by side</i> and sum to 180°. Vertical angles lie <i>opposite</i> each other and are equal.'),
      L('<b>Umumiy tomoni bor har qanday burchaklarni qo‘shni deb o‘ylash.</b> Qo‘shni bo‘lishi uchun qolgan ikki tomon bitta to‘g‘ri chiziqda yotishi shart.', '<b>Считать смежными любые углы с общей стороной.</b> Для смежности две другие стороны обязаны лежать на одной прямой.', '<b>Calling any two angles with a common side adjacent.</b> For them to be adjacent, the other two sides must form a line.'),
      L('<b>Transportirni noto‘g‘ri qo‘yish.</b> Markaz — uchda, nol chizig‘i — bir tomonda bo‘lsin. Ichki va tashqi shkalani adashtirmang: o‘tkir burchak 90° dan kichik chiqishi kerak.', '<b>Неверно прикладывать транспортир.</b> Центр — в вершине, нулевая линия — на стороне. Не путайте внутреннюю и внешнюю шкалы: острый угол должен получиться меньше 90°.', '<b>Placing the protractor wrongly.</b> The centre goes on the vertex, the zero line on a side. Don’t mix up the inner and outer scales: an acute angle must come out below 90°.'),
      L('<b>∠AOB ni ∠OAB deb yozish.</b> Uch harfli belgida uchi doim o‘rtada.', '<b>Писать ∠OAB вместо ∠AOB.</b> В трёхбуквенном обозначении вершина всегда посередине.', '<b>Writing ∠OAB instead of ∠AOB.</b> In three-letter notation the vertex is always in the middle.'),
      L('<b>Tenglamada tekshirishni unutish.</b> Qo‘shni burchaklarni topgach, ularni qo‘shib 180° chiqishiga ishonch hosil qiling.', '<b>Забывать проверку.</b> Найдя смежные углы, сложите их и убедитесь, что получилось 180°.', '<b>Skipping the check.</b> After finding adjacent angles, add them and make sure you get 180°.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Chorrahada.</b> Ikki ko‘cha kesishganda to‘rtta burchak hosil bo‘ladi. Agar ulardan biri 70° bo‘lsa, loyihachi qolganlarini o‘lchamasdan biladi: 70°, 110°, 70°, 110°.', '<b>На перекрёстке.</b> Две улицы при пересечении образуют четыре угла. Если один из них 70°, проектировщик знает остальные без измерения: 70°, 110°, 70°, 110°.', '<b>At a crossroads.</b> Two crossing streets make four angles. If one is 70°, the planner knows the rest without measuring: 70°, 110°, 70°, 110°.'),
      L('<b>Bilyardda.</b> Shar bortga qanday burchak ostida kelsa, shunday burchak ostida qaytadi. Shar yo‘lini oldindan hisoblash — bu burchaklar bilan ishlash.', '<b>В бильярде.</b> Под каким углом шар приходит к борту, под таким и отражается. Рассчитать путь шара заранее — значит работать с углами.', '<b>In billiards.</b> A ball bounces off the cushion at the same angle it arrives. Planning the ball’s path means working with angles.'),
      L('<b>Soatda.</b> Soat millari orasidagi burchak: 3:00 da 90°, 6:00 da 180°, 1:00 da 30°. Soat miliga har daqiqada 0,5° aylanadi — bu masalalar olimpiadalarda tez-tez uchraydi.', '<b>На часах.</b> Угол между стрелками: в 3:00 — 90°, в 6:00 — 180°, в 1:00 — 30°. Часовая стрелка поворачивается на 0,5° в минуту — такие задачи часто бывают на олимпиадах.', '<b>On a clock.</b> The angle between the hands: 90° at 3:00, 180° at 6:00, 30° at 1:00. The hour hand turns 0.5° per minute — such problems often appear in competitions.'),
      L('<b>Qaychi va qisqich.</b> Qaychi — ikki kesishgan chiziq. Dastalar orasidagi burchak pichoqlar orasidagi burchakka teng, chunki ular vertikal!', '<b>Ножницы и щипцы.</b> Ножницы — две пересекающиеся прямые. Угол между ручками равен углу между лезвиями, потому что они вертикальные!', '<b>Scissors and tongs.</b> Scissors are two crossing lines. The angle between the handles equals the angle between the blades because they are vertical angles!')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Gradusdan tashqari burchak <b>radian</b>larda ham o‘lchanadi: 180° = π radian. Oliy matematika va fizikada aynan radian ishlatiladi.', 'Кроме градусов, углы измеряют в <b>радианах</b>: 180° = π радиан. В высшей математике и физике используют именно радианы.', 'Besides degrees, angles are measured in <b>radians</b>: 180° = π radians. Higher mathematics and physics use radians.'),
      L('Harbiylar va artilleriyachilar burchakni «ming»larda o‘lchaydi — to‘liq aylana 6000 ga bo‘linadi. Bu masofani tez hisoblash uchun qulay.', 'Военные и артиллеристы измеряют углы в «тысячных» — полный оборот делится на 6000 частей. Это удобно для быстрого расчёта расстояний.', 'Soldiers and gunners measure angles in “mils” — a full turn is divided into 6 000 parts. It is handy for quick distance estimates.'),
      L('Inson ko‘zi ikki nuqtani faqat ular orasidagi burchak taxminan 1′ (bir minut) dan katta bo‘lsa ajrata oladi. Shuning uchun uzoqdagi ikki chiroq bitta bo‘lib ko‘rinadi.', 'Глаз человека различает две точки, только если угол между ними больше примерно 1′ (одной минуты). Поэтому два далёких фонаря сливаются в один.', 'The human eye can separate two points only if the angle between them is more than about 1′ (one minute). That is why two distant lamps look like one.'),
      L('Asalari uyasidagi har bir katakcha 120° li burchaklardan iborat — bu eng kam mum bilan eng ko‘p joy beradigan shakl.', 'Каждая ячейка пчелиных сот состоит из углов по 120° — это форма, дающая больше всего места при наименьшем расходе воска.', 'Every cell of a honeycomb has 120° angles — the shape that gives the most room for the least wax.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), p: [
      L('Chizma chizing va burchaklarni raqamlang — shunda qaysi juft qo‘shni, qaysi juft vertikal ekani darrov ko‘rinadi.', 'Сделайте чертёж и пронумеруйте углы — тогда сразу видно, какие пары смежные, а какие вертикальные.', 'Draw the figure and number the angles — then you can see at once which pairs are adjacent and which are vertical.')
    ], list: [
      L('Qo‘shni burchaklar 3 : 7 nisbatda. Ularni toping.', 'Смежные углы относятся как 3 : 7. Найдите их.', 'Adjacent angles are in the ratio 3 : 7. Find them.'),
      L('Ikki to‘g‘ri chiziq kesishganda hosil bo‘lgan burchaklardan uchtasining yig‘indisi 290°. To‘rtinchisini toping.', 'Сумма трёх из четырёх углов, образованных при пересечении двух прямых, равна 290°. Найдите четвёртый.', 'Three of the four angles made by two crossing lines sum to 290°. Find the fourth.'),
      L('Qo‘shni burchaklarning bissektrisalari orasidagi burchak nechaga teng? Har qanday qo‘shni burchaklar uchun isbotlang.', 'Чему равен угол между биссектрисами смежных углов? Докажите для любых смежных углов.', 'What is the angle between the bisectors of two adjacent angles? Prove it for any adjacent angles.'),
      L('Soat 4:00 ni ko‘rsatganda millar orasidagi burchak nechaga teng? 4:30 da-chi?', 'Чему равен угол между стрелками в 4:00? А в 4:30?', 'What is the angle between the clock hands at 4:00? And at 4:30?')
    ], after: [
      L('Javoblar: 1) 54° va 126°. 2) 360° − 290° = 70°. 3) 90°: bissektrisalar α/2 + β/2 = (α + β)/2 = 180°/2 burchak hosil qiladi. 4) 120°; 4:30 da soat mili 4 va 5 o‘rtasida: 45°.', 'Ответы: 1) 54° и 126°. 2) 360° − 290° = 70°. 3) 90°: биссектрисы образуют угол α/2 + β/2 = (α + β)/2 = 180°/2. 4) 120°; в 4:30 часовая стрелка между 4 и 5: 45°.', 'Answers: 1) 54° and 126°. 2) 360° − 290° = 70°. 3) 90°: the bisectors make an angle of α/2 + β/2 = (α + β)/2 = 180°/2. 4) 120°; at 4:30 the hour hand is between 4 and 5: 45°.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Burchak — umumiy boshli ikki nur; uchi, tomonlari, gradus o‘lchovi bor.', 'Угол — два луча с общим началом; у него есть вершина, стороны и градусная мера.', 'An angle is two rays with a common endpoint; it has a vertex, sides and a degree measure.'),
      L('Turlari: o‘tkir (&lt; 90°), to‘g‘ri (90°), o‘tmas (90°–180°), yoyiq (180°).', 'Виды: острый (&lt; 90°), прямой (90°), тупой (90°–180°), развёрнутый (180°).', 'Types: acute (&lt; 90°), right (90°), obtuse (90°–180°), straight (180°).'),
      L('Bissektrisa burchakni teng ikkiga bo‘ladi.', 'Биссектриса делит угол пополам.', 'The bisector halves an angle.'),
      L('<b>Qo‘shni burchaklar</b>: bir tomoni umumiy, qolganlari to‘g‘ri chiziq; yig‘indisi <b>180°</b>.', '<b>Смежные углы</b>: одна сторона общая, остальные образуют прямую; сумма <b>180°</b>.', '<b>Adjacent angles</b>: one common side, the others form a line; they sum to <b>180°</b>.'),
      L('<b>Vertikal burchaklar</b> teng — bu qo‘shni burchaklar teoremasidan kelib chiqadi.', '<b>Вертикальные углы</b> равны — это следует из теоремы о смежных углах.', '<b>Vertical angles</b> are equal — this follows from the adjacent-angle theorem.'),
      L('Ikki to‘g‘ri chiziq kesishganda faqat ikki xil burchak bor: α va 180° − α.', 'При пересечении двух прямых есть только два разных угла: α и 180° − α.', 'Two crossing lines give only two different angles: α and 180° − α.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t3. Perpendikulyar to‘g‘ri chiziqlar ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('To‘g‘ri burchak hamma joyda', 'Прямой угол повсюду', 'Right angles are everywhere'), p: [
      L('Xonangizga qarang: devor polga, eshik romi ostonaga, daftar varag‘ining qirralari bir-biriga to‘g‘ri burchak ostida uchrashadi. Agar shunday bo‘lmaganida, uylar qiyshayib, javonlardan kitoblar sirpanib tushardi. Ikki to‘g‘ri chiziq to‘g‘ri burchak ostida kesishsa, ular <b>perpendikulyar</b> deyiladi.', 'Посмотрите на комнату: стена встречается с полом, дверная рама — с порогом, края тетрадного листа — друг с другом под прямым углом. Если бы это было не так, дома бы кривились, а книги соскальзывали бы с полок. Если две прямые пересекаются под прямым углом, они называются <b>перпендикулярными</b>.', 'Look around your room: the wall meets the floor, the door frame meets the threshold, the edges of a notebook page meet each other at right angles. If they did not, houses would lean and books would slide off shelves. When two lines cross at a right angle they are called <b>perpendicular</b>.'),
      L('Bu mavzuda perpendikulyarlik ta’rifini, nuqtadan to‘g‘ri chiziqqa perpendikulyar tushirish haqidagi teoremani va «nuqtadan to‘g‘ri chiziqqacha masofa» tushunchasini o‘rganamiz. Shuningdek, nega eng qisqa yo‘l doim perpendikulyar bo‘ylab o‘tishini tushunamiz.', 'В этой теме изучим определение перпендикулярности, теорему о перпендикуляре, опущенном из точки на прямую, и понятие «расстояние от точки до прямой». Также поймём, почему кратчайший путь всегда идёт по перпендикуляру.', 'In this topic we study the definition of perpendicular lines, the theorem about dropping a perpendicular from a point to a line, and the idea of the “distance from a point to a line”. We will also see why the shortest path always runs along the perpendicular.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), p: [
      L('<b>Perpendikulyar to‘g‘ri chiziqlar</b> — to‘g‘ri burchak ostida kesishuvchi ikki to‘g‘ri chiziq. Yozuvi: a ⊥ b. Kesishganda hosil bo‘lgan to‘rtala burchak ham 90° ga teng. Haqiqatan: bittasi 90° bo‘lsa, unga vertikal burchak ham 90°, qo‘shnilari esa 180° − 90° = 90°.', '<b>Перпендикулярные прямые</b> — две прямые, пересекающиеся под прямым углом. Запись: a ⊥ b. Все четыре образовавшихся угла равны 90°. Действительно: если один 90°, то вертикальный ему тоже 90°, а смежные 180° − 90° = 90°.', '<b>Perpendicular lines</b> are two lines that cross at a right angle. Notation: a ⊥ b. All four angles formed are 90°. Indeed, if one is 90°, the vertical angle is also 90°, and the adjacent ones are 180° − 90° = 90°.')
    ], list: [
      L('<b>Perpendikulyar</b> (kesma) — A nuqtadan a to‘g‘ri chiziqqa o‘tkazilgan, a ga perpendikulyar AH kesma. H — <b>perpendikulyar asosi</b>.', '<b>Перпендикуляр</b> (отрезок) — отрезок AH из точки A к прямой a, перпендикулярный a. H — <b>основание перпендикуляра</b>.', 'A <b>perpendicular</b> (segment) is the segment AH from point A to line a that is perpendicular to a. H is the <b>foot of the perpendicular</b>.'),
      L('<b>Og‘ma</b> — A nuqtani a dagi H dan boshqa ixtiyoriy M nuqta bilan tutashtiruvchi kesma.', '<b>Наклонная</b> — отрезок, соединяющий A с любой точкой M прямой a, отличной от H.', 'An <b>oblique</b> (slanted segment) joins A to any point M on a other than H.'),
      L('<b>Nuqtadan to‘g‘ri chiziqqacha masofa</b> — perpendikulyar uzunligi AH.', '<b>Расстояние от точки до прямой</b> — длина перпендикуляра AH.', 'The <b>distance from a point to a line</b> is the length of the perpendicular AH.'),
      L('<b>O‘rta perpendikulyar</b> — kesmaning o‘rtasidan o‘tib, unga perpendikulyar bo‘lgan to‘g‘ri chiziq.', '<b>Серединный перпендикуляр</b> — прямая, проходящая через середину отрезка перпендикулярно ему.', 'The <b>perpendicular bisector</b> is the line through the midpoint of a segment, perpendicular to it.')
    ] },
    { kind: 'history', h: L('Misr arqoni va «uchburchak 3–4–5»', 'Египетская верёвка и «треугольник 3–4–5»', 'The Egyptian rope and the 3–4–5 triangle'), p: [
      L('Qadimgi Misr quruvchilari to‘g‘ri burchakni qanday yasashgan? Rivoyatga ko‘ra, ular arqonga teng oraliqda 12 ta tugun bog‘lashgan. Arqonni 3, 4 va 5 bo‘lakli uchburchak shaklida tortishsa, 3 va 4 bo‘lakli tomonlar orasida aniq to‘g‘ri burchak hosil bo‘lgan. Bu usul bilan piramida asoslari va dalalar burchaklari belgilangan.', 'Как древнеегипетские строители получали прямой угол? По преданию, они завязывали на верёвке 12 узлов на равных расстояниях. Если натянуть верёвку треугольником со сторонами 3, 4 и 5 частей, между сторонами 3 и 4 получался точный прямой угол. Так размечали основания пирамид и углы полей.', 'How did Ancient Egyptian builders make a right angle? According to tradition, they tied 12 knots at equal spacing on a rope. Stretching it into a triangle with sides of 3, 4 and 5 parts gave an exact right angle between the sides of 3 and 4. This is how pyramid bases and field corners were laid out.'),
      L('Keyinchalik <b>Pifagor</b> maktabi bu hodisaning sababini tushuntirib bergan: 3² + 4² = 5². Yevklid «Negizlar»da perpendikulyarni sirkul va chizg‘ich bilan yasash usullarini batafsil bayon qilgan. <b>Al-Xorazmiy</b> esa «Al-jabr» kitobidagi geometrik bo‘limda yer maydonlarini o‘lchashda balandlik — ya’ni perpendikulyar — tushunchasidan foydalangan.', 'Позже школа <b>Пифагора</b> объяснила причину: 3² + 4² = 5². Евклид в «Началах» подробно описал построение перпендикуляра циркулем и линейкой. А <b>аль-Хорезми</b> в геометрическом разделе книги «Аль-джабр» использовал понятие высоты — то есть перпендикуляра — при измерении участков земли.', 'Later the school of <b>Pythagoras</b> explained why: 3² + 4² = 5². Euclid described in detail how to construct a perpendicular with compass and straightedge in the <i>Elements</i>. And <b>al-Khwarizmi</b>, in the geometry section of his <i>Al-jabr</i>, used the idea of a height — that is, a perpendicular — to measure plots of land.')
    ] },
    { kind: 'rule', h: L('Perpendikulyar haqidagi teorema', 'Теорема о перпендикуляре', 'The perpendicular theorem'), p: [
      L('<b>Teorema.</b> To‘g‘ri chiziqda yotmagan nuqtadan bu to‘g‘ri chiziqqa perpendikulyar tushirish mumkin va u <b>yagona</b>.', '<b>Теорема.</b> Из точки, не лежащей на прямой, можно опустить на эту прямую перпендикуляр, и притом <b>только один</b>.', '<b>Theorem.</b> From a point not on a line a perpendicular can be dropped to that line, and it is <b>unique</b>.'),
      L('<i>Mavjudligi (g‘oya).</i> Varaqni a chiziq bo‘ylab buklaymiz, A nuqta qog‘oz ostidan A′ nuqtaga tushadi. AA′ kesma a ni H nuqtada kesadi. Buklash burchaklarni ustma-ust tushirgani uchun ∠AHM = ∠A′HM, ular esa qo‘shni — demak har biri 90°.', '<i>Существование (идея).</i> Перегнём лист по прямой a, точка A отпечатается в точке A′. Отрезок AA′ пересекает a в точке H. При перегибании углы совмещаются, поэтому ∠AHM = ∠A′HM, а они смежные — значит, каждый 90°.', '<i>Existence (idea).</i> Fold the sheet along line a; point A lands on point A′. Segment AA′ crosses a at H. Folding makes the angles coincide, so ∠AHM = ∠A′HM, and they are adjacent — therefore each is 90°.'),
      L('<i>Yagonaligi (teskarisidan faraz).</i> Faraz qilaylik, A dan ikkita perpendikulyar AH va AK tushdi. U holda AHK uchburchakda ikkita to‘g‘ri burchak bo‘lardi: 90° + 90° = 180°, uchinchi burchakka joy qolmaydi. Bunday bo‘lishi mumkin emas, demak perpendikulyar yagona. Bu usul <b>teskarisidan faraz qilib isbotlash</b> deyiladi.', '<i>Единственность (от противного).</i> Допустим, из A опущены два перпендикуляра AH и AK. Тогда в треугольнике AHK было бы два прямых угла: 90° + 90° = 180°, и для третьего угла места не осталось бы. Так быть не может, значит, перпендикуляр единственный. Этот приём называется <b>доказательством от противного</b>.', '<i>Uniqueness (by contradiction).</i> Suppose two perpendiculars AH and AK were dropped from A. Then triangle AHK would have two right angles: 90° + 90° = 180°, leaving no room for the third angle. That is impossible, so the perpendicular is unique. This method is called <b>proof by contradiction</b>.'),
      L('<b>Natija:</b> perpendikulyar har qanday og‘madan qisqa: AH &lt; AM. Shuning uchun masofa sifatida aynan perpendikulyar uzunligi olinadi.', '<b>Следствие:</b> перпендикуляр короче любой наклонной: AH &lt; AM. Поэтому расстоянием считается именно длина перпендикуляра.', '<b>Corollary:</b> the perpendicular is shorter than any oblique: AH &lt; AM. That is why distance is defined as the length of the perpendicular.')
    ] },
    { kind: 'steps', h: L('Perpendikulyarni chizish', 'Как начертить перпендикуляр', 'Drawing a perpendicular'), p: [
      L('Amalda perpendikulyar <b>chizmachilik uchburchagi</b> (go‘nyo) bilan chiziladi:', 'На практике перпендикуляр проводят с помощью <b>чертёжного угольника</b>:', 'In practice a perpendicular is drawn with a <b>set square</b>:')
    ], list: [
      L('1-qadam. Chizg‘ichni a to‘g‘ri chiziq bo‘ylab mahkam qo‘ying.', 'Шаг 1. Плотно приложите линейку вдоль прямой a.', 'Step 1. Hold a ruler firmly along line a.'),
      L('2-qadam. Uchburchakning bir kateti chizg‘ichga tegib tursin.', 'Шаг 2. Приложите угольник одним катетом к линейке.', 'Step 2. Put one short side of the set square against the ruler.'),
      L('3-qadam. Uchburchakni chizg‘ich bo‘ylab ikkinchi kateti A nuqtadan o‘tguncha suring.', 'Шаг 3. Двигайте угольник вдоль линейки, пока второй катет не пройдёт через точку A.', 'Step 3. Slide the set square along the ruler until its other short side passes through A.'),
      L('4-qadam. Ikkinchi katet bo‘ylab A dan a gacha chiziq torting. Kesishish nuqtasi — H.', 'Шаг 4. Проведите линию вдоль второго катета от A до a. Точка пересечения — H.', 'Step 4. Draw along that side from A down to a. The crossing point is H.'),
      L('5-qadam. AH ni o‘lchang — bu A dan a gacha masofa. To‘g‘ri burchakni kvadratcha bilan belgilang.', 'Шаг 5. Измерьте AH — это расстояние от A до a. Отметьте прямой угол квадратиком.', 'Step 5. Measure AH — that is the distance from A to a. Mark the right angle with a small square.')
    ], after: [
      L('Sirkul va chizg‘ich bilan perpendikulyar yasashni 12-mavzuda o‘rganamiz — u yerda go‘nyo ham kerak bo‘lmaydi.', 'Построение перпендикуляра циркулем и линейкой изучим в теме 12 — там не понадобится даже угольник.', 'Constructing a perpendicular with compass and straightedge is covered in topic 12 — there you won’t even need a set square.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har masalada to‘g‘ri burchakni chizmada belgilab oling.', 'В каждой задаче отметьте прямой угол на чертеже.', 'In each problem, mark the right angle on your drawing.')
    ], ex: [
      { q: L('OC ⊥ AB, D nuqta ∠AOC ichida, ∠AOD = 28°. ∠DOC ni toping.', 'OC ⊥ AB, точка D внутри ∠AOC, ∠AOD = 28°. Найдите ∠DOC.', 'OC ⊥ AB, D is inside ∠AOC, ∠AOD = 28°. Find ∠DOC.'), s: L('OC ⊥ AB bo‘lgani uchun ∠AOC = 90°. OD nuri uni bo‘ladi: ∠DOC = 90° − 28° = <b>62°</b>.', 'Так как OC ⊥ AB, ∠AOC = 90°. Луч OD делит его: ∠DOC = 90° − 28° = <b>62°</b>.', 'Since OC ⊥ AB, ∠AOC = 90°. Ray OD splits it: ∠DOC = 90° − 28° = <b>62°</b>.') },
      { q: L('Ikki to‘g‘ri chiziq kesishganda hosil bo‘lgan qo‘shni burchaklar teng. Chiziqlar perpendikulyarmi?', 'Смежные углы, образованные при пересечении двух прямых, равны. Перпендикулярны ли прямые?', 'Two crossing lines form equal adjacent angles. Are the lines perpendicular?'), s: L('Qo‘shnilar yig‘indisi 180°, ular teng — har biri 180° : 2 = 90°. Demak, <b>ha</b>, chiziqlar perpendikulyar.', 'Сумма смежных 180°, они равны — каждый 180° : 2 = 90°. Значит, <b>да</b>, прямые перпендикулярны.', 'Adjacent angles sum to 180° and are equal, so each is 180° : 2 = 90°. So <b>yes</b>, the lines are perpendicular.') },
      { q: L('A nuqtadan a to‘g‘ri chiziqqa AH perpendikulyar va AM og‘ma o‘tkazilgan. AH = 6 cm. AM 5 cm bo‘lishi mumkinmi?', 'Из точки A к прямой a проведены перпендикуляр AH и наклонная AM. AH = 6 см. Может ли AM быть 5 см?', 'From A to line a, perpendicular AH and oblique AM are drawn. AH = 6 cm. Can AM be 5 cm?'), s: L('<b>Yo‘q.</b> Perpendikulyar har qanday og‘madan qisqa, demak AM &gt; 6 cm bo‘lishi shart.', '<b>Нет.</b> Перпендикуляр короче любой наклонной, значит AM &gt; 6 см.', '<b>No.</b> The perpendicular is shorter than any oblique, so AM must be greater than 6 cm.') },
      { q: L('O nuqtadan OA, OB, OC nurlar chiqadi. OA ⊥ OB, ∠BOC = 35° (OC — ∠AOB tashqarisida). ∠AOC ni toping.', 'Из точки O выходят лучи OA, OB, OC. OA ⊥ OB, ∠BOC = 35° (OC вне ∠AOB). Найдите ∠AOC.', 'Rays OA, OB, OC start at O. OA ⊥ OB, ∠BOC = 35° (OC outside ∠AOB). Find ∠AOC.'), s: L('OC tashqarida bo‘lgani uchun burchaklar qo‘shiladi: ∠AOC = 90° + 35° = <b>125°</b>. (Agar OC ichkarida bo‘lganda, 90° − 35° = 55° bo‘lar edi.)', 'Так как OC снаружи, углы складываются: ∠AOC = 90° + 35° = <b>125°</b>. (Если бы OC был внутри, получилось бы 90° − 35° = 55°.)', 'Since OC is outside, the angles add: ∠AOC = 90° + 35° = <b>125°</b>. (If OC were inside, it would be 90° − 35° = 55°.)') }
    ] },
    { kind: 'table', h: L('Perpendikulyar va og‘ma', 'Перпендикуляр и наклонная', 'Perpendicular vs oblique'), table: { head: [L('Xossa', 'Свойство', 'Property'), L('Perpendikulyar AH', 'Перпендикуляр AH', 'Perpendicular AH'), L('Og‘ma AM', 'Наклонная AM', 'Oblique AM')], rows: [
      [L('a bilan burchagi', 'Угол с a', 'Angle with a'), '90°', L('90° emas', 'не 90°', 'not 90°')],
      [L('A nuqtadan nechta', 'Сколько из точки A', 'How many from A'), L('faqat bitta', 'только один', 'exactly one'), L('cheksiz ko‘p', 'бесконечно много', 'infinitely many')],
      [L('Uzunligi', 'Длина', 'Length'), L('eng qisqa', 'наименьшая', 'the shortest'), L('perpendikulyardan uzun', 'длиннее перпендикуляра', 'longer than the perpendicular')],
      [L('Ma’nosi', 'Смысл', 'Meaning'), L('masofa', 'расстояние', 'the distance'), L('ixtiyoriy yo‘l', 'произвольный путь', 'any other path')]
    ] }, after: [
      L('Shuningdek: bitta to‘g‘ri chiziqqa perpendikulyar ikki to‘g‘ri chiziq o‘zaro kesishmaydi. Agar ular kesishganda, kesishish nuqtasidan bitta chiziqqa ikkita perpendikulyar tushgan bo‘lardi — teoremaga zid.', 'А также: две прямые, перпендикулярные одной прямой, не пересекаются. Если бы они пересеклись, из точки пересечения к одной прямой шли бы два перпендикуляра — противоречие с теоремой.', 'Also: two lines perpendicular to the same line never meet. If they did, two perpendiculars would go from the meeting point to one line — contradicting the theorem.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>«Ko‘zga 90° ko‘rinadi» deb hisoblash.</b> Chizmadagi burchak to‘g‘riga o‘xshasa ham, shart bo‘lmasa, uni 90° deb olmang.', '<b>Считать угол прямым «на глаз».</b> Даже если угол на чертеже похож на прямой, без условия не считайте его 90°.', '<b>Assuming 90° “by eye”.</b> Even if an angle looks right, don’t take it as 90° unless it is given.'),
      L('<b>Masofani og‘ma bo‘ylab o‘lchash.</b> Nuqtadan chiziqqacha masofa — faqat perpendikulyar uzunligi.', '<b>Измерять расстояние по наклонной.</b> Расстояние от точки до прямой — только длина перпендикуляра.', '<b>Measuring distance along an oblique.</b> The distance from a point to a line is only the perpendicular’s length.'),
      L('<b>Perpendikulyar va bissektrisani aralashtirish.</b> Perpendikulyar 90° hosil qiladi, bissektrisa esa burchakni yarimlaydi — bular turli narsalar.', '<b>Путать перпендикуляр и биссектрису.</b> Перпендикуляр даёт 90°, а биссектриса делит угол пополам — это разные вещи.', '<b>Confusing a perpendicular with a bisector.</b> A perpendicular makes 90°; a bisector halves an angle — different things.'),
      L('<b>«a ⊥ b, b ⊥ c ⇒ a ⊥ c» deb o‘ylash.</b> Aslida tekislikda bu holda a va c parallel bo‘ladi.', '<b>Думать, что «a ⊥ b, b ⊥ c ⇒ a ⊥ c».</b> На самом деле на плоскости в этом случае a и c параллельны.', '<b>Thinking “a ⊥ b, b ⊥ c ⇒ a ⊥ c”.</b> In fact, in a plane a and c are then parallel.'),
      L('<b>Nurning joyini hisobga olmaslik.</b> 4-namunadagidek, nur burchak ichida yoki tashqarisida bo‘lishiga qarab javob o‘zgaradi.', '<b>Не учитывать положение луча.</b> Как в примере 4, ответ зависит от того, лежит луч внутри угла или снаружи.', '<b>Ignoring where the ray lies.</b> As in example 4, the answer changes depending on whether the ray is inside or outside the angle.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Qurilishda.</b> Shoqul (ip uchidagi yuk) vertikalni, suv sathi esa gorizontalni ko‘rsatadi — ular doim perpendikulyar. Usta devor shoqulga mos ekanini tekshiradi.', '<b>В строительстве.</b> Отвес (груз на нити) показывает вертикаль, уровень воды — горизонталь, и они всегда перпендикулярны. Мастер проверяет стену по отвесу.', '<b>In building.</b> A plumb line (a weight on a string) shows the vertical, a water level shows the horizontal — they are always perpendicular. The builder checks a wall against the plumb line.'),
      L('<b>Piyoda yo‘lida.</b> Ko‘chani eng qisqa yo‘l bilan kesib o‘tish — perpendikulyar bo‘ylab yurish. Shuning uchun piyodalar o‘tish joylari yo‘lga perpendikulyar chiziladi: yo‘lda kamroq vaqt o‘tkazasiz.', '<b>На пешеходном переходе.</b> Пересечь улицу кратчайшим путём — значит идти по перпендикуляру. Поэтому переходы размечают перпендикулярно дороге: вы меньше времени проводите на проезжей части.', '<b>At a crossing.</b> Crossing a street by the shortest path means walking along the perpendicular. That is why crossings are painted perpendicular to the road: you spend less time in traffic.'),
      L('<b>Xaritada.</b> Toshkent ko‘chalari ko‘p joyda to‘rsimon — bir-biriga perpendikulyar. Koordinata tekisligidagi x va y o‘qlari ham perpendikulyar.', '<b>На карте.</b> Улицы многих районов Ташкента образуют сетку — перпендикулярны друг другу. Оси x и y координатной плоскости тоже перпендикулярны.', '<b>On a map.</b> Streets in many parts of Tashkent form a grid of perpendicular lines. The x- and y-axes of the coordinate plane are perpendicular too.'),
      L('<b>Sportda.</b> Futbol maydonining chiziqlari, basketbol savatining ustuni, yengil atletika yo‘lakchalarining start chizig‘i — hammasi perpendikulyar qilib belgilanadi. Hakamlar ham to‘pning chiziqdan o‘tganini perpendikulyar bo‘ylab qarab aniqlashadi.', '<b>В спорте.</b> Линии футбольного поля, стойка баскетбольного кольца, линия старта на беговых дорожках — всё размечается перпендикулярно. Судьи тоже определяют, пересёк ли мяч линию, глядя вдоль перпендикуляра.', '<b>In sport.</b> The lines of a football pitch, the post of a basketball hoop, the start line on a running track are all marked perpendicular. Referees also judge whether the ball crossed a line by looking along the perpendicular.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Yer tortish kuchi doim Yer sirtiga perpendikulyar yo‘nalgan. Shuning uchun turli shaharlardagi shoqullar aslida parallel emas — ular Yer markaziga qarab yo‘nalgan.', 'Сила тяжести всегда направлена перпендикулярно поверхности Земли. Поэтому отвесы в разных городах на самом деле не параллельны — они направлены к центру Земли.', 'Gravity always points perpendicular to the Earth’s surface. So plumb lines in different cities are not truly parallel — they all point toward the Earth’s centre.'),
      L('Pizadagi qiya minora vertikaldan taxminan 4° ga og‘gan. Agar perpendikulyar qurilganda, u turistlar uchun bunchalik qiziq bo‘lmasdi!', 'Пизанская башня отклонена от вертикали примерно на 4°. Если бы её построили перпендикулярно земле, она не была бы так интересна туристам!', 'The Leaning Tower of Pisa tilts about 4° from the vertical. Had it been built perpendicular to the ground, tourists would find it far less interesting!'),
      L('Yorug‘lik ko‘zguga perpendikulyar tushsa, o‘sha yo‘l bo‘ylab ortga qaytadi. Oyga o‘rnatilgan ko‘zgularga lazer yuborib, olimlar Oygacha masofani santimetrlar aniqligida o‘lchaydi.', 'Если свет падает на зеркало перпендикулярно, он возвращается по тому же пути. Посылая лазер на зеркала, установленные на Луне, учёные измеряют расстояние до неё с точностью до сантиметров.', 'Light hitting a mirror perpendicularly returns along the same path. By sending lasers to mirrors left on the Moon, scientists measure its distance to within centimetres.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('a ⊥ b. Ular hosil qilgan burchaklardan birining bissektrisasi a bilan qanday burchak hosil qiladi?', 'a ⊥ b. Какой угол образует с a биссектриса одного из образовавшихся углов?', 'a ⊥ b. What angle does the bisector of one of the angles make with a?'),
      L('Bir nuqtadan to‘rtta nur chiqqan: OA ⊥ OC, OB ⊥ OD, ∠AOB = 30°. ∠COD ni toping (B va C ∠AOD ichida).', 'Из одной точки выходят четыре луча: OA ⊥ OC, OB ⊥ OD, ∠AOB = 30°. Найдите ∠COD (B и C внутри ∠AOD).', 'Four rays start at O: OA ⊥ OC, OB ⊥ OD, ∠AOB = 30°. Find ∠COD (B and C inside ∠AOD).'),
      L('Qog‘ozni buklab, chizg‘ichsiz va go‘nyosiz to‘g‘ri burchak qanday hosil qilinadi?', 'Как получить прямой угол, перегибая бумагу, без линейки и угольника?', 'How can you make a right angle just by folding paper, without a ruler or set square?')
    ], after: [
      L('Javoblar: 1) 45°. 2) ∠BOC = 90° − 30° = 60°, ∠COD = 90° − 60° = 30°. 3) Varaqni bir marta buklang, so‘ng bukilgan chiziqni o‘zi ustiga tushadigan qilib yana buklang — burchak 180° : 2 = 90°.', 'Ответы: 1) 45°. 2) ∠BOC = 90° − 30° = 60°, ∠COD = 90° − 60° = 30°. 3) Сложите лист один раз, затем сложите ещё раз так, чтобы линия сгиба легла сама на себя, — угол 180° : 2 = 90°.', 'Answers: 1) 45°. 2) ∠BOC = 90° − 30° = 60°, ∠COD = 90° − 60° = 30°. 3) Fold the sheet once, then fold again so the crease lies on itself — the angle is 180° : 2 = 90°.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('To‘g‘ri burchak ostida kesishgan chiziqlar perpendikulyar: a ⊥ b; to‘rtala burchak 90°.', 'Прямые, пересекающиеся под прямым углом, перпендикулярны: a ⊥ b; все четыре угла по 90°.', 'Lines crossing at a right angle are perpendicular: a ⊥ b; all four angles are 90°.'),
      L('Nuqtadan to‘g‘ri chiziqqa perpendikulyar mavjud va yagona (teskarisidan faraz bilan isbotlanadi).', 'Перпендикуляр из точки к прямой существует и единственен (доказывается от противного).', 'The perpendicular from a point to a line exists and is unique (proved by contradiction).'),
      L('Perpendikulyar har qanday og‘madan qisqa; uning uzunligi — nuqtadan to‘g‘ri chiziqqacha masofa.', 'Перпендикуляр короче любой наклонной; его длина — расстояние от точки до прямой.', 'The perpendicular is shorter than any oblique; its length is the distance from the point to the line.'),
      L('Bir chiziqqa perpendikulyar ikki chiziq kesishmaydi.', 'Две прямые, перпендикулярные одной, не пересекаются.', 'Two lines perpendicular to the same line do not meet.'),
      L('Perpendikulyar go‘nyo bilan yoki sirkul va chizg‘ich bilan yasaladi.', 'Перпендикуляр проводят угольником или строят циркулем и линейкой.', 'A perpendicular is drawn with a set square or constructed with compass and straightedge.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t4. Uchburchak, uning turlari va elementlari ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Eng mustahkam shakl', 'Самая прочная фигура', 'The strongest shape'), p: [
      L('To‘rtta tayoqchani mixlab kvadrat yasang va bir burchagidan bosing — u osongina qiyshayib, romb shakliga kirib qoladi. Endi uchta tayoqchadan uchburchak yasang — uni qancha bossangiz ham shakli o‘zgarmaydi. Shuning uchun ko‘priklar, minoralar, kran strelalari, velosiped ramalari uchburchaklardan quriladi. Uchburchak — geometriyaning eng muhim va eng ko‘p o‘rganiladigan shakli.', 'Сколотите квадрат из четырёх реек и надавите на угол — он легко перекосится и станет ромбом. А теперь соберите треугольник из трёх реек — как ни дави, форма не меняется. Поэтому мосты, вышки, стрелы кранов и рамы велосипедов строят из треугольников. Треугольник — самая важная и самая изучаемая фигура геометрии.', 'Nail four sticks into a square and press on a corner — it easily skews into a rhombus. Now make a triangle from three sticks — however hard you press, its shape does not change. That is why bridges, towers, crane arms and bicycle frames are built from triangles. The triangle is the most important and most studied figure in geometry.'),
      L('Bu mavzuda uchburchakning elementlarini (uchlari, tomonlari, burchaklari), uning turlarini va uchta muhim kesmasini — <b>mediana</b>, <b>bissektrisa</b> va <b>balandlik</b>ni o‘rganamiz. Keyingi barcha mavzular shu tushunchalarga tayanadi, shuning uchun ularni yaxshi eslab qoling.', 'В этой теме изучим элементы треугольника (вершины, стороны, углы), его виды и три важных отрезка — <b>медиану</b>, <b>биссектрису</b> и <b>высоту</b>. Все следующие темы опираются на эти понятия, поэтому запомните их хорошо.', 'In this topic we study the parts of a triangle (vertices, sides, angles), its types, and three important segments: the <b>median</b>, the <b>angle bisector</b> and the <b>altitude</b>. Every later topic relies on these ideas, so learn them well.')
    ] },
    { kind: 'def', h: L('Uchburchak va uning elementlari', 'Треугольник и его элементы', 'A triangle and its parts'), p: [
      L('<b>Uchburchak</b> — bir to‘g‘ri chiziqda yotmagan uchta nuqta va ularni juft-jufti bilan tutashtiruvchi uchta kesmadan iborat shakl. Nuqtalar — <b>uchlari</b> (A, B, C), kesmalar — <b>tomonlari</b> (AB, BC, CA). Belgilanishi: △ABC. Uchburchakning uchta burchagi bor: ∠A, ∠B, ∠C. Tomon va unga qarama-qarshi uch: BC tomon A uchga <b>qarshi</b> yotadi. Barcha tomonlar yig‘indisi — <b>perimetr</b>: P = AB + BC + CA.', '<b>Треугольник</b> — фигура из трёх точек, не лежащих на одной прямой, и трёх отрезков, попарно их соединяющих. Точки — <b>вершины</b> (A, B, C), отрезки — <b>стороны</b> (AB, BC, CA). Обозначение: △ABC. У треугольника три угла: ∠A, ∠B, ∠C. Сторона BC лежит <b>против</b> вершины A. Сумма всех сторон — <b>периметр</b>: P = AB + BC + CA.', 'A <b>triangle</b> is a figure made of three points not on one line and the three segments joining them in pairs. The points are its <b>vertices</b> (A, B, C), the segments its <b>sides</b> (AB, BC, CA). Notation: △ABC. A triangle has three angles: ∠A, ∠B, ∠C. Side BC lies <b>opposite</b> vertex A. The sum of all sides is the <b>perimeter</b>: P = AB + BC + CA.')
    ], list: [
      L('<b>Mediana</b> — uchni qarshi tomonning o‘rtasi bilan tutashtiruvchi kesma. AM mediana bo‘lsa, BM = MC.', '<b>Медиана</b> — отрезок, соединяющий вершину с серединой противоположной стороны. Если AM — медиана, то BM = MC.', 'A <b>median</b> joins a vertex to the midpoint of the opposite side. If AM is a median, BM = MC.'),
      L('<b>Bissektrisa</b> — burchakni teng ikkiga bo‘luvchi, uchdan qarshi tomongacha bo‘lgan kesma. AL bissektrisa bo‘lsa, ∠BAL = ∠LAC.', '<b>Биссектриса</b> — отрезок от вершины до противоположной стороны, делящий угол пополам. Если AL — биссектриса, то ∠BAL = ∠LAC.', 'An <b>angle bisector</b> is the segment from a vertex to the opposite side that halves the angle. If AL is a bisector, ∠BAL = ∠LAC.'),
      L('<b>Balandlik</b> — uchdan qarshi tomon yotgan to‘g‘ri chiziqqa tushirilgan perpendikulyar. AH balandlik bo‘lsa, AH ⊥ BC.', '<b>Высота</b> — перпендикуляр, опущенный из вершины на прямую, содержащую противоположную сторону. Если AH — высота, то AH ⊥ BC.', 'An <b>altitude</b> is the perpendicular dropped from a vertex to the line containing the opposite side. If AH is an altitude, AH ⊥ BC.')
    ], after: [
      L('Har bir uchburchakda uchtadan mediana, bissektrisa va balandlik bor. Ajoyib fakt: uchta mediana bitta nuqtada kesishadi (uchburchakning og‘irlik markazi), uchta bissektrisa ham bir nuqtada, uchta balandlik (yoki ularning davomi) ham bir nuqtada kesishadi. Bularni yuqori sinflarda isbotlaysiz.', 'В каждом треугольнике по три медианы, биссектрисы и высоты. Замечательный факт: три медианы пересекаются в одной точке (центре тяжести треугольника), три биссектрисы — тоже в одной точке, и три высоты (или их продолжения) — тоже. Это вы докажете в старших классах.', 'Every triangle has three medians, three bisectors and three altitudes. A remarkable fact: the three medians meet at one point (the triangle’s centre of mass), the three bisectors meet at one point, and the three altitudes (or their extensions) meet at one point too. You will prove these in later grades.')
    ] },
    { kind: 'history', h: L('Uchburchak tarixda', 'Треугольник в истории', 'The triangle in history'), p: [
      L('Misr piramidalarining yon yoqlari — ulkan uchburchaklar. Yunon olimi <b>Fales</b> piramida balandligini o‘lchash uchun o‘z soyasi bo‘yiga teng bo‘lgan paytni kutgan: aynan o‘sha paytda piramida soyasi ham uning balandligiga teng bo‘lgan. Bu o‘xshash uchburchaklar g‘oyasidan foydalanishning eng mashhur namunasi.', 'Боковые грани египетских пирамид — огромные треугольники. Греческий учёный <b>Фалес</b>, чтобы измерить высоту пирамиды, дождался момента, когда его тень сравнялась с его ростом: в этот момент и тень пирамиды равнялась её высоте. Это самый знаменитый пример использования идеи подобных треугольников.', 'The faces of Egyptian pyramids are giant triangles. To measure a pyramid’s height, the Greek scholar <b>Thales</b> waited for the moment his own shadow equalled his height: at that moment the pyramid’s shadow also equalled its height. This is the most famous example of using the idea of similar triangles.'),
      L('Yevklid «Negizlar»ining birinchi kitobi deyarli butunlay uchburchaklarga bag‘ishlangan. O‘rta asrlarda <b>Beruniy</b> va <b>Nasiriddin Tusiy</b> uchburchaklar haqidagi bilimlarni trigonometriyaga aylantirdilar — tomonlar va burchaklar orasidagi aniq hisob-kitoblar fani. <b>Ulug‘bek</b> rasadxonasida tuzilgan sinuslar jadvali o‘z davrining eng aniq jadvallaridan biri bo‘lgan.', 'Первая книга «Начал» Евклида почти целиком посвящена треугольникам. В Средние века <b>Беруни</b> и <b>Насир ад-Дин Туси</b> превратили знания о треугольниках в тригонометрию — науку о точных расчётах сторон и углов. Таблица синусов, составленная в обсерватории <b>Улугбека</b>, была одной из самых точных в своё время.', 'The first book of Euclid’s <i>Elements</i> is almost entirely about triangles. In the Middle Ages <b>Biruni</b> and <b>Nasir al-Din al-Tusi</b> turned knowledge of triangles into trigonometry, the science of exact calculations with sides and angles. The sine table made at <b>Ulugh Beg</b>’s observatory was one of the most accurate of its time.')
    ] },
    { kind: 'rule', h: L('Uchburchak turlari', 'Виды треугольников', 'Types of triangles'), p: [
      L('Uchburchaklar ikki belgi bo‘yicha turlarga ajratiladi. <b>Burchaklari bo‘yicha:</b>', 'Треугольники делят на виды по двум признакам. <b>По углам:</b>', 'Triangles are classified in two ways. <b>By angles:</b>')
    ], list: [
      L('<b>O‘tkir burchakli</b> — uchala burchagi o‘tkir.', '<b>Остроугольный</b> — все три угла острые.', '<b>Acute</b> — all three angles are acute.'),
      L('<b>To‘g‘ri burchakli</b> — bitta burchagi 90°. To‘g‘ri burchak qarshisidagi tomon — <b>gipotenuza</b>, qolgan ikkitasi — <b>katetlar</b>.', '<b>Прямоугольный</b> — один угол 90°. Сторона против прямого угла — <b>гипотенуза</b>, две другие — <b>катеты</b>.', '<b>Right</b> — one angle is 90°. The side opposite the right angle is the <b>hypotenuse</b>; the other two are the <b>legs</b>.'),
      L('<b>O‘tmas burchakli</b> — bitta burchagi o‘tmas.', '<b>Тупоугольный</b> — один угол тупой.', '<b>Obtuse</b> — one angle is obtuse.'),
      L('<b>Tomonlari bo‘yicha:</b> <b>turli tomonli</b> (hamma tomonlar har xil), <b>teng yonli</b> (ikki tomoni teng), <b>teng tomonli</b> (uchala tomoni teng).', '<b>По сторонам:</b> <b>разносторонний</b> (все стороны разные), <b>равнобедренный</b> (две стороны равны), <b>равносторонний</b> (все три стороны равны).', '<b>By sides:</b> <b>scalene</b> (all sides different), <b>isosceles</b> (two sides equal), <b>equilateral</b> (all three sides equal).')
    ], after: [
      L('Nima uchun uchburchakda ikkita to‘g‘ri yoki ikkita o‘tmas burchak bo‘lishi mumkin emas? Chunki keyinroq isbotlaymizki, uchburchak burchaklari yig‘indisi 180°. Ikki to‘g‘ri burchakning o‘zi 180° ni egallaydi. Teng tomonli uchburchak — teng yonlining xususiy holi: unda istalgan ikki tomon teng.', 'Почему в треугольнике не может быть двух прямых или двух тупых углов? Потому что, как мы позже докажем, сумма углов треугольника равна 180°. Два прямых угла уже занимают все 180°. Равносторонний треугольник — частный случай равнобедренного: в нём равны любые две стороны.', 'Why can’t a triangle have two right or two obtuse angles? Because, as we will prove later, the angles of a triangle add up to 180°. Two right angles alone already take all 180°. An equilateral triangle is a special isosceles triangle: any two of its sides are equal.')
    ] },
    { kind: 'steps', h: L('Mediana, bissektrisa va balandlikni chizish', 'Как провести медиану, биссектрису и высоту', 'Drawing a median, bisector and altitude'), list: [
      L('<b>Mediana AM.</b> BC tomonni chizg‘ich bilan o‘lchang, uzunlikni ikkiga bo‘lib, o‘rtasi M ni belgilang. A ni M bilan tutashtiring.', '<b>Медиана AM.</b> Измерьте сторону BC линейкой, разделите длину пополам и отметьте середину M. Соедините A с M.', '<b>Median AM.</b> Measure side BC with a ruler, halve the length and mark the midpoint M. Join A to M.'),
      L('<b>Bissektrisa AL.</b> ∠A ni transportir bilan o‘lchang, yarmini hisoblang. AB tomondan shu burchakni qo‘yib, nur o‘tkazing; u BC ni L nuqtada kesadi.', '<b>Биссектриса AL.</b> Измерьте ∠A транспортиром, найдите половину. Отложите этот угол от стороны AB и проведите луч; он пересечёт BC в точке L.', '<b>Bisector AL.</b> Measure ∠A with a protractor and halve it. Lay off that angle from side AB and draw a ray; it meets BC at L.'),
      L('<b>Balandlik AH.</b> Go‘nyoni bir kateti BC bo‘ylab, ikkinchisi A dan o‘tadigan qilib qo‘ying va chiziq torting. O‘tmas burchakli uchburchakda BC ni davom ettirish kerak bo‘lishi mumkin — balandlik uchburchakdan tashqariga tushadi.', '<b>Высота AH.</b> Приложите угольник одним катетом вдоль BC так, чтобы другой проходил через A, и проведите линию. В тупоугольном треугольнике может понадобиться продолжить BC — высота упадёт вне треугольника.', '<b>Altitude AH.</b> Place a set square with one side along BC and the other through A, and draw the line. In an obtuse triangle you may need to extend BC — the altitude then falls outside the triangle.'),
      L('Tekshiruv: mediana tomonni teng bo‘ladi, bissektrisa burchakni teng bo‘ladi, balandlik 90° hosil qiladi. Uchala kesmaning nomini chizmaga yozib qo‘ying.', 'Проверка: медиана делит сторону пополам, биссектриса — угол пополам, высота образует 90°. Подпишите все три отрезка на чертеже.', 'Check: the median halves the side, the bisector halves the angle, the altitude makes 90°. Label all three segments on the drawing.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir masalada qaysi kesma haqida gap ketayotganini avval aniqlang.', 'В каждой задаче сначала определите, о каком отрезке идёт речь.', 'In every problem, first decide which segment it is about.')
    ], ex: [
      { q: L('△ABC da AM — mediana, BC = 16 cm. BM va MC ni toping.', 'В △ABC AM — медиана, BC = 16 см. Найдите BM и MC.', 'In △ABC, AM is a median and BC = 16 cm. Find BM and MC.'), s: L('Mediana qarshi tomonni teng ikkiga bo‘ladi: BM = MC = 16 : 2 = <b>8 cm</b>.', 'Медиана делит противоположную сторону пополам: BM = MC = 16 : 2 = <b>8 см</b>.', 'A median halves the opposite side: BM = MC = 16 : 2 = <b>8 cm</b>.') },
      { q: L('BD — △ABC ning bissektrisasi, ∠ABD = 34°. ∠B ni toping.', 'BD — биссектриса △ABC, ∠ABD = 34°. Найдите ∠B.', 'BD is the bisector of △ABC and ∠ABD = 34°. Find ∠B.'), s: L('Bissektrisa ∠B ni ikkita teng burchakka bo‘ladi: ∠B = 2 · 34° = <b>68°</b>.', 'Биссектриса делит ∠B на два равных угла: ∠B = 2 · 34° = <b>68°</b>.', 'The bisector splits ∠B into two equal angles: ∠B = 2 · 34° = <b>68°</b>.') },
      { q: L('Uchburchak perimetri 45 cm, tomonlari 2 : 3 : 4 nisbatda. Tomonlarni toping va uchburchak turini aniqlang (tomonlari bo‘yicha).', 'Периметр треугольника 45 см, стороны относятся как 2 : 3 : 4. Найдите стороны и определите вид треугольника по сторонам.', 'A triangle’s perimeter is 45 cm and its sides are in the ratio 2 : 3 : 4. Find the sides and its type by sides.'), s: L('Jami 2 + 3 + 4 = 9 ulush, bir ulush 45 : 9 = 5 cm. Tomonlar: <b>10, 15, 20 cm</b>. Hammasi har xil — <b>turli tomonli</b> uchburchak.', 'Всего 2 + 3 + 4 = 9 частей, одна часть 45 : 9 = 5 см. Стороны: <b>10, 15, 20 см</b>. Все разные — треугольник <b>разносторонний</b>.', 'Total 2 + 3 + 4 = 9 parts; one part is 45 : 9 = 5 cm. Sides: <b>10, 15, 20 cm</b>. All different — a <b>scalene</b> triangle.') },
      { q: L('AH — △ABC ning balandligi, H nuqta BC da yotadi, ∠BAH = 25°. ∠ABC ni toping.', 'AH — высота △ABC, H лежит на BC, ∠BAH = 25°. Найдите ∠ABC.', 'AH is an altitude of △ABC, H lies on BC, ∠BAH = 25°. Find ∠ABC.'), s: L('ABH uchburchakda ∠AHB = 90°. To‘g‘ri burchakli uchburchakda o‘tkir burchaklar yig‘indisi 90° (buni 9–10-mavzularda isbotlaymiz): ∠ABC = 90° − 25° = <b>65°</b>.', 'В треугольнике ABH ∠AHB = 90°. В прямоугольном треугольнике сумма острых углов 90° (это докажем в темах 9–10): ∠ABC = 90° − 25° = <b>65°</b>.', 'In triangle ABH, ∠AHB = 90°. In a right triangle the acute angles add to 90° (proved in topics 9–10): ∠ABC = 90° − 25° = <b>65°</b>.') }
    ] },
    { kind: 'table', h: L('Uch muhim kesma', 'Три важных отрезка', 'Three key segments'), table: { head: [L('Kesma', 'Отрезок', 'Segment'), L('Qayerdan', 'Откуда', 'From'), L('Qayerga', 'Куда', 'To'), L('Asosiy xossa', 'Главное свойство', 'Key property')], rows: [
      [L('mediana', 'медиана', 'median'), L('uch', 'вершина', 'vertex'), L('qarshi tomon o‘rtasi', 'середина противоп. стороны', 'midpoint of opposite side'), L('tomonni teng bo‘ladi', 'делит сторону пополам', 'halves the side')],
      [L('bissektrisa', 'биссектриса', 'bisector'), L('uch', 'вершина', 'vertex'), L('qarshi tomon', 'противоп. сторона', 'opposite side'), L('burchakni teng bo‘ladi', 'делит угол пополам', 'halves the angle')],
      [L('balandlik', 'высота', 'altitude'), L('uch', 'вершина', 'vertex'), L('qarshi tomon to‘g‘ri chizig‘i', 'прямая противоп. стороны', 'line of opposite side'), L('unga perpendikulyar', 'перпендикулярна ей', 'perpendicular to it')]
    ] }, after: [
      L('Odatda uchala kesma turli chiziqlar. Ammo teng yonli uchburchakda asosga tushirilgan mediana, bissektrisa va balandlik ustma-ust tushadi — buni 6-mavzuda isbotlaymiz. To‘g‘ri burchakli uchburchakda esa ikki katet bir vaqtda balandlik ham bo‘ladi.', 'Обычно эти три отрезка — разные линии. Но в равнобедренном треугольнике медиана, биссектриса и высота к основанию совпадают — это докажем в теме 6. А в прямоугольном треугольнике два катета одновременно являются высотами.', 'Usually the three segments are different lines. But in an isosceles triangle the median, bisector and altitude to the base coincide — we prove this in topic 6. In a right triangle the two legs are also altitudes.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Medianani bissektrisa bilan adashtirish.</b> Mediana <i>tomonni</i>, bissektrisa <i>burchakni</i> teng bo‘ladi. Ular faqat maxsus hollarda ustma-ust tushadi.', '<b>Путать медиану с биссектрисой.</b> Медиана делит пополам <i>сторону</i>, биссектриса — <i>угол</i>. Совпадают они лишь в особых случаях.', '<b>Confusing a median with a bisector.</b> A median halves a <i>side</i>, a bisector halves an <i>angle</i>. They coincide only in special cases.'),
      L('<b>Balandlikni doim uchburchak ichida deb o‘ylash.</b> O‘tmas burchakli uchburchakda ikki balandlik tashqariga tushadi.', '<b>Думать, что высота всегда внутри.</b> В тупоугольном треугольнике две высоты лежат снаружи.', '<b>Thinking an altitude is always inside.</b> In an obtuse triangle two altitudes fall outside.'),
      L('<b>Bir to‘g‘ri chiziqdagi uch nuqtani uchburchak deb hisoblash.</b> Uchburchak bo‘lishi uchun uchlari bir chiziqda yotmasligi shart.', '<b>Считать треугольником три точки на одной прямой.</b> Вершины треугольника не должны лежать на одной прямой.', '<b>Calling three collinear points a triangle.</b> A triangle’s vertices must not lie on one line.'),
      L('<b>Perimetrda bitta tomonni unutish.</b> Teng yonli uchburchakda yon tomonni ikki marta qo‘shing: P = 2a + b.', '<b>Забыть сторону в периметре.</b> В равнобедренном треугольнике боковую сторону берите дважды: P = 2a + b.', '<b>Forgetting a side in the perimeter.</b> In an isosceles triangle count the leg twice: P = 2a + b.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Muhandislikda.</b> Temir yo‘l ko‘priklari, elektr uzatish minoralari va Eyfel minorasi uchburchak shaklidagi fermalardan iborat. Uchburchak qattiq — yuk ostida shakli buzilmaydi.', '<b>В инженерии.</b> Железнодорожные мосты, опоры ЛЭП и Эйфелева башня состоят из треугольных ферм. Треугольник жёсткий — под нагрузкой не деформируется.', '<b>In engineering.</b> Railway bridges, power-line pylons and the Eiffel Tower are made of triangular trusses. A triangle is rigid — it does not deform under load.'),
      L('<b>Og‘irlik markazi.</b> Kartondan uchburchak qirqing va uning medianalari kesishgan nuqtasini qalam uchiga qo‘ying — uchburchak muvozanatda turadi! Bu nuqta og‘irlik markazi deyiladi.', '<b>Центр тяжести.</b> Вырежьте треугольник из картона и поставьте точку пересечения медиан на кончик карандаша — треугольник будет в равновесии! Эта точка называется центром тяжести.', '<b>Centre of mass.</b> Cut a triangle from cardboard and balance the meeting point of its medians on a pencil tip — it stays balanced! That point is the centre of mass.'),
      L('<b>Navigatsiyada.</b> GPS qurilmasi bir necha sun’iy yo‘ldoshgacha masofani bilib, o‘z joyini uchburchaklar yordamida aniqlaydi. Qadimda ham dengizchilar ikki mayoqqa qarab kemaning o‘rnini shunday topishgan.', '<b>В навигации.</b> GPS-приёмник, зная расстояния до нескольких спутников, определяет своё положение с помощью треугольников. Мореплаватели древности так же находили место корабля по двум маякам.', '<b>In navigation.</b> A GPS receiver finds its position using triangles, knowing its distances to several satellites. Ancient sailors likewise located their ship from two lighthouses.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Kompyuter o‘yinlaridagi har qanday 3D shakl — personaj, mashina, daraxt — minglab mayda uchburchaklardan yasaladi. Videokarta soniyasiga milliardlab uchburchak chizadi.', 'Любая 3D-фигура в компьютерных играх — персонаж, машина, дерево — собрана из тысяч мелких треугольников. Видеокарта рисует миллиарды треугольников в секунду.', 'Every 3D shape in a video game — a character, a car, a tree — is built from thousands of tiny triangles. A graphics card draws billions of triangles per second.'),
      L('Uchburchakda yuzdan ortiq «ajoyib nuqta» ma’lum (medianalar, bissektrisalar, balandliklar kesishmasi va boshqalar). Olimlar ularning to‘liq ro‘yxatini tuzib, ming-minglab nuqtani qayd etishgan.', 'У треугольника известно больше сотни «замечательных точек» (пересечение медиан, биссектрис, высот и другие). Учёные составили их энциклопедию, в ней уже тысячи точек.', 'More than a hundred “remarkable points” of a triangle are known (where medians, bisectors, altitudes meet, and more). Mathematicians keep an encyclopedia of them, now listing thousands of points.'),
      L('Geodezistlar XIX asrda butun mamlakatlarni ulkan uchburchaklar to‘ri bilan qoplab, aniq xaritalar tuzishgan. Bu usul <b>triangulyatsiya</b> deyiladi.', 'В XIX веке геодезисты покрывали целые страны сетью огромных треугольников, чтобы составить точные карты. Этот метод называется <b>триангуляцией</b>.', 'In the 19th century surveyors covered whole countries with networks of huge triangles to make accurate maps. The method is called <b>triangulation</b>.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Teng tomonli uchburchakning perimetri 27 cm. Tomoni nechaga teng?', 'Периметр равностороннего треугольника 27 см. Чему равна сторона?', 'An equilateral triangle has perimeter 27 cm. What is its side?'),
      L('Qaysi uchburchakda balandlik uchburchakning tomoni bilan ustma-ust tushadi?', 'В каком треугольнике высота совпадает со стороной?', 'In which triangle does an altitude coincide with a side?'),
      L('AM mediana △ABC ni ikki uchburchakka bo‘ladi. Ularning perimetrlari ayirmasi nimaga teng?', 'Медиана AM делит △ABC на два треугольника. Чему равна разность их периметров?', 'Median AM splits △ABC into two triangles. What is the difference of their perimeters?'),
      L('Uchburchakning uchala bissektrisasini chizing. Ular bir nuqtada kesishdimi?', 'Начертите все три биссектрисы треугольника. Пересеклись ли они в одной точке?', 'Draw all three bisectors of a triangle. Do they meet at one point?')
    ], after: [
      L('Javoblar: 1) 9 cm. 2) To‘g‘ri burchakli uchburchakda — katet. 3) ABM va ACM da AM umumiy, BM = MC, demak ayirma |AB − AC|. 4) Ha, doim bitta nuqtada — bu ichki chizilgan aylananing markazi.', 'Ответы: 1) 9 см. 2) В прямоугольном — катет. 3) У ABM и ACM общая AM и BM = MC, значит разность |AB − AC|. 4) Да, всегда в одной точке — это центр вписанной окружности.', 'Answers: 1) 9 cm. 2) In a right triangle — a leg. 3) ABM and ACM share AM and BM = MC, so the difference is |AB − AC|. 4) Yes, always at one point — the centre of the inscribed circle.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Uchburchak — bir chiziqda yotmagan uch nuqta va ularni tutashtiruvchi uch kesma.', 'Треугольник — три точки не на одной прямой и три соединяющих их отрезка.', 'A triangle is three non-collinear points and the three segments joining them.'),
      L('Burchaklari bo‘yicha: o‘tkir, to‘g‘ri, o‘tmas burchakli; tomonlari bo‘yicha: turli tomonli, teng yonli, teng tomonli.', 'По углам: остроугольный, прямоугольный, тупоугольный; по сторонам: разносторонний, равнобедренный, равносторонний.', 'By angles: acute, right, obtuse; by sides: scalene, isosceles, equilateral.'),
      L('<b>Mediana</b> qarshi tomonni, <b>bissektrisa</b> burchakni teng ikkiga bo‘ladi, <b>balandlik</b> qarshi tomonga perpendikulyar.', '<b>Медиана</b> делит пополам противоположную сторону, <b>биссектриса</b> — угол, <b>высота</b> перпендикулярна противоположной стороне.', 'A <b>median</b> halves the opposite side, a <b>bisector</b> halves the angle, an <b>altitude</b> is perpendicular to the opposite side.'),
      L('Har uchburchakda bu kesmalarning har biridan uchtadan bor va ular bir nuqtada kesishadi.', 'В каждом треугольнике по три таких отрезка каждого вида, и они пересекаются в одной точке.', 'Every triangle has three of each, and each trio meets at one point.'),
      L('Perimetr — tomonlar yig‘indisi: P = a + b + c.', 'Периметр — сумма сторон: P = a + b + c.', 'Perimeter is the sum of the sides: P = a + b + c.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t5. Uchburchaklar tengligi alomatlari ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Qachon ikki uchburchak bir xil?', 'Когда два треугольника одинаковы?', 'When are two triangles the same?'), p: [
      L('Tasavvur qiling: duradgor bir xil ikkita uchburchak shaklidagi tokcha yasashi kerak. U birinchisining uchala tomonini va uchala burchagini — oltita o‘lchovni ham o‘lchab, ikkinchisiga ko‘chirishi shartmi? Yo‘q! Ma’lum bo‘lishicha, faqat <b>uchta</b> to‘g‘ri tanlangan element yetarli. Qolganlari o‘z-o‘zidan mos keladi.', 'Представьте: столяру нужно сделать две одинаковые треугольные полки. Обязан ли он измерить у первой все три стороны и все три угла — шесть величин — и перенести их на вторую? Нет! Оказывается, достаточно всего <b>трёх</b> правильно выбранных элементов. Остальные совпадут сами.', 'Imagine a carpenter has to make two identical triangular shelves. Must he measure all three sides and all three angles of the first one — six measurements — and copy them to the second? No! It turns out that just <b>three</b> well-chosen parts are enough. The rest match automatically.'),
      L('Bu mavzudagi uchta teorema — <b>uchburchaklar tengligi alomatlari</b> — geometriyaning eng kuchli quroli. Kesmalar yoki burchaklarning tengligini isbotlash kerak bo‘lsa, ko‘pincha ularni ikkita teng uchburchakning mos elementlari sifatida ko‘rsatish kifoya. Deyarli barcha keyingi teoremalar shu alomatlar orqali isbotlanadi.', 'Три теоремы этой темы — <b>признаки равенства треугольников</b> — самое мощное оружие геометрии. Если нужно доказать равенство отрезков или углов, часто достаточно показать, что они — соответствующие элементы двух равных треугольников. Почти все дальнейшие теоремы доказываются через эти признаки.', 'The three theorems of this topic — the <b>triangle congruence tests</b> — are geometry’s most powerful tool. To prove that two segments or angles are equal, it is often enough to show they are matching parts of two congruent triangles. Almost every later theorem is proved using these tests.')
    ] },
    { kind: 'def', h: L('Teng shakllar', 'Равные фигуры', 'Congruent figures'), p: [
      L('Ikki shakl <b>teng</b> deyiladi, agar ularni ustma-ust qo‘yganda (siljitish, burish yoki ag‘darish bilan) to‘liq mos tushsa. Teng uchburchaklarda mos tomonlar va mos burchaklar teng bo‘ladi. Yozuvi: △ABC = △A₁B₁C₁ (ba’zan ≅ belgisi ishlatiladi).', 'Две фигуры называются <b>равными</b>, если их можно совместить наложением (сдвигом, поворотом или переворотом). У равных треугольников соответствующие стороны и соответствующие углы равны. Запись: △ABC = △A₁B₁C₁ (иногда используют знак ≅).', 'Two figures are <b>congruent</b> if one can be placed exactly on the other (by sliding, turning or flipping). In congruent triangles the matching sides and matching angles are equal. Notation: △ABC = △A₁B₁C₁ (sometimes the sign ≅ is used).'),
      L('Yozuvdagi harflar tartibi muhim! △ABC = △MNK yozuvi A ↔ M, B ↔ N, C ↔ K mos kelishini bildiradi. Demak AB = MN, BC = NK, AC = MK, ∠A = ∠M, ∠B = ∠N, ∠C = ∠K. Harflarni tartibsiz yozish xatoga olib keladi.', 'Порядок букв в записи важен! △ABC = △MNK означает соответствие A ↔ M, B ↔ N, C ↔ K. Значит, AB = MN, BC = NK, AC = MK, ∠A = ∠M, ∠B = ∠N, ∠C = ∠K. Беспорядочная запись букв приводит к ошибкам.', 'The order of the letters matters! △ABC = △MNK means A ↔ M, B ↔ N, C ↔ K. So AB = MN, BC = NK, AC = MK, ∠A = ∠M, ∠B = ∠N, ∠C = ∠K. Writing the letters in a careless order leads to mistakes.'),
      L('<b>Alomat</b> — bu shakllarning tengligini aniqlash uchun yetarli shartlar to‘plami. Teng uchburchaklarning barcha oltita elementi teng, lekin tenglikni isbotlash uchun uchtasini tekshirish kifoya.', '<b>Признак</b> — это набор условий, достаточных для вывода о равенстве фигур. У равных треугольников равны все шесть элементов, но для доказательства равенства достаточно проверить три.', 'A <b>test</b> is a set of conditions sufficient to conclude that figures are congruent. Congruent triangles have all six parts equal, but to prove congruence it is enough to check three.')
    ] },
    { kind: 'history', h: L('Fales, Yevklid va «ustma-ust qo‘yish»', 'Фалес, Евклид и «наложение»', 'Thales, Euclid and superposition'), p: [
      L('Rivoyatlarga ko‘ra, <b>Fales</b> «tomon va unga yopishgan ikki burchak» alomatidan amalda foydalangan: qirg‘oqdan turib dengizdagi kemagacha masofani o‘lchash uchun u qirg‘oqda xuddi shunday, lekin qo‘l yetadigan uchburchak yasagan. Ikki uchburchak teng bo‘lgani uchun, kemagacha masofa quruqlikdagi kesmaga teng bo‘lgan.', 'По преданию, <b>Фалес</b> применял на практике признак «сторона и два прилежащих угла»: чтобы измерить расстояние с берега до корабля в море, он строил на суше такой же треугольник, но доступный для измерения. Так как треугольники равны, расстояние до корабля равнялось отрезку на суше.', 'According to legend, <b>Thales</b> used the “side and two adjacent angles” test in practice: to measure the distance from the shore to a ship at sea, he built an identical but reachable triangle on land. Since the triangles were congruent, the distance to the ship equalled the segment on land.'),
      L('<b>Yevklid</b> «Negizlar»ning birinchi kitobida birinchi alomatni (4-tasdiq) shakllarni xayolan ustma-ust qo‘yish yo‘li bilan isbotlagan. Keyinchalik XIX asr oxirida nemis matematigi <b>David Gilbert</b> bu usul qat’iy emasligini ko‘rsatdi va birinchi alomatni aksioma sifatida qabul qilishni taklif etdi. Hozirgi ko‘plab darsliklar ham shu yo‘ldan boradi.', '<b>Евклид</b> в первой книге «Начал» доказал первый признак (предложение 4) мысленным наложением фигур. Позже, в конце XIX века, немецкий математик <b>Давид Гильберт</b> показал, что этот приём недостаточно строг, и предложил принять первый признак как аксиому. Многие современные учебники идут этим путём.', '<b>Euclid</b> proved the first test (Proposition 4 of Book I) by mentally placing one figure on the other. Much later, at the end of the 19th century, the German mathematician <b>David Hilbert</b> showed this method was not fully rigorous and proposed taking the first test as an axiom. Many modern textbooks follow that path.')
    ] },
    { kind: 'rule', h: L('Uchta alomat', 'Три признака', 'The three tests'), p: [
      L('<b>1-alomat (TBT — ikki tomon va ular orasidagi burchak).</b> Agar bir uchburchakning ikki tomoni va ular orasidagi burchagi ikkinchi uchburchakning ikki tomoni va ular orasidagi burchagiga mos ravishda teng bo‘lsa, bunday uchburchaklar teng. <i>Isbot g‘oyasi:</i> △A₁B₁C₁ ni A₁ nuqta A ga tushadigan qilib qo‘yamiz va A₁B₁ ni AB nuri bo‘ylab yo‘naltiramiz. AB = A₁B₁ bo‘lgani uchun B₁ nuqta B ga tushadi. ∠A = ∠A₁ bo‘lgani uchun A₁C₁ nuri AC nuri bilan ustma-ust tushadi, AC = A₁C₁ bo‘lgani uchun C₁ nuqta C ga tushadi. Uchala uch mos tushdi — uchburchaklar teng.', '<b>Первый признак (СУС — две стороны и угол между ними).</b> Если две стороны и угол между ними одного треугольника соответственно равны двум сторонам и углу между ними другого, то треугольники равны. <i>Идея доказательства:</i> наложим △A₁B₁C₁ так, чтобы A₁ совпала с A, а A₁B₁ пошла по лучу AB. Так как AB = A₁B₁, точка B₁ совпадёт с B. Так как ∠A = ∠A₁, луч A₁C₁ пойдёт по лучу AC, а так как AC = A₁C₁, точка C₁ совпадёт с C. Все три вершины совпали — треугольники равны.', '<b>Test 1 (SAS — two sides and the included angle).</b> If two sides and the angle between them in one triangle equal two sides and the angle between them in another, the triangles are congruent. <i>Proof idea:</i> place △A₁B₁C₁ so that A₁ lands on A and A₁B₁ runs along ray AB. Since AB = A₁B₁, B₁ lands on B. Since ∠A = ∠A₁, ray A₁C₁ runs along ray AC, and since AC = A₁C₁, C₁ lands on C. All three vertices coincide — the triangles are congruent.'),
      L('<b>2-alomat (BTB — tomon va unga yopishgan ikki burchak).</b> Agar bir uchburchakning tomoni va unga yopishgan ikki burchagi ikkinchisining mos elementlariga teng bo‘lsa, uchburchaklar teng. <i>G‘oya:</i> AB ni A₁B₁ ga qo‘yamiz. Burchaklar teng bo‘lgani uchun A₁C₁ nuri AC ustiga, B₁C₁ nuri BC ustiga tushadi. Ikki nur faqat bitta nuqtada kesishadi, demak C₁ nuqta C ga tushadi.', '<b>Второй признак (УСУ — сторона и два прилежащих угла).</b> Если сторона и два прилежащих к ней угла одного треугольника равны соответствующим элементам другого, треугольники равны. <i>Идея:</i> наложим AB на A₁B₁. Так как углы равны, луч A₁C₁ ляжет на AC, а луч B₁C₁ — на BC. Два луча пересекаются только в одной точке, значит C₁ совпадёт с C.', '<b>Test 2 (ASA — a side and the two angles on it).</b> If a side and the two angles adjacent to it in one triangle equal the matching parts of another, the triangles are congruent. <i>Idea:</i> place AB on A₁B₁. Because the angles are equal, ray A₁C₁ lies along AC and ray B₁C₁ along BC. Two rays meet in only one point, so C₁ lands on C.'),
      L('<b>3-alomat (TTT — uch tomon).</b> Agar bir uchburchakning uchala tomoni ikkinchisining uchala tomoniga mos ravishda teng bo‘lsa, uchburchaklar teng. <i>G‘oya:</i> ikkinchi uchburchakni AB tomoniga boshqa tarafdan qo‘yib, C va C₁ uchlarini tutashtiramiz. Ikkita teng yonli uchburchak hosil bo‘ladi; ularning asosdagi burchaklari tengligidan ∠C = ∠C₁ kelib chiqadi va 1-alomat ishlaydi.', '<b>Третий признак (ССС — три стороны).</b> Если три стороны одного треугольника соответственно равны трём сторонам другого, треугольники равны. <i>Идея:</i> приложим второй треугольник к стороне AB с другой стороны и соединим вершины C и C₁. Получатся два равнобедренных треугольника; из равенства углов при основании следует ∠C = ∠C₁, и работает первый признак.', '<b>Test 3 (SSS — three sides).</b> If all three sides of one triangle equal the three sides of another, the triangles are congruent. <i>Idea:</i> attach the second triangle to side AB from the other side and join C to C₁. Two isosceles triangles appear; equal base angles give ∠C = ∠C₁, and test 1 applies.')
    ] },
    { kind: 'steps', h: L('Tenglikni isbotlash rejasi', 'План доказательства равенства', 'A plan for proving congruence'), list: [
      L('1-qadam. Chizma chizing va shartdagi teng elementlarni bir xil belgilar (chiziqcha, yoycha) bilan belgilang.', 'Шаг 1. Сделайте чертёж и отметьте равные по условию элементы одинаковыми знаками (чёрточками, дужками).', 'Step 1. Draw the figure and mark the parts that are equal by the given data with matching ticks and arcs.'),
      L('2-qadam. Qaysi ikki uchburchakni taqqoslash kerakligini tanlang — izlanayotgan kesma yoki burchak shu uchburchaklarda bo‘lsin.', 'Шаг 2. Выберите, какие два треугольника сравнивать, — искомый отрезок или угол должен в них входить.', 'Step 2. Choose which two triangles to compare — the segment or angle you need must belong to them.'),
      L('3-qadam. Yashirin tengliklarni qidiring: <b>umumiy tomon</b> (o‘ziga teng), <b>vertikal burchaklar</b>, o‘rta nuqta, bissektrisa.', 'Шаг 3. Ищите скрытые равенства: <b>общая сторона</b> (равна сама себе), <b>вертикальные углы</b>, середина, биссектриса.', 'Step 3. Look for hidden equalities: a <b>common side</b> (equal to itself), <b>vertical angles</b>, a midpoint, a bisector.'),
      L('4-qadam. Uchta tenglikni yozing va alomatni nomlang: «TBT alomatiga ko‘ra △… = △…».', 'Шаг 4. Выпишите три равенства и назовите признак: «по признаку СУС △… = △…».', 'Step 4. Write the three equalities and name the test: “by SAS, △… ≅ △…”.'),
      L('5-qadam. Teng uchburchaklardan kerakli mos elementlar tengligini xulosa qiling.', 'Шаг 5. Из равенства треугольников выведите равенство нужных соответствующих элементов.', 'Step 5. From the congruence, conclude that the required matching parts are equal.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har bir yechimda alomat nomini aniq ayting — bu isbotning eng muhim qismi.', 'В каждом решении чётко называйте признак — это главная часть доказательства.', 'Name the test clearly in each solution — it is the key part of the proof.')
    ], ex: [
      { q: L('AB va CD kesmalar O nuqtada kesishadi va har biri shu nuqtada teng ikkiga bo‘linadi. AC = BD ekanini isbotlang.', 'Отрезки AB и CD пересекаются в точке O и делятся ею пополам. Докажите, что AC = BD.', 'Segments AB and CD cross at O, and O is the midpoint of each. Prove that AC = BD.'), s: L('△AOC va △BOD ni olamiz. AO = OB va CO = OD (shart bo‘yicha), ∠AOC = ∠BOD (vertikal). TBT alomatiga ko‘ra △AOC = △BOD, demak mos tomonlar <b>AC = BD</b>.', 'Рассмотрим △AOC и △BOD. AO = OB и CO = OD (по условию), ∠AOC = ∠BOD (вертикальные). По признаку СУС △AOC = △BOD, значит, соответствующие стороны <b>AC = BD</b>.', 'Take △AOC and △BOD. AO = OB and CO = OD (given), ∠AOC = ∠BOD (vertical). By SAS, △AOC ≅ △BOD, so the matching sides give <b>AC = BD</b>.') },
      { q: L('AD kesma ∠BAC ning bissektrisasi va AD ⊥ BC (D — BC da). AB = AC ekanini isbotlang.', 'AD — биссектриса ∠BAC и AD ⊥ BC (D на BC). Докажите, что AB = AC.', 'AD bisects ∠BAC and AD ⊥ BC (D on BC). Prove that AB = AC.'), s: L('△ABD va △ACD: AD — umumiy tomon, ∠BAD = ∠CAD (bissektrisa), ∠ADB = ∠ADC = 90°. Tomon va unga yopishgan ikki burchak teng — BTB alomati. Demak △ABD = △ACD va <b>AB = AC</b>.', '△ABD и △ACD: AD — общая сторона, ∠BAD = ∠CAD (биссектриса), ∠ADB = ∠ADC = 90°. Сторона и два прилежащих угла равны — признак УСУ. Значит △ABD = △ACD и <b>AB = AC</b>.', '△ABD and △ACD: AD is common, ∠BAD = ∠CAD (bisector), ∠ADB = ∠ADC = 90°. A side and its two adjacent angles are equal — ASA. So △ABD ≅ △ACD and <b>AB = AC</b>.') },
      { q: L('ABCD to‘rtburchakda AB = CD va BC = AD. ∠B = ∠D ekanini isbotlang.', 'В четырёхугольнике ABCD AB = CD и BC = AD. Докажите, что ∠B = ∠D.', 'In quadrilateral ABCD, AB = CD and BC = AD. Prove that ∠B = ∠D.'), s: L('AC diagonalni o‘tkazamiz. △ABC va △CDA: AB = CD, BC = DA (shart), AC — umumiy. TTT alomatiga ko‘ra △ABC = △CDA. B uchiga D uchi mos keladi, demak <b>∠B = ∠D</b>.', 'Проведём диагональ AC. △ABC и △CDA: AB = CD, BC = DA (условие), AC — общая. По признаку ССС △ABC = △CDA. Вершине B соответствует D, значит <b>∠B = ∠D</b>.', 'Draw diagonal AC. △ABC and △CDA: AB = CD, BC = DA (given), AC is common. By SSS, △ABC ≅ △CDA. Vertex B matches D, so <b>∠B = ∠D</b>.') },
      { q: L('△ABC = △KLM, AB = 7 cm, ∠B = 50°, LM = 9 cm. KL, ∠L va BC ni toping.', '△ABC = △KLM, AB = 7 см, ∠B = 50°, LM = 9 см. Найдите KL, ∠L и BC.', '△ABC ≅ △KLM, AB = 7 cm, ∠B = 50°, LM = 9 cm. Find KL, ∠L and BC.'), s: L('Moslik: A ↔ K, B ↔ L, C ↔ M. KL = AB = <b>7 cm</b>, ∠L = ∠B = <b>50°</b>, BC = LM = <b>9 cm</b>.', 'Соответствие: A ↔ K, B ↔ L, C ↔ M. KL = AB = <b>7 см</b>, ∠L = ∠B = <b>50°</b>, BC = LM = <b>9 см</b>.', 'Matching: A ↔ K, B ↔ L, C ↔ M. KL = AB = <b>7 cm</b>, ∠L = ∠B = <b>50°</b>, BC = LM = <b>9 cm</b>.') }
    ] },
    { kind: 'table', h: L('Alomatlar jadvali', 'Таблица признаков', 'Table of tests'), table: { head: [L('Alomat', 'Признак', 'Test'), L('Nima teng bo‘lishi kerak', 'Что должно быть равно', 'What must be equal'), L('Diqqat', 'Внимание', 'Watch out')], rows: [
      [L('1 · TBT', '1 · СУС', '1 · SAS'), L('ikki tomon + ular orasidagi burchak', 'две стороны + угол между ними', 'two sides + the angle between them'), L('burchak aynan shu tomonlar orasida bo‘lsin', 'угол именно между этими сторонами', 'the angle must be between those sides')],
      [L('2 · BTB', '2 · УСУ', '2 · ASA'), L('tomon + unga yopishgan ikki burchak', 'сторона + два прилежащих угла', 'a side + the two angles on it'), L('burchaklar shu tomonga yopishgan bo‘lsin', 'углы прилежат именно к этой стороне', 'the angles must sit on that side')],
      [L('3 · TTT', '3 · ССС', '3 · SSS'), L('uchala tomon', 'все три стороны', 'all three sides'), L('burchaklar shart emas', 'углы не нужны', 'no angles needed')],
      [L('«BBB» — alomat EMAS', '«УУУ» — НЕ признак', '“AAA” is NOT a test'), L('uchala burchak', 'три угла', 'three angles'), L('o‘lchami har xil bo‘lishi mumkin', 'размеры могут быть разными', 'sizes can differ')]
    ] }, after: [
      L('Oxirgi qator muhim: uchala burchagi teng uchburchaklar faqat <i>o‘xshash</i> bo‘ladi — biri ikkinchisining kattalashtirilgan nusxasi bo‘lishi mumkin. Shuningdek, «ikki tomon va ular orasida bo‘lmagan burchak» (TTB) umumiy holda alomat emas.', 'Последняя строка важна: треугольники с тремя равными углами лишь <i>подобны</i> — один может быть увеличенной копией другого. Также «две стороны и угол не между ними» в общем случае не является признаком.', 'The last row matters: triangles with three equal angles are only <i>similar</i> — one may be an enlarged copy of the other. Also, “two sides and an angle not between them” is not a test in general.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Harflar tartibini buzish.</b> △ABC = △MNK dan AB = NK deb yozish — xato. Mos uchlar bir xil o‘rinda turadi.', '<b>Нарушать порядок букв.</b> Из △ABC = △MNK писать AB = NK — ошибка. Соответствующие вершины стоят на одинаковых местах.', '<b>Breaking the letter order.</b> From △ABC ≅ △MNK writing AB = NK is wrong. Matching vertices stand in the same positions.'),
      L('<b>TBT da burchakni noto‘g‘ri tanlash.</b> Burchak aynan teng tomonlar <i>orasida</i> bo‘lishi shart.', '<b>Брать «не тот» угол в СУС.</b> Угол обязан лежать <i>между</i> равными сторонами.', '<b>Using the wrong angle in SAS.</b> The angle must lie <i>between</i> the equal sides.'),
      L('<b>Uch burchak tengligidan uchburchaklar tengligini chiqarish.</b> Bunday alomat yo‘q.', '<b>Выводить равенство треугольников из равенства трёх углов.</b> Такого признака нет.', '<b>Concluding congruence from three equal angles.</b> No such test exists.'),
      L('<b>Umumiy tomonni unutish.</b> Ikki uchburchak bitta tomonni bo‘lishsa, bu tayyor tenglik — uni yozishni unutmang.', '<b>Забывать общую сторону.</b> Если у двух треугольников общая сторона, это готовое равенство — не забудьте его выписать.', '<b>Forgetting a common side.</b> If two triangles share a side, that is a ready-made equality — write it down.'),
      L('<b>Alomat nomini yozmaslik.</b> «Uchburchaklar teng» deyish yetarli emas — qaysi alomat bo‘yicha ekanini ko‘rsating.', '<b>Не называть признак.</b> Недостаточно сказать «треугольники равны» — укажите, по какому признаку.', '<b>Not naming the test.</b> “The triangles are congruent” is not enough — say which test.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Daryo kengligini o‘lchash.</b> Daryo bo‘yida A nuqtani, narigi qirg‘oqda daraxt T ni tanlang. A dan qirg‘oq bo‘ylab teng AO va OB kesmalarni o‘lchab qo‘ying, B dan qirg‘oqqa perpendikulyar yo‘nalishda yurib, O va T bir chiziqda ko‘ringan joyda to‘xtang. BTB alomati bo‘yicha hosil bo‘lgan uchburchak kerakli uchburchakka teng — daryo kengligi siz bosib o‘tgan yo‘lga teng!', '<b>Измерение ширины реки.</b> Выберите точку A на берегу и дерево T на другом берегу. Отложите вдоль берега равные отрезки AO и OB, из B идите перпендикулярно берегу, пока O и T не окажутся на одной линии. По признаку УСУ полученный треугольник равен нужному — ширина реки равна пройденному вами пути!', '<b>Measuring a river’s width.</b> Pick point A on the bank and a tree T on the far bank. Pace out equal segments AO and OB along the bank, then walk from B perpendicular to the bank until O and T line up. By ASA your triangle is congruent to the one you need — the river’s width equals the distance you walked!'),
      L('<b>Zavodda.</b> Detallar shablon bo‘yicha yasaladi: uchta tomoni bir xil uchburchak plastinkalar TTT alomati bo‘yicha teng — ular bir-birining o‘rnini bosa oladi.', '<b>На заводе.</b> Детали делают по шаблону: треугольные пластины с одинаковыми тремя сторонами равны по признаку ССС — они взаимозаменяемы.', '<b>In a factory.</b> Parts are made from a template: triangular plates with the same three sides are congruent by SSS — they are interchangeable.'),
      L('<b>Qurilishda.</b> Tom yog‘ochlari (stropila) bir xil uzunlikdagi uchta to‘sindan yig‘iladi — har bir uchburchak bir xil chiqadi, tom tekis bo‘ladi.', '<b>В строительстве.</b> Стропила собирают из трёх балок одинаковой длины — каждый треугольник получается одинаковым, и крыша ровная.', '<b>In building.</b> Roof trusses are assembled from three beams of fixed lengths — every triangle comes out the same and the roof is even.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('TTT alomati uchburchakning nega qattiq ekanini tushuntiradi: uch tomon uzunligi shaklni to‘liq belgilaydi. To‘rtburchakda esa to‘rt tomon ham shaklni belgilamaydi — shuning uchun u qiyshayadi.', 'Признак ССС объясняет, почему треугольник жёсткий: три длины сторон полностью задают форму. А у четырёхугольника даже четыре стороны форму не задают — поэтому он перекашивается.', 'The SSS test explains why a triangle is rigid: three side lengths fix the shape completely. For a quadrilateral even four sides do not fix the shape — that is why it skews.'),
      L('«Negizlar»da birinchi alomat (4-tasdiq) darhol 5-tasdiqdan oldin keladi. 5-tasdiq — teng yonli uchburchak asosidagi burchaklar tengligi — o‘rta asr Yevropasida lotincha <i>pons asinorum</i>, ya’ni «eshak ko‘prigi» deb atalgan: undan o‘ta olmagan talaba geometriyani davom ettirolmas ekan.', 'В «Началах» первый признак (предложение 4) стоит прямо перед предложением 5. Предложение 5 — о равенстве углов при основании равнобедренного треугольника — в средневековой Европе называли по-латыни <i>pons asinorum</i>, «ослиный мост»: студент, не сумевший его перейти, дальше в геометрии не продвигался.', 'In the <i>Elements</i> the first test (Proposition 4) comes right before Proposition 5. Proposition 5 — the equal base angles of an isosceles triangle — was nicknamed <i>pons asinorum</i>, “the bridge of asses”, in medieval Europe: a student who could not cross it went no further in geometry.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Ikkita to‘g‘ri burchakli uchburchakning katetlari mos ravishda teng. Ular tengmi? Qaysi alomat bo‘yicha?', 'Катеты двух прямоугольных треугольников соответственно равны. Равны ли треугольники? По какому признаку?', 'The legs of two right triangles are equal in pairs. Are the triangles congruent? By which test?'),
      L('Uchburchak va uning nusxasining perimetrlari teng va ikki tomoni teng. Uchinchi tomoni haqida nima deyish mumkin?', 'У треугольника и другого треугольника равны периметры и две стороны. Что можно сказать о третьей стороне?', 'Two triangles have equal perimeters and two equal sides. What about the third side?'),
      L('M nuqta AB ning o‘rtasi, MC ⊥ AB. CA = CB ekanini isbotlang.', 'M — середина AB, MC ⊥ AB. Докажите, что CA = CB.', 'M is the midpoint of AB and MC ⊥ AB. Prove that CA = CB.')
    ], after: [
      L('Javoblar: 1) Ha, TBT: katetlar va ular orasidagi 90°. 2) U ham teng, demak uchburchaklar TTT bo‘yicha teng. 3) △AMC = △BMC: AM = MB, MC umumiy, ∠AMC = ∠BMC = 90° (TBT).', 'Ответы: 1) Да, СУС: катеты и угол 90° между ними. 2) Она тоже равна, значит треугольники равны по ССС. 3) △AMC = △BMC: AM = MB, MC общая, ∠AMC = ∠BMC = 90° (СУС).', 'Answers: 1) Yes, SAS: the legs and the 90° angle between them. 2) It is equal too, so the triangles are congruent by SSS. 3) △AMC ≅ △BMC: AM = MB, MC common, ∠AMC = ∠BMC = 90° (SAS).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Teng uchburchaklar ustma-ust tushadi; mos tomonlar va mos burchaklar teng.', 'Равные треугольники совмещаются наложением; соответствующие стороны и углы равны.', 'Congruent triangles coincide when overlaid; matching sides and angles are equal.'),
      L('<b>TBT:</b> ikki tomon va ular orasidagi burchak.', '<b>СУС:</b> две стороны и угол между ними.', '<b>SAS:</b> two sides and the included angle.'),
      L('<b>BTB:</b> tomon va unga yopishgan ikki burchak.', '<b>УСУ:</b> сторона и два прилежащих угла.', '<b>ASA:</b> a side and the two adjacent angles.'),
      L('<b>TTT:</b> uchala tomon.', '<b>ССС:</b> три стороны.', '<b>SSS:</b> three sides.'),
      L('Uch burchak tengligi — alomat emas.', 'Равенство трёх углов — не признак.', 'Three equal angles is not a test.'),
      L('Isbotda umumiy tomon va vertikal burchaklarni qidiring, alomatni nomlang.', 'В доказательстве ищите общую сторону и вертикальные углы, называйте признак.', 'In proofs, look for common sides and vertical angles, and name the test.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t6. Teng yonli uchburchakning xossalari ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Simmetrik uchburchak', 'Симметричный треугольник', 'A symmetric triangle'), p: [
      L('Uyning tomi, archa, ko‘prik ustunlari orasidagi tros, varrak — ularning ko‘pchiligi ikki tomoni teng uchburchak shaklida. Bunday uchburchak chap va o‘ng yarmi bir xil — u <b>simmetrik</b>. Simmetriya esa doim chiroyli va ayni paytda foydali: yuk ikki tomonga teng taqsimlanadi.', 'Крыша дома, ёлка, тросы между опорами моста, воздушный змей — многие из них имеют форму треугольника с двумя равными сторонами. У такого треугольника левая и правая половины одинаковы — он <b>симметричен</b>. А симметрия всегда красива и одновременно полезна: нагрузка распределяется на обе стороны поровну.', 'A house roof, a fir tree, cables between bridge towers, a kite — many of them are triangles with two equal sides. The left and right halves of such a triangle are the same — it is <b>symmetric</b>. Symmetry is always beautiful and useful too: the load is shared equally between the two sides.'),
      L('Bu mavzuda teng yonli uchburchakning ikki asosiy xossasini isbotlaymiz: asosdagi burchaklar teng va asosga tushirilgan mediana bir vaqtda bissektrisa hamda balandlik bo‘ladi. Shuningdek, teskari teoremani — teng yonlilik alomatini ham o‘rganamiz. Bu isbotlar oldingi mavzudagi tenglik alomatlarini qanday ishlatishni ko‘rsatadi.', 'В этой теме докажем два главных свойства равнобедренного треугольника: углы при основании равны, а медиана к основанию одновременно является биссектрисой и высотой. Также изучим обратную теорему — признак равнобедренного треугольника. Эти доказательства показывают, как работают признаки равенства из прошлой темы.', 'In this topic we prove two main properties of an isosceles triangle: the base angles are equal, and the median to the base is also the bisector and the altitude. We also study the converse — the test for an isosceles triangle. These proofs show how the congruence tests from the previous topic are used.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), p: [
      L('<b>Teng yonli uchburchak</b> — ikki tomoni teng bo‘lgan uchburchak. Teng tomonlar <b>yon tomonlar</b>, uchinchi tomon — <b>asos</b> deyiladi. Yon tomonlar uchrashgan uch — <b>uchi</b>, undagi burchak — <b>uchidagi burchak</b>; asosga yopishgan ikki burchak — <b>asosdagi burchaklar</b>.', '<b>Равнобедренный треугольник</b> — треугольник с двумя равными сторонами. Равные стороны называются <b>боковыми</b>, третья — <b>основанием</b>. Вершина, где сходятся боковые стороны, — <b>вершина</b> треугольника, угол при ней — <b>угол при вершине</b>; два угла, прилежащих к основанию, — <b>углы при основании</b>.', 'An <b>isosceles triangle</b> has two equal sides. The equal sides are the <b>legs</b>, the third side is the <b>base</b>. The vertex where the legs meet is the <b>apex</b>, its angle is the <b>apex angle</b>; the two angles on the base are the <b>base angles</b>.'),
      L('<b>Teng tomonli uchburchak</b> — uchala tomoni teng uchburchak. U teng yonlining xususiy holi: istalgan tomonini asos deb olish mumkin. Shuning uchun teng yonli uchburchak haqidagi barcha teoremalar teng tomonliga ham taalluqli.', '<b>Равносторонний треугольник</b> — треугольник, у которого все три стороны равны. Это частный случай равнобедренного: основанием можно считать любую сторону. Поэтому все теоремы о равнобедренном треугольнике верны и для равностороннего.', 'An <b>equilateral triangle</b> has all three sides equal. It is a special isosceles triangle: any side can be taken as the base. So every theorem about isosceles triangles also holds for equilateral ones.'),
      L('Teng yonli uchburchakning perimetri: P = 2a + b, bu yerda a — yon tomon, b — asos. Teng tomonlining perimetri: P = 3a.', 'Периметр равнобедренного треугольника: P = 2a + b, где a — боковая сторона, b — основание. Периметр равностороннего: P = 3a.', 'Perimeter of an isosceles triangle: P = 2a + b, where a is a leg and b the base. Perimeter of an equilateral triangle: P = 3a.')
    ] },
    { kind: 'history', h: L('«Eshak ko‘prigi»', '«Ослиный мост»', 'The bridge of asses'), p: [
      L('Teng yonli uchburchak asosidagi burchaklar tengligi haqidagi teorema Yevklid «Negizlar»ida 5-tasdiq bo‘lib, uning chizmasi ko‘prikka o‘xshab ketadi. O‘rta asr Yevropasida bu teorema <i>pons asinorum</i> — «eshak ko‘prigi» deb atalgan: undan o‘ta olmagan talaba «eshak» hisoblanib, geometriyani davom ettira olmagan. Yevklid isboti ancha uzun va murakkab bo‘lgan.', 'Теорема о равенстве углов при основании равнобедренного треугольника — предложение 5 в «Началах» Евклида, и её чертёж похож на мост. В средневековой Европе её называли <i>pons asinorum</i> — «ослиный мост»: студент, не сумевший его перейти, считался «ослом» и не мог продолжать геометрию. Доказательство Евклида было довольно длинным и сложным.', 'The theorem that the base angles of an isosceles triangle are equal is Proposition 5 in Euclid’s <i>Elements</i>, and its figure looks like a bridge. In medieval Europe it was called <i>pons asinorum</i>, “the bridge of asses”: a student who could not cross it was thought a “donkey” and could not continue with geometry. Euclid’s proof was rather long and complicated.'),
      L('Rivoyatga ko‘ra, bu teoremani birinchi bo‘lib <b>Fales</b> kashf etgan. Qadimgi yunon olimi <b>Papp Iskandariy</b> (IV asr) esa juda qisqa isbot topgan: uchburchakni o‘zining ko‘zgudagi aksi bilan taqqoslash. Biz quyida mediana orqali isbotlaymiz — bu usul eng tushunarli.', 'По преданию, эту теорему первым открыл <b>Фалес</b>. А древнегреческий учёный <b>Папп Александрийский</b> (IV век) нашёл очень короткое доказательство — сравнить треугольник с его зеркальным отражением. Мы докажем её ниже через медиану — этот способ самый понятный.', 'Tradition says <b>Thales</b> discovered this theorem first. The Greek scholar <b>Pappus of Alexandria</b> (4th century) found a very short proof: compare the triangle with its own mirror image. Below we prove it using the median — the clearest way.')
    ] },
    { kind: 'rule', h: L('Asosiy teoremalar', 'Основные теоремы', 'The main theorems'), p: [
      L('<b>1-teorema.</b> Teng yonli uchburchakda asosdagi burchaklar teng. <i>Isbot:</i> △ABC da AB = BC, AC — asos. BM medianani o‘tkazamiz (AM = MC). △ABM va △CBM da: AB = CB (shart), AM = CM (mediana), BM — umumiy tomon. TTT alomatiga ko‘ra △ABM = △CBM. Mos burchaklar teng: <b>∠A = ∠C</b>.', '<b>Теорема 1.</b> В равнобедренном треугольнике углы при основании равны. <i>Доказательство:</i> в △ABC AB = BC, AC — основание. Проведём медиану BM (AM = MC). В △ABM и △CBM: AB = CB (условие), AM = CM (медиана), BM — общая. По признаку ССС △ABM = △CBM. Соответствующие углы равны: <b>∠A = ∠C</b>.', '<b>Theorem 1.</b> In an isosceles triangle the base angles are equal. <i>Proof:</i> in △ABC, AB = BC and AC is the base. Draw median BM (AM = MC). In △ABM and △CBM: AB = CB (given), AM = CM (median), BM common. By SSS, △ABM ≅ △CBM. Matching angles are equal: <b>∠A = ∠C</b>.'),
      L('<b>2-teorema.</b> Teng yonli uchburchakda asosga tushirilgan mediana bissektrisa va balandlik ham bo‘ladi. <i>Isbot:</i> o‘sha teng uchburchaklardan ∠ABM = ∠CBM — demak BM bissektrisa. Yana ∠AMB = ∠CMB, ular qo‘shni va yig‘indisi 180°, demak har biri 90° — BM balandlik.', '<b>Теорема 2.</b> В равнобедренном треугольнике медиана, проведённая к основанию, является биссектрисой и высотой. <i>Доказательство:</i> из тех же равных треугольников ∠ABM = ∠CBM — значит, BM биссектриса. Также ∠AMB = ∠CMB, они смежные с суммой 180°, значит каждый 90° — BM высота.', '<b>Theorem 2.</b> In an isosceles triangle the median to the base is also the angle bisector and the altitude. <i>Proof:</i> the same congruent triangles give ∠ABM = ∠CBM, so BM is the bisector. Also ∠AMB = ∠CMB; they are adjacent with sum 180°, so each is 90° — BM is the altitude.'),
      L('<b>3-teorema (alomat).</b> Agar uchburchakning ikki burchagi teng bo‘lsa, u teng yonli. <i>Isbot g‘oyasi:</i> ∠A = ∠C bo‘lsin. △ABC ni o‘zining «ag‘darilgan nusxasi» △CBA bilan taqqoslaymiz: AC = CA, ∠A = ∠C, ∠C = ∠A — BTB alomati bo‘yicha ular teng, demak AB = CB. Teng tomonli uchburchakda esa uchala burchak teng — har biri 60°.', '<b>Теорема 3 (признак).</b> Если два угла треугольника равны, то он равнобедренный. <i>Идея доказательства:</i> пусть ∠A = ∠C. Сравним △ABC с его «перевёрнутой копией» △CBA: AC = CA, ∠A = ∠C, ∠C = ∠A — по признаку УСУ они равны, значит AB = CB. В равностороннем треугольнике все три угла равны — по 60°.', '<b>Theorem 3 (test).</b> If two angles of a triangle are equal, it is isosceles. <i>Proof idea:</i> let ∠A = ∠C. Compare △ABC with its “flipped copy” △CBA: AC = CA, ∠A = ∠C, ∠C = ∠A — by ASA they are congruent, so AB = CB. In an equilateral triangle all three angles are equal — 60° each.')
    ] },
    { kind: 'steps', h: L('Teng yonli uchburchak burchaklarini topish', 'Как найти углы равнобедренного треугольника', 'Finding angles in an isosceles triangle'), list: [
      L('1-qadam. Qaysi tomon asos ekanini aniqlang — asos yon tomonlar orasida emas, ularning uchlarini tutashtiradi.', 'Шаг 1. Определите, какая сторона — основание: оно соединяет концы боковых сторон.', 'Step 1. Decide which side is the base: it joins the ends of the two equal legs.'),
      L('2-qadam. Agar uchidagi burchak β berilgan bo‘lsa: asosdagi har bir burchak = (180° − β) : 2.', 'Шаг 2. Если дан угол при вершине β: каждый угол при основании = (180° − β) : 2.', 'Step 2. If the apex angle β is given: each base angle = (180° − β) : 2.'),
      L('3-qadam. Agar asosdagi burchak α berilgan bo‘lsa: uchidagi burchak = 180° − 2α.', 'Шаг 3. Если дан угол при основании α: угол при вершине = 180° − 2α.', 'Step 3. If a base angle α is given: apex angle = 180° − 2α.'),
      L('4-qadam. Agar berilgan burchak qaysi ekani noma’lum bo‘lsa, ikki holni ham ko‘ring. Faqat o‘tmas burchak har doim uchidagi burchak bo‘ladi (asosda ikkita o‘tmas burchak bo‘la olmaydi).', 'Шаг 4. Если неизвестно, какой это угол, рассмотрите оба случая. Только тупой угол всегда при вершине (при основании не может быть двух тупых углов).', 'Step 4. If you are not told which angle it is, consider both cases. Only an obtuse angle must be the apex angle (the base cannot have two obtuse angles).'),
      L('(Uchburchak burchaklari yig‘indisi 180° ekanligini 9-mavzuda isbotlaymiz; bu yerda undan oldindan foydalanamiz.)', '(То, что сумма углов треугольника равна 180°, докажем в теме 9; здесь пользуемся этим заранее.)', '(We prove that a triangle’s angles sum to 180° in topic 9; here we use it in advance.)')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), p: [
      L('Har masalada chizmada teng tomonlarni chiziqcha bilan belgilang.', 'В каждой задаче отметьте равные стороны чёрточками на чертеже.', 'In every problem, mark the equal sides with ticks on the drawing.')
    ], ex: [
      { q: L('Teng yonli uchburchakning uchidagi burchagi 40°. Asosdagi burchaklarni toping.', 'Угол при вершине равнобедренного треугольника 40°. Найдите углы при основании.', 'The apex angle of an isosceles triangle is 40°. Find the base angles.'), s: L('(180° − 40°) : 2 = 140° : 2 = <b>70°</b>. Ikkalasi ham 70°.', '(180° − 40°) : 2 = 140° : 2 = <b>70°</b>. Оба по 70°.', '(180° − 40°) : 2 = 140° : 2 = <b>70°</b>. Both are 70°.') },
      { q: L('Teng yonli uchburchakning bir burchagi 50°. Qolgan burchaklarini toping.', 'Один из углов равнобедренного треугольника 50°. Найдите остальные.', 'One angle of an isosceles triangle is 50°. Find the others.'), s: L('Ikki hol. 1) 50° — uchidagi burchak: asosdagilar (180 − 50) : 2 = 65°. Javob: <b>50°, 65°, 65°</b>. 2) 50° — asosdagi burchak: ikkinchisi ham 50°, uchidagi 180 − 100 = 80°. Javob: <b>50°, 50°, 80°</b>.', 'Два случая. 1) 50° — угол при вершине: при основании (180 − 50) : 2 = 65°. Ответ: <b>50°, 65°, 65°</b>. 2) 50° — угол при основании: второй тоже 50°, при вершине 180 − 100 = 80°. Ответ: <b>50°, 50°, 80°</b>.', 'Two cases. 1) 50° is the apex angle: base angles (180 − 50) : 2 = 65°. Answer: <b>50°, 65°, 65°</b>. 2) 50° is a base angle: the other is also 50°, apex 180 − 100 = 80°. Answer: <b>50°, 50°, 80°</b>.') },
      { q: L('Teng yonli uchburchakning perimetri 32 cm, asosi yon tomonidan 4 cm qisqa. Tomonlarini toping.', 'Периметр равнобедренного треугольника 32 см, основание на 4 см короче боковой стороны. Найдите стороны.', 'An isosceles triangle has perimeter 32 cm, and the base is 4 cm shorter than a leg. Find the sides.'), s: L('Yon tomon x, asos x − 4. 2x + (x − 4) = 32, 3x = 36, x = 12. Yon tomonlar <b>12 cm</b>, asos <b>8 cm</b>. Tekshiruv: 12 + 12 + 8 = 32.', 'Боковая сторона x, основание x − 4. 2x + (x − 4) = 32, 3x = 36, x = 12. Боковые стороны <b>12 см</b>, основание <b>8 см</b>. Проверка: 12 + 12 + 8 = 32.', 'Let the leg be x and the base x − 4. 2x + (x − 4) = 32, 3x = 36, x = 12. Legs <b>12 cm</b>, base <b>8 cm</b>. Check: 12 + 12 + 8 = 32.') },
      { q: L('△ABC da AB = BC, BD — mediana, ∠ABC = 110°, AC = 18 cm. ∠ABD, ∠BDC va AD ni toping.', 'В △ABC AB = BC, BD — медиана, ∠ABC = 110°, AC = 18 см. Найдите ∠ABD, ∠BDC и AD.', 'In △ABC, AB = BC, BD is a median, ∠ABC = 110°, AC = 18 cm. Find ∠ABD, ∠BDC and AD.'), s: L('Asosga mediana — bissektrisa ham: ∠ABD = 110° : 2 = <b>55°</b>. U balandlik ham: ∠BDC = <b>90°</b>. Mediana bo‘lgani uchun AD = 18 : 2 = <b>9 cm</b>.', 'Медиана к основанию — ещё и биссектриса: ∠ABD = 110° : 2 = <b>55°</b>. И высота: ∠BDC = <b>90°</b>. Так как медиана, AD = 18 : 2 = <b>9 см</b>.', 'The median to the base is also the bisector: ∠ABD = 110° : 2 = <b>55°</b>. And the altitude: ∠BDC = <b>90°</b>. Being a median, AD = 18 : 2 = <b>9 cm</b>.') }
    ] },
    { kind: 'table', h: L('Teng yonli va teng tomonli', 'Равнобедренный и равносторонний', 'Isosceles vs equilateral'), table: { head: [L('Xossa', 'Свойство', 'Property'), L('Teng yonli', 'Равнобедренный', 'Isosceles'), L('Teng tomonli', 'Равносторонний', 'Equilateral')], rows: [
      [L('Teng tomonlar', 'Равные стороны', 'Equal sides'), '2', '3'],
      [L('Teng burchaklar', 'Равные углы', 'Equal angles'), L('2 (asosda)', '2 (при основании)', '2 (base angles)'), L('3 (har biri 60°)', '3 (по 60°)', '3 (60° each)')],
      [L('Mediana = bissektrisa = balandlik', 'Медиана = биссектриса = высота', 'Median = bisector = altitude'), L('faqat asosga', 'только к основанию', 'only to the base'), L('har uchala tomonga', 'ко всем трём сторонам', 'to all three sides')],
      [L('Simmetriya o‘qlari', 'Оси симметрии', 'Lines of symmetry'), '1', '3'],
      [L('Perimetr', 'Периметр', 'Perimeter'), 'P = 2a + b', 'P = 3a']
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Asosni noto‘g‘ri aniqlash.</b> Asos har doim «pastdagi» tomon emas — u teng bo‘lmagan tomon. Chizma qanday turishiga qaramang.', '<b>Неверно определять основание.</b> Основание — не обязательно «нижняя» сторона, а та, что не равна другим. Не смотрите на то, как повёрнут чертёж.', '<b>Misidentifying the base.</b> The base is not always the “bottom” side — it is the unequal side. Ignore how the drawing is turned.'),
      L('<b>Ikki holni ko‘rmaslik.</b> «Bir burchagi 50°» deyilsa, u uchida ham, asosda ham bo‘lishi mumkin.', '<b>Не рассматривать два случая.</b> Если сказано «один угол 50°», он может быть и при вершине, и при основании.', '<b>Missing a case.</b> If “one angle is 50°”, it may be the apex angle or a base angle.'),
      L('<b>Har qanday medianani bissektrisa deb hisoblash.</b> Faqat <i>asosga</i> tushirilgan mediana bissektrisa va balandlik bo‘ladi; yon tomonga tushirilgani — odatda yo‘q.', '<b>Считать любую медиану биссектрисой.</b> Только медиана к <i>основанию</i> — биссектриса и высота; медиана к боковой стороне обычно нет.', '<b>Thinking every median is a bisector.</b> Only the median to the <i>base</i> is also the bisector and altitude; one to a leg usually is not.'),
      L('<b>Asosda o‘tmas burchak qo‘yish.</b> Asosdagi burchaklar har doim o‘tkir: ikkita o‘tmas burchak yig‘indisi 180° dan oshib ketadi.', '<b>Ставить тупой угол при основании.</b> Углы при основании всегда острые: два тупых угла в сумме больше 180°.', '<b>Putting an obtuse angle at the base.</b> Base angles are always acute: two obtuse angles would exceed 180°.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Tom qurishda.</b> Ikki nishabli tomning kesimi teng yonli uchburchak. Usta tomning cho‘qqisidan shoqul tushirib, uning asos o‘rtasiga aniq tushishini tekshiradi — bu mediana va balandlik ustma-ust tushishining amaliy qo‘llanishi.', '<b>При строительстве крыши.</b> Сечение двускатной крыши — равнобедренный треугольник. Мастер опускает отвес с конька и проверяет, что он попадает точно в середину основания, — это практическое применение совпадения медианы и высоты.', '<b>Building a roof.</b> A gable roof’s cross-section is an isosceles triangle. The builder drops a plumb line from the ridge and checks that it hits the exact middle of the base — a practical use of the median and altitude coinciding.'),
      L('<b>Tarozida.</b> Pallali tarozi muvozanatda bo‘lganda, ikki ip va to‘sin teng yonli uchburchak hosil qiladi. Simmetrik shakl — teng og‘irlik belgisi.', '<b>В весах.</b> Когда чашечные весы уравновешены, подвесы и коромысло образуют равнобедренный треугольник. Симметричная форма — признак равных весов.', '<b>In balances.</b> When a pan balance is level, the hangers and beam form an isosceles triangle. A symmetric shape signals equal weights.'),
      L('<b>Me’morchilikda.</b> Samarqand va Buxoro peshtoqlarining ravoqlari, qadimiy gumbazlar naqshlari ko‘pincha teng yonli va teng tomonli uchburchaklardan tuzilgan. Usta-naqqoshlar bunday naqshlarni faqat sirkul va chizg‘ich bilan chizishgan.', '<b>В архитектуре.</b> Арки порталов Самарканда и Бухары, узоры древних куполов часто составлены из равнобедренных и равносторонних треугольников. Мастера-орнаменталисты чертили такие узоры только циркулем и линейкой.', '<b>In architecture.</b> The arches of portals in Samarkand and Bukhara and the patterns of old domes are often built from isosceles and equilateral triangles. Master ornament-makers drew such patterns with only compass and straightedge.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Misrdagi Xeops piramidasining har bir yon yog‘i teng yonli uchburchak. Asosining tomoni taxminan 230 m, dastlabki balandligi esa 146 m ga yaqin bo‘lgan.', 'Каждая боковая грань пирамиды Хеопса — равнобедренный треугольник. Сторона основания около 230 м, а первоначальная высота — около 146 м.', 'Each face of the Great Pyramid of Khufu is an isosceles triangle. Its base side is about 230 m and its original height was about 146 m.'),
      L('Teng tomonli uchburchaklar bilan tekislikni bo‘shliqsiz qoplash mumkin: har bir uchda oltita 60° li burchak uchrashadi va 360° ni to‘ldiradi.', 'Равносторонними треугольниками можно замостить плоскость без щелей: в каждой вершине сходятся шесть углов по 60°, давая 360°.', 'Equilateral triangles tile the plane without gaps: six 60° angles meet at each vertex and fill 360°.'),
      L('Yo‘l belgilarining ko‘pchiligi — teng tomonli uchburchak shaklida, chunki bu shakl uzoqdan oson taniladi.', 'Многие дорожные знаки — равносторонние треугольники, потому что такую форму легко узнать издалека.', 'Many road signs are equilateral triangles because the shape is easy to recognise from far away.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Teng yonli uchburchakning asosdagi burchagi uchidagi burchakdan 2 marta katta. Burchaklarni toping.', 'Угол при основании равнобедренного треугольника в 2 раза больше угла при вершине. Найдите углы.', 'A base angle of an isosceles triangle is twice the apex angle. Find the angles.'),
      L('Teng yonli uchburchakning tomonlari 4 cm va 9 cm. Perimetrini toping.', 'Стороны равнобедренного треугольника 4 см и 9 см. Найдите периметр.', 'An isosceles triangle has sides of 4 cm and 9 cm. Find its perimeter.'),
      L('Teng yonli to‘g‘ri burchakli uchburchakning o‘tkir burchaklari nechaga teng?', 'Чему равны острые углы равнобедренного прямоугольного треугольника?', 'What are the acute angles of an isosceles right triangle?')
    ], after: [
      L('Javoblar: 1) x + 2x + 2x = 180, x = 36: 36°, 72°, 72°. 2) 4, 4, 9 bo‘lishi mumkin emas (4 + 4 &lt; 9), demak 9, 9, 4: P = 22 cm. 3) 45° va 45°.', 'Ответы: 1) x + 2x + 2x = 180, x = 36: 36°, 72°, 72°. 2) 4, 4, 9 невозможно (4 + 4 &lt; 9), значит 9, 9, 4: P = 22 см. 3) 45° и 45°.', 'Answers: 1) x + 2x + 2x = 180, x = 36: 36°, 72°, 72°. 2) 4, 4, 9 is impossible (4 + 4 &lt; 9), so 9, 9, 4: P = 22 cm. 3) 45° and 45°.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Teng yonli uchburchakda ikki yon tomon teng, uchinchisi — asos.', 'В равнобедренном треугольнике две боковые стороны равны, третья — основание.', 'An isosceles triangle has two equal legs; the third side is the base.'),
      L('Asosdagi burchaklar teng (TTT orqali isbotlanadi).', 'Углы при основании равны (доказывается через ССС).', 'The base angles are equal (proved via SSS).'),
      L('Asosga tushirilgan mediana = bissektrisa = balandlik.', 'Медиана к основанию = биссектриса = высота.', 'The median to the base = the bisector = the altitude.'),
      L('Alomat: ikki burchagi teng uchburchak — teng yonli.', 'Признак: треугольник с двумя равными углами — равнобедренный.', 'Test: a triangle with two equal angles is isosceles.'),
      L('Teng tomonli uchburchakda hamma burchaklar 60°.', 'В равностороннем треугольнике все углы по 60°.', 'In an equilateral triangle every angle is 60°.'),
      L('Bitta burchak berilsa — u uchidami yoki asosdami, ikki holni ko‘ring.', 'Если дан один угол — рассмотрите оба случая: при вершине или при основании.', 'Given one angle, consider both cases: apex or base.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t7. Parallel to‘g‘ri chiziqlar va parallellik alomatlari ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Hech qachon uchrashmaydigan chiziqlar', 'Линии, которые никогда не встречаются', 'Lines that never meet'), p: [
      L('Temir yo‘l relslari ufqqa qadar cho‘zilib ketadi, lekin bir-biriga hech qachon yaqinlashmaydi — aks holda poyezd yo‘ldan chiqib ketardi. Daftar chiziqlari, nota yo‘llari, piyodalar o‘tish joyidagi oq yo‘laklar ham shunday. Bir tekislikda yotib, hech qachon kesishmaydigan to‘g‘ri chiziqlar <b>parallel</b> deyiladi.', 'Рельсы железной дороги тянутся до самого горизонта, но никогда не сближаются — иначе поезд сошёл бы с пути. Так же устроены линейки тетради, нотный стан, белые полосы пешеходного перехода. Прямые, лежащие в одной плоскости и никогда не пересекающиеся, называются <b>параллельными</b>.', 'Railway tracks stretch to the horizon but never get closer — otherwise the train would derail. Notebook lines, music staves and the white stripes of a pedestrian crossing are the same. Lines in one plane that never cross are called <b>parallel</b>.'),
      L('Lekin chiziqlar cheksiz uzun! Ularning hech qachon kesishmasligini qanday tekshiramiz — oxirigacha yurib chiqa olmaymiz-ku? Bu mavzuda shu savolga javob beradigan <b>parallellik alomatlari</b>ni o‘rganamiz: chiziqlar kesuvchi bilan hosil qilgan burchaklarga qarab, ular parallel ekanini isbotlash mumkin. Shuningdek, geometriya tarixidagi eng mashhur aksioma — <b>parallellik aksiomasi</b> bilan tanishamiz.', 'Но прямые бесконечны! Как проверить, что они никогда не пересекутся, — ведь дойти до конца нельзя? В этой теме изучим <b>признаки параллельности</b>, которые отвечают на этот вопрос: по углам, которые прямые образуют с секущей, можно доказать их параллельность. А ещё познакомимся с самой знаменитой аксиомой в истории геометрии — <b>аксиомой параллельных</b>.', 'But lines are infinitely long! How can we check they never cross — we can’t walk to the end? In this topic we study the <b>tests for parallel lines</b> that answer this: the angles the lines make with a transversal can prove they are parallel. We also meet the most famous axiom in the history of geometry — the <b>parallel postulate</b>.')
    ] },
    { kind: 'def', h: L('Parallel chiziqlar va kesuvchi', 'Параллельные прямые и секущая', 'Parallel lines and a transversal'), p: [
      L('<b>Parallel to‘g‘ri chiziqlar</b> — bir tekislikda yotib, kesishmaydigan ikki to‘g‘ri chiziq. Yozuvi: a ∥ b. Ikki kesma yoki nur parallel deyiladi, agar ular parallel to‘g‘ri chiziqlarda yotsa.', '<b>Параллельные прямые</b> — две прямые, которые лежат в одной плоскости и не пересекаются. Запись: a ∥ b. Два отрезка или луча параллельны, если они лежат на параллельных прямых.', '<b>Parallel lines</b> are two lines in one plane that do not meet. Notation: a ∥ b. Two segments or rays are parallel if they lie on parallel lines.'),
      L('Ikki to‘g‘ri chiziqni uchinchi to‘g‘ri chiziq — <b>kesuvchi</b> c kesib o‘tsa, sakkizta burchak hosil bo‘ladi. Ularning juftliklari maxsus nomlarga ega:', 'Если две прямые пересечь третьей — <b>секущей</b> c, образуется восемь углов. Их пары имеют особые названия:', 'If a third line, a <b>transversal</b> c, crosses two lines, eight angles form. Pairs of them have special names:')
    ], list: [
      L('<b>Ichki almashinuvchi (ichki almashinib yotuvchi) burchaklar</b> — a va b orasida, kesuvchining turli tomonlarida yotadi (Z harfi shaklida).', '<b>Накрест лежащие углы</b> — лежат между a и b, по разные стороны от секущей (форма буквы Z).', '<b>Alternate interior angles</b> lie between a and b, on opposite sides of the transversal (a Z shape).'),
      L('<b>Mos burchaklar</b> — biri a va b orasida, ikkinchisi tashqarida, kesuvchining bir tomonida (F harfi shaklida).', '<b>Соответственные углы</b> — один между a и b, другой снаружи, по одну сторону от секущей (форма буквы F).', '<b>Corresponding angles</b> — one between a and b, one outside, on the same side of the transversal (an F shape).'),
      L('<b>Ichki bir tomonli burchaklar</b> — a va b orasida, kesuvchining bir tomonida (C yoki U harfi shaklida).', '<b>Односторонние углы</b> — между a и b, по одну сторону от секущей (форма буквы C или U).', '<b>Co-interior (same-side interior) angles</b> lie between a and b, on the same side of the transversal (a C or U shape).')
    ] },
    { kind: 'history', h: L('Yevklidning beshinchi postulati va Lobachevskiy', 'Пятый постулат Евклида и Лобачевский', 'Euclid’s fifth postulate and Lobachevsky'), p: [
      L('Yevklid «Negizlar»ni beshta postulatdan boshlagan. Dastlabki to‘rttasi qisqa va ravshan edi, beshinchisi esa uzun va murakkab bo‘lgan. Bugungi tilda u shunday yangraydi: <b>to‘g‘ri chiziqda yotmagan nuqta orqali unga parallel faqat bitta to‘g‘ri chiziq o‘tadi</b>. Ikki ming yil davomida matematiklar bu postulatni qolgan to‘rttasidan isbotlashga urinishgan.', 'Евклид начал «Начала» с пяти постулатов. Первые четыре были короткими и ясными, а пятый — длинным и сложным. На современном языке он звучит так: <b>через точку, не лежащую на прямой, проходит только одна прямая, параллельная данной</b>. Две тысячи лет математики пытались доказать этот постулат из остальных четырёх.', 'Euclid opened the <i>Elements</i> with five postulates. The first four were short and clear; the fifth was long and complicated. In modern words it says: <b>through a point not on a line exactly one line parallel to it can be drawn</b>. For two thousand years mathematicians tried to prove this postulate from the other four.'),
      L('Ular orasida Sharq olimlari ham bor: <b>Umar Xayyom</b> (XI–XII asr) va <b>Nasiriddin Tusiy</b> (XIII asr) beshinchi postulat ustida jiddiy ishlagan. Tusiyning ishlari keyinchalik Yevropada ham o‘rganilgan.', 'Среди них были и учёные Востока: <b>Омар Хайям</b> (XI–XII века) и <b>Насир ад-Дин Туси</b> (XIII век) серьёзно работали над пятым постулатом. Труды Туси позже изучали и в Европе.', 'Among them were scholars of the East: <b>Omar Khayyam</b> (11th–12th centuries) and <b>Nasir al-Din al-Tusi</b> (13th century) worked seriously on the fifth postulate. Al-Tusi’s writings were later studied in Europe as well.'),
      L('1826-yili Qozon universiteti professori <b>Nikolay Lobachevskiy</b> dadil qadam qo‘ydi: u beshinchi postulat o‘rniga «nuqta orqali kamida ikkita parallel o‘tadi» degan aksiomani olib, ziddiyatsiz yangi geometriya qurdi. Taxminan shu paytda venger <b>Yanosh Boyai</b> ham shunday natijaga kelgan. Shunday qilib, parallellik aksiomasini isbotlab bo‘lmasligi, u haqiqatan ham aksioma ekani ma’lum bo‘ldi.', 'В 1826 году профессор Казанского университета <b>Николай Лобачевский</b> сделал смелый шаг: заменив пятый постулат аксиомой «через точку проходят по крайней мере две параллельные», он построил новую непротиворечивую геометрию. Примерно тогда же к тому же пришёл венгр <b>Янош Бойяи</b>. Так выяснилось, что аксиому параллельных доказать нельзя — она действительно аксиома.', 'In 1826 <b>Nikolai Lobachevsky</b>, a professor at Kazan University, took a bold step: replacing the fifth postulate with the axiom “at least two parallels pass through the point”, he built a new, consistent geometry. At about the same time the Hungarian <b>János Bolyai</b> reached the same result. So it became clear that the parallel postulate cannot be proved — it really is an axiom.')
    ] },
    { kind: 'rule', h: L('Parallellik alomatlari', 'Признаки параллельности', 'Tests for parallel lines'), p: [
      L('<b>1-alomat.</b> Agar ikki to‘g‘ri chiziqni kesuvchi kesib o‘tganda <b>ichki almashinuvchi burchaklar teng</b> bo‘lsa, bu chiziqlar parallel. <i>Isbot g‘oyasi (teskarisidan faraz):</i> a va b kesuvchini A va B nuqtalarda kesib, almashinuvchi burchaklar teng, lekin a va b biror C nuqtada kesishsin. U holda ABC uchburchak hosil bo‘ladi. Kesuvchining narigi tomonida xuddi shunday uchburchak quramiz (TBT bo‘yicha teng). Shunda A va B orqali a va b chiziqlar ikkinchi marta ham uchrashib, ikkita umumiy nuqtaga ega bo‘lardi — bu «ikki nuqta orqali bitta to‘g‘ri chiziq» aksiomasiga zid. Demak a ∥ b.', '<b>Признак 1.</b> Если при пересечении двух прямых секущей <b>накрест лежащие углы равны</b>, то прямые параллельны. <i>Идея доказательства (от противного):</i> пусть a и b пересекают секущую в точках A и B, накрест лежащие углы равны, но a и b пересекаются в некоторой точке C. Получится треугольник ABC. По другую сторону секущей строим такой же треугольник (равный по СУС). Тогда a и b встретились бы второй раз и имели бы две общие точки — противоречие с аксиомой «через две точки проходит одна прямая». Значит, a ∥ b.', '<b>Test 1.</b> If a transversal crosses two lines and the <b>alternate interior angles are equal</b>, the lines are parallel. <i>Proof idea (by contradiction):</i> let a and b meet the transversal at A and B with equal alternate angles, but suppose a and b meet at some point C. That gives triangle ABC. Build an identical triangle on the other side of the transversal (congruent by SAS). Then a and b would meet a second time and share two points — contradicting the axiom “one line through two points”. So a ∥ b.'),
      L('<b>2-alomat.</b> Agar <b>mos burchaklar teng</b> bo‘lsa, chiziqlar parallel. <i>G‘oya:</i> mos burchakka vertikal bo‘lgan burchak u bilan teng va ayni paytda ikkinchi burchak bilan ichki almashinuvchi — 1-alomatga keldik.', '<b>Признак 2.</b> Если <b>соответственные углы равны</b>, прямые параллельны. <i>Идея:</i> угол, вертикальный соответственному, равен ему и одновременно является накрест лежащим со вторым углом — пришли к признаку 1.', '<b>Test 2.</b> If <b>corresponding angles are equal</b>, the lines are parallel. <i>Idea:</i> the angle vertical to one corresponding angle equals it and is alternate to the other — reducing to test 1.'),
      L('<b>3-alomat.</b> Agar <b>ichki bir tomonli burchaklar yig‘indisi 180°</b> bo‘lsa, chiziqlar parallel. <i>G‘oya:</i> bir tomonli burchaklardan biriga qo‘shni burchak 180° − ∠1 = ∠2 bo‘ladi va u ∠2 bilan almashinuvchi — yana 1-alomat.', '<b>Признак 3.</b> Если <b>сумма односторонних углов равна 180°</b>, прямые параллельны. <i>Идея:</i> угол, смежный с одним из односторонних, равен 180° − ∠1 = ∠2 и является накрест лежащим с ∠2 — снова признак 1.', '<b>Test 3.</b> If the <b>co-interior angles add up to 180°</b>, the lines are parallel. <i>Idea:</i> the angle adjacent to one co-interior angle is 180° − ∠1 = ∠2, and it is alternate to ∠2 — test 1 again.'),
      L('<b>Natija:</b> bitta to‘g‘ri chiziqqa perpendikulyar ikki to‘g‘ri chiziq parallel (mos burchaklar 90° ga teng). <b>Aksioma:</b> chiziqda yotmagan nuqta orqali unga parallel faqat bitta to‘g‘ri chiziq o‘tadi.', '<b>Следствие:</b> две прямые, перпендикулярные третьей, параллельны (соответственные углы по 90°). <b>Аксиома:</b> через точку вне прямой проходит только одна прямая, параллельная данной.', '<b>Corollary:</b> two lines perpendicular to a third are parallel (corresponding angles are 90°). <b>Axiom:</b> through a point off a line exactly one parallel line passes.')
    ] },
    { kind: 'steps', h: L('Parallellikni qanday isbotlash', 'Как доказать параллельность', 'How to prove lines are parallel'), list: [
      L('1-qadam. Ikki chiziqni kesib o‘tuvchi kesuvchini toping (yoki o‘zingiz o‘tkazing).', 'Шаг 1. Найдите секущую, пересекающую обе прямые (или проведите её).', 'Step 1. Find a transversal crossing both lines (or draw one).'),
      L('2-qadam. Berilgan burchaklar qanday juftlik ekanini aniqlang: almashinuvchi (Z), mos (F) yoki bir tomonli (C).', 'Шаг 2. Определите, какую пару образуют данные углы: накрест лежащие (Z), соответственные (F) или односторонние (C).', 'Step 2. Identify which pair the given angles form: alternate (Z), corresponding (F) or co-interior (C).'),
      L('3-qadam. Shartni tekshiring: Z va F uchun — tenglik, C uchun — yig‘indi 180°.', 'Шаг 3. Проверьте условие: для Z и F — равенство, для C — сумма 180°.', 'Step 3. Check the condition: for Z and F — equality; for C — a sum of 180°.'),
      L('4-qadam. Agar burchaklar boshqa joyda berilgan bo‘lsa, vertikal va qo‘shni burchaklar yordamida kerakli juftlikka o‘ting.', 'Шаг 4. Если углы даны в другом месте, перейдите к нужной паре с помощью вертикальных и смежных углов.', 'Step 4. If the angles are given elsewhere, move to a suitable pair using vertical and adjacent angles.'),
      L('5-qadam. Xulosa yozing: «… alomatiga ko‘ra a ∥ b».', 'Шаг 5. Запишите вывод: «по признаку … a ∥ b».', 'Step 5. Write the conclusion: “by test …, a ∥ b”.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('a va b ni c kesuvchi kesib o‘tadi. Ichki almashinuvchi burchaklar 47° va 47°. a ∥ b mi?', 'Прямые a и b пересечены секущей c. Накрест лежащие углы 47° и 47°. a ∥ b?', 'Lines a and b are cut by transversal c. The alternate interior angles are 47° and 47°. Is a ∥ b?'), s: L('Almashinuvchi burchaklar teng — 1-alomat bo‘yicha <b>a ∥ b</b>.', 'Накрест лежащие углы равны — по признаку 1 <b>a ∥ b</b>.', 'The alternate angles are equal — by test 1, <b>a ∥ b</b>.') },
      { q: L('Ichki bir tomonli burchaklar 72° va 118°. Chiziqlar parallelmi?', 'Односторонние углы 72° и 118°. Параллельны ли прямые?', 'The co-interior angles are 72° and 118°. Are the lines parallel?'), s: L('72° + 118° = 190° ≠ 180°. Demak <b>parallel emas</b>. Ular yig‘indi 180° dan katta bo‘lgan tomonga qarama-qarshi tarafda — ya’ni burchaklar yig‘indisi kichik bo‘lgan tomonda kesishadi.', '72° + 118° = 190° ≠ 180°. Значит, <b>не параллельны</b>. Они пересекутся с той стороны секущей, где сумма односторонних углов меньше 180°.', '72° + 118° = 190° ≠ 180°. So they are <b>not parallel</b>. They meet on the side of the transversal where the co-interior angles sum to less than 180°.') },
      { q: L('Kesuvchi a bilan 65° li burchak hosil qiladi, b bilan esa unga vertikal bo‘lmagan, lekin mos burchakka qo‘shni bo‘lgan 115° li burchak. a ∥ b ekanini ko‘rsating.', 'Секущая образует с a угол 65°, а с b — угол 115°, смежный с углом, соответственным первому. Покажите, что a ∥ b.', 'The transversal makes a 65° angle with a, and with b a 115° angle adjacent to the angle corresponding to the first. Show that a ∥ b.'), s: L('115° ga qo‘shni burchak: 180° − 115° = 65°. Bu burchak birinchi 65° li burchakka mos. Mos burchaklar teng — 2-alomat bo‘yicha <b>a ∥ b</b>.', 'Угол, смежный с 115°: 180° − 115° = 65°. Он соответственный первому углу 65°. Соответственные углы равны — по признаку 2 <b>a ∥ b</b>.', 'The angle adjacent to 115° is 180° − 115° = 65°. It corresponds to the first 65° angle. Corresponding angles are equal — by test 2, <b>a ∥ b</b>.') },
      { q: L('AB va CD kesmalar O nuqtada kesishib, unda teng ikkiga bo‘linadi. AC ∥ BD ekanini isbotlang.', 'Отрезки AB и CD пересекаются в точке O и делятся ею пополам. Докажите, что AC ∥ BD.', 'Segments AB and CD cross at O, which bisects both. Prove AC ∥ BD.'), s: L('△AOC = △BOD (TBT: AO = OB, CO = OD, vertikal burchaklar). Demak ∠OAC = ∠OBD. Bu burchaklar AC va BD chiziqlari hamda AB kesuvchi uchun ichki almashinuvchi. 1-alomat bo‘yicha <b>AC ∥ BD</b>.', '△AOC = △BOD (СУС: AO = OB, CO = OD, вертикальные углы). Значит ∠OAC = ∠OBD. Это накрест лежащие углы для прямых AC и BD и секущей AB. По признаку 1 <b>AC ∥ BD</b>.', '△AOC ≅ △BOD (SAS: AO = OB, CO = OD, vertical angles). So ∠OAC = ∠OBD. These are alternate angles for lines AC and BD with transversal AB. By test 1, <b>AC ∥ BD</b>.') }
    ] },
    { kind: 'table', h: L('Burchak juftliklari va alomatlar', 'Пары углов и признаки', 'Angle pairs and tests'), table: { head: [L('Juftlik', 'Пара', 'Pair'), L('Shakli', 'Форма', 'Shape'), L('a ∥ b bo‘lishi uchun', 'Условие a ∥ b', 'Condition for a ∥ b')], rows: [
      [L('ichki almashinuvchi', 'накрест лежащие', 'alternate interior'), 'Z', L('teng', 'равны', 'equal')],
      [L('mos', 'соответственные', 'corresponding'), 'F', L('teng', 'равны', 'equal')],
      [L('ichki bir tomonli', 'односторонние', 'co-interior'), 'C', L('yig‘indisi 180°', 'сумма 180°', 'sum 180°')],
      [L('tashqi almashinuvchi', 'внешние накрест лежащие', 'alternate exterior'), L('tashqi Z', 'внешняя Z', 'outer Z'), L('teng', 'равны', 'equal')]
    ] }, after: [
      L('Barcha alomatlar aslida bitta — 1-alomatga keltiriladi. Vertikal va qo‘shni burchaklar xossalari bir juftlikdan ikkinchisiga o‘tish uchun «ko‘prik» vazifasini bajaradi.', 'Все признаки по сути сводятся к одному — признаку 1. Свойства вертикальных и смежных углов служат «мостиком» от одной пары к другой.', 'All the tests really reduce to one — test 1. Vertical and adjacent angle properties act as a “bridge” from one pair to another.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Chizmaga ishonish.</b> Chiziqlar parallel «ko‘rinsa» ham, isbotsiz bunday xulosa qilmang.', '<b>Доверять чертежу.</b> Даже если прямые «выглядят» параллельными, без доказательства так не говорите.', '<b>Trusting the drawing.</b> Even if lines “look” parallel, do not say so without proof.'),
      L('<b>Bir tomonli burchaklarni teng deb kutish.</b> Ular teng emas, yig‘indisi 180° bo‘lishi kerak.', '<b>Ждать равенства односторонних углов.</b> Они не равны — их сумма должна быть 180°.', '<b>Expecting co-interior angles to be equal.</b> They are not equal — they must sum to 180°.'),
      L('<b>Juftlik turini adashtirish.</b> Z, F, C harflarini chizmada qidiring — bu eng ishonchli usul.', '<b>Путать тип пары.</b> Ищите на чертеже буквы Z, F, C — это самый надёжный способ.', '<b>Mixing up pair types.</b> Look for the letters Z, F, C on the drawing — the most reliable method.'),
      L('<b>Alomat va xossani aralashtirish.</b> Alomat: «burchaklar teng ⇒ parallel». Xossa (8-mavzu): «parallel ⇒ burchaklar teng». Bular teskari teoremalar.', '<b>Путать признак и свойство.</b> Признак: «углы равны ⇒ параллельны». Свойство (тема 8): «параллельны ⇒ углы равны». Это обратные теоремы.', '<b>Confusing a test with a property.</b> Test: “angles equal ⇒ parallel”. Property (topic 8): “parallel ⇒ angles equal”. These are converse theorems.'),
      L('<b>Fazodagi chiziqlarni unutish.</b> Fazoda kesishmaydigan, lekin parallel bo‘lmagan chiziqlar ham bor (ayqash chiziqlar). Ta’rifdagi «bir tekislikda» so‘zi shuning uchun muhim.', '<b>Забывать о прямых в пространстве.</b> В пространстве есть непересекающиеся, но непараллельные прямые (скрещивающиеся). Поэтому слова «в одной плоскости» в определении важны.', '<b>Forgetting lines in space.</b> In space there are lines that never meet yet are not parallel (skew lines). That is why “in one plane” matters in the definition.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Chizmachilikda.</b> Parallel chiziq chizish uchun go‘nyoni chizg‘ich bo‘ylab siljitamiz: go‘nyo chizg‘ich bilan doim bir xil burchak hosil qiladi, demak mos burchaklar teng — chiziqlar parallel. Bu 2-alomatning amaliy qo‘llanishi.', '<b>В черчении.</b> Чтобы провести параллельные прямые, двигают угольник вдоль линейки: угольник всегда образует с линейкой один и тот же угол, значит соответственные углы равны — прямые параллельны. Это практическое применение признака 2.', '<b>In technical drawing.</b> To draw parallel lines, slide a set square along a ruler: the set square always makes the same angle with the ruler, so corresponding angles are equal and the lines are parallel. That is test 2 in practice.'),
      L('<b>Yo‘l qurilishida.</b> Ko‘p qatorli yo‘l chiziqlari, ko‘prik to‘siqlari, avtoturargoh joylari parallel qilib belgilanadi. Ishchilar ko‘ndalang chiziq bilan bir xil burchakni tekshirib, chiziqlar parallelligiga ishonch hosil qiladi.', '<b>В дорожном строительстве.</b> Разметку многополосной дороги, ограждения мостов, места на парковке делают параллельными. Рабочие проверяют одинаковый угол с поперечной линией и убеждаются в параллельности.', '<b>In road building.</b> Lane markings, bridge railings and parking spaces are laid out parallel. Workers check the same angle against a cross line to make sure the lines are parallel.'),
      L('<b>Duradgorlikda.</b> Javon tokchalari yon devorga perpendikulyar qilib o‘rnatiladi — natijada ular o‘zaro parallel bo‘ladi.', '<b>В столярном деле.</b> Полки ставят перпендикулярно боковой стенке — в результате они параллельны друг другу.', '<b>In carpentry.</b> Shelves are fixed perpendicular to the side panel — as a result they are parallel to each other.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Shar sirtida (masalan, Yer globusida) «to‘g‘ri chiziqlar» — katta aylanalar, va ular doim kesishadi. Ekvatorga perpendikulyar meridianlar qutblarda uchrashadi! Bu — parallel chiziqlari umuman yo‘q bo‘lgan geometriya.', 'На поверхности шара (например, глобуса) «прямые» — большие окружности, и они всегда пересекаются. Меридианы, перпендикулярные экватору, встречаются на полюсах! Это геометрия, в которой параллельных вообще нет.', 'On the surface of a sphere (a globe, say) the “straight lines” are great circles, and they always meet. Meridians perpendicular to the equator meet at the poles! It is a geometry with no parallels at all.'),
      L('Eynshteynning umumiy nisbiylik nazariyasi Yevklidniki bo‘lmagan geometriyalardan foydalanadi: katta massa atrofida fazo «egiladi».', 'Общая теория относительности Эйнштейна использует неевклидовы геометрии: вокруг больших масс пространство «искривляется».', 'Einstein’s general theory of relativity uses non-Euclidean geometry: space “curves” around large masses.'),
      L('Uzoqqa ketayotgan relslar ufqda «kesishgandek» ko‘rinadi. Bu ko‘z aldanishi — perspektiva. Rassomlar bu qonuniyatdan suratga chuqurlik berish uchun foydalanadi.', 'Уходящие вдаль рельсы будто «сходятся» на горизонте. Это обман зрения — перспектива. Художники пользуются им, чтобы придать картине глубину.', 'Rails running into the distance seem to “meet” at the horizon. That is an illusion — perspective. Artists use it to give their pictures depth.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Mos burchaklar 3x va 2x + 20°. x ning qanday qiymatida a ∥ b?', 'Соответственные углы 3x и 2x + 20°. При каком x a ∥ b?', 'Corresponding angles are 3x and 2x + 20°. For which x is a ∥ b?'),
      L('Ichki bir tomonli burchaklar 4 : 5 nisbatda va a ∥ b. Ularni toping.', 'Односторонние углы относятся как 4 : 5 и a ∥ b. Найдите их.', 'The co-interior angles are in the ratio 4 : 5 and a ∥ b. Find them.'),
      L('Nega daftar chiziqlari parallel? Qaysi alomat bilan tushuntirasiz?', 'Почему линейки тетради параллельны? Каким признаком объясните?', 'Why are the lines in a notebook parallel? Which test explains it?')
    ], after: [
      L('Javoblar: 1) 3x = 2x + 20, x = 20°. 2) 9 ulush = 180°: 80° va 100°. 3) Ular varaq chetiga perpendikulyar — bir chiziqqa perpendikulyar chiziqlar parallel.', 'Ответы: 1) 3x = 2x + 20, x = 20°. 2) 9 частей = 180°: 80° и 100°. 3) Они перпендикулярны краю листа — прямые, перпендикулярные одной прямой, параллельны.', 'Answers: 1) 3x = 2x + 20, x = 20°. 2) 9 parts = 180°: 80° and 100°. 3) They are perpendicular to the page edge — lines perpendicular to one line are parallel.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Parallel chiziqlar bir tekislikda yotadi va kesishmaydi: a ∥ b.', 'Параллельные прямые лежат в одной плоскости и не пересекаются: a ∥ b.', 'Parallel lines lie in one plane and never meet: a ∥ b.'),
      L('Kesuvchi sakkiz burchak hosil qiladi: almashinuvchi (Z), mos (F), bir tomonli (C).', 'Секущая образует восемь углов: накрест лежащие (Z), соответственные (F), односторонние (C).', 'A transversal makes eight angles: alternate (Z), corresponding (F), co-interior (C).'),
      L('Alomatlar: almashinuvchilar teng, yoki moslar teng, yoki bir tomonlilar yig‘indisi 180° ⇒ a ∥ b.', 'Признаки: накрест лежащие равны, или соответственные равны, или сумма односторонних 180° ⇒ a ∥ b.', 'Tests: alternate equal, or corresponding equal, or co-interior summing to 180° ⇒ a ∥ b.'),
      L('Bir chiziqqa perpendikulyar ikki chiziq parallel.', 'Две прямые, перпендикулярные третьей, параллельны.', 'Two lines perpendicular to a third are parallel.'),
      L('Parallellik aksiomasi: nuqta orqali bitta parallel; Lobachevskiy uni o‘zgartirib, yangi geometriya yaratgan.', 'Аксиома параллельных: через точку — одна параллельная; Лобачевский, изменив её, создал новую геометрию.', 'Parallel postulate: one parallel through a point; Lobachevsky changed it and created a new geometry.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t8. Parallel to‘g‘ri chiziqlar va kesuvchi hosil qilgan burchaklar ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('Teskari yo‘nalishda', 'В обратную сторону', 'Going the other way'), p: [
      L('Oldingi mavzuda biz burchaklarga qarab chiziqlarning parallelligini isbotladik. Endi teskari savolni beramiz: agar chiziqlar parallel ekani <b>allaqachon ma’lum</b> bo‘lsa, kesuvchi hosil qilgan burchaklar haqida nima deyish mumkin? Javob juda chiroyli: sakkizta burchakdan faqat <b>ikki xil qiymat</b> chiqadi. Bittasini bilsangiz, qolgan yettitasini o‘lchamasdan topasiz.', 'В прошлой теме мы по углам доказывали параллельность прямых. Теперь зададим обратный вопрос: если <b>уже известно</b>, что прямые параллельны, что можно сказать об углах, образованных секущей? Ответ очень красивый: у восьми углов всего <b>два разных значения</b>. Зная один угол, остальные семь найдёте без измерения.', 'In the previous topic we used angles to prove that lines are parallel. Now we ask the reverse question: if we <b>already know</b> the lines are parallel, what can we say about the angles the transversal makes? The answer is beautiful: the eight angles take only <b>two different values</b>. Know one, and you get the other seven without measuring.'),
      L('Bu mavzu «teskari teorema» tushunchasini ham o‘rgatadi. Har bir teoremada shart va xulosa bor; ularning o‘rnini almashtirsak, teskari teorema hosil bo‘ladi. U doim ham to‘g‘ri bo‘lavermaydi — shuning uchun alohida isbotlanadi. Bu yerdagi teskari teoremalarni isbotlashda esa parallellik aksiomasi hal qiluvchi rol o‘ynaydi.', 'Эта тема знакомит и с понятием «обратная теорема». В каждой теореме есть условие и заключение; поменяв их местами, получим обратную теорему. Она верна не всегда — поэтому её доказывают отдельно. А в доказательстве здешних обратных теорем решающую роль играет аксиома параллельных.', 'This topic also introduces the idea of a “converse theorem”. Every theorem has a hypothesis and a conclusion; swapping them gives the converse. A converse is not always true, so it must be proved separately. Here, proving the converses depends crucially on the parallel postulate.')
    ] },
    { kind: 'def', h: L('Teorema va teskari teorema', 'Теорема и обратная теорема', 'Theorem and converse'), p: [
      L('Teorema odatda «agar …, u holda …» ko‘rinishida yoziladi. «Agar» qismi — <b>shart</b>, «u holda» qismi — <b>xulosa</b>. Masalan: «Agar almashinuvchi burchaklar teng bo‘lsa, u holda chiziqlar parallel» (alomat). Teskarisi: «Agar chiziqlar parallel bo‘lsa, u holda almashinuvchi burchaklar teng» (xossa).', 'Теорему обычно записывают в виде «если …, то …». Часть «если» — <b>условие</b>, часть «то» — <b>заключение</b>. Например: «Если накрест лежащие углы равны, то прямые параллельны» (признак). Обратная: «Если прямые параллельны, то накрест лежащие углы равны» (свойство).', 'A theorem is usually written “if …, then …”. The “if” part is the <b>hypothesis</b>, the “then” part the <b>conclusion</b>. For example: “If alternate angles are equal, then the lines are parallel” (a test). Its converse: “If the lines are parallel, then alternate angles are equal” (a property).'),
      L('Teskari teorema har doim ham to‘g‘ri emas. Masalan, «vertikal burchaklar teng» to‘g‘ri, lekin «teng burchaklar vertikal» — noto‘g‘ri (teng burchaklar istalgan joyda bo‘lishi mumkin). Shuning uchun har bir teskari teoremani alohida isbotlash kerak.', 'Обратная теорема верна не всегда. Например, «вертикальные углы равны» — верно, а «равные углы вертикальны» — неверно (равные углы могут быть где угодно). Поэтому каждую обратную теорему нужно доказывать отдельно.', 'A converse is not always true. For example, “vertical angles are equal” is true, but “equal angles are vertical” is false (equal angles can be anywhere). So each converse must be proved on its own.')
    ] },
    { kind: 'history', h: L('Aksiomaning kuchi', 'Сила аксиомы', 'The power of an axiom'), p: [
      L('Yevklid «Negizlar» birinchi kitobining 27–28-tasdiqlarida parallellik alomatlarini beshinchi postulatsiz isbotlagan. Ammo 29-tasdiqda — parallel chiziqlardagi burchaklar xossasida — u birinchi marta beshinchi postulatdan foydalanishga majbur bo‘lgan. Tarixchilar Yevklid bu postulatni imkon qadar kech ishlatishga harakat qilganini qayd etishadi.', 'В предложениях 27–28 первой книги «Начал» Евклид доказал признаки параллельности без пятого постулата. Но в предложении 29 — о свойствах углов при параллельных — он впервые был вынужден применить пятый постулат. Историки отмечают, что Евклид старался использовать этот постулат как можно позже.', 'In Propositions 27–28 of Book I of the <i>Elements</i>, Euclid proved the tests for parallels without the fifth postulate. But in Proposition 29 — the property of angles at parallel lines — he had to use the fifth postulate for the first time. Historians note that Euclid tried to use this postulate as late as possible.'),
      L('Aynan shuning uchun Lobachevskiy geometriyasida parallellik alomatlari to‘g‘ri bo‘lib qoladi, lekin bu mavzudagi xossalar bajarilmaydi: u yerda parallel chiziqlar kesuvchi bilan teng bo‘lmagan almashinuvchi burchaklar hosil qilishi mumkin. Bu ikki geometriyani ajratib turuvchi aniq chegara.', 'Именно поэтому в геометрии Лобачевского признаки параллельности остаются верными, а свойства из этой темы не выполняются: там параллельные прямые могут образовывать с секущей неравные накрест лежащие углы. Это чёткая граница между двумя геометриями.', 'That is why in Lobachevsky’s geometry the tests for parallels remain true but the properties in this topic fail: there, parallel lines can make unequal alternate angles with a transversal. This is the exact line separating the two geometries.')
    ] },
    { kind: 'rule', h: L('Parallel chiziqlardagi burchaklar xossalari', 'Свойства углов при параллельных прямых', 'Properties of angles at parallel lines'), p: [
      L('<b>Teorema 1.</b> Agar ikki parallel to‘g‘ri chiziqni kesuvchi kesib o‘tsa, <b>ichki almashinuvchi burchaklar teng</b>. <i>Isbot (teskarisidan faraz):</i> a ∥ b, c kesuvchi a ni A da, b ni B da kesadi, lekin almashinuvchi burchaklar teng emas deylik. A nuqta orqali a₁ chiziqni shunday o‘tkazamizki, u c bilan teng almashinuvchi burchak hosil qilsin. Alomatga ko‘ra a₁ ∥ b. Natijada A nuqta orqali b ga parallel ikkita chiziq — a va a₁ o‘tadi. Bu parallellik aksiomasiga zid. Demak burchaklar teng.', '<b>Теорема 1.</b> Если две параллельные прямые пересечены секущей, то <b>накрест лежащие углы равны</b>. <i>Доказательство (от противного):</i> пусть a ∥ b, секущая c пересекает a в A и b в B, но накрест лежащие углы не равны. Проведём через A прямую a₁ так, чтобы она образовала с c равный накрест лежащий угол. По признаку a₁ ∥ b. Тогда через A проходят две прямые, параллельные b, — a и a₁. Это противоречит аксиоме параллельных. Значит, углы равны.', '<b>Theorem 1.</b> If two parallel lines are cut by a transversal, the <b>alternate interior angles are equal</b>. <i>Proof (by contradiction):</i> let a ∥ b, with c cutting a at A and b at B, and suppose the alternate angles are not equal. Through A draw a line a₁ making an equal alternate angle with c. By the test, a₁ ∥ b. Then two lines parallel to b — a and a₁ — pass through A. That contradicts the parallel postulate. So the angles are equal.'),
      L('<b>Teorema 2.</b> Parallel chiziqlarda <b>mos burchaklar teng</b>. (Mos burchak almashinuvchi burchakka vertikal.)', '<b>Теорема 2.</b> При параллельных прямых <b>соответственные углы равны</b>. (Соответственный угол вертикален накрест лежащему.)', '<b>Theorem 2.</b> At parallel lines <b>corresponding angles are equal</b>. (A corresponding angle is vertical to an alternate one.)'),
      L('<b>Teorema 3.</b> Parallel chiziqlarda <b>ichki bir tomonli burchaklar yig‘indisi 180°</b>. (Bir tomonli burchak almashinuvchi burchakka qo‘shni.)', '<b>Теорема 3.</b> При параллельных прямых <b>сумма односторонних углов равна 180°</b>. (Односторонний угол смежен накрест лежащему.)', '<b>Theorem 3.</b> At parallel lines <b>co-interior angles add up to 180°</b>. (A co-interior angle is adjacent to an alternate one.)'),
      L('<b>Natija:</b> agar to‘g‘ri chiziq ikki parallel chiziqdan biriga perpendikulyar bo‘lsa, ikkinchisiga ham perpendikulyar. Sakkizta burchakning hammasi α yoki 180° − α ga teng.', '<b>Следствие:</b> если прямая перпендикулярна одной из двух параллельных, то она перпендикулярна и другой. Все восемь углов равны α или 180° − α.', '<b>Corollary:</b> a line perpendicular to one of two parallel lines is perpendicular to the other too. All eight angles equal α or 180° − α.')
    ] },
    { kind: 'steps', h: L('Sakkiz burchakni topish', 'Как найти все восемь углов', 'Finding all eight angles'), list: [
      L('1-qadam. Burchaklarni 1 dan 8 gacha raqamlang: a chiziqdagi to‘rttasi 1–4, b dagi to‘rttasi 5–8, bir xil tartibda (masalan, soat strelkasi bo‘yicha).', 'Шаг 1. Пронумеруйте углы от 1 до 8: четыре у прямой a — 1–4, четыре у b — 5–8, в одном и том же порядке (например, по часовой стрелке).', 'Step 1. Number the angles 1 to 8: the four at line a are 1–4 and the four at line b are 5–8, in the same order (say, clockwise).'),
      L('2-qadam. Berilgan burchak α bo‘lsin. Unga vertikal burchak ham α.', 'Шаг 2. Пусть данный угол α. Вертикальный ему тоже α.', 'Step 2. Let the given angle be α. The angle vertical to it is also α.'),
      L('3-qadam. Unga qo‘shni ikki burchak 180° − α.', 'Шаг 3. Два смежных с ним угла равны 180° − α.', 'Step 3. The two angles adjacent to it are 180° − α.'),
      L('4-qadam. Ikkinchi chiziqqa «ko‘chiring»: mos burchaklar teng, shuning uchun b dagi to‘rtta burchak a dagilarni xuddi o‘sha tartibda takrorlaydi.', 'Шаг 4. «Перенесите» на вторую прямую: соответственные углы равны, поэтому четыре угла у b повторяют углы у a в том же порядке.', 'Step 4. “Copy” to the second line: corresponding angles are equal, so the four angles at b repeat those at a in the same order.'),
      L('5-qadam. Tekshiring: o‘tkir burchaklar bir-biriga, o‘tmaslar bir-biriga teng; har qanday o‘tkir + o‘tmas = 180°.', 'Шаг 5. Проверьте: острые углы равны между собой, тупые — между собой; любой острый + любой тупой = 180°.', 'Step 5. Check: all the acute angles are equal, all the obtuse ones are equal; any acute + any obtuse = 180°.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('a ∥ b, kesuvchi bilan hosil bo‘lgan burchaklardan biri 58°. Qolgan yettitasini toping.', 'a ∥ b, один из углов с секущей равен 58°. Найдите остальные семь.', 'a ∥ b and one of the angles with the transversal is 58°. Find the other seven.'), s: L('Faqat ikki qiymat bor: 58° va 180° − 58° = 122°. To‘rtta burchak <b>58°</b>, to‘rttasi <b>122°</b>.', 'Есть только два значения: 58° и 180° − 58° = 122°. Четыре угла по <b>58°</b>, четыре — по <b>122°</b>.', 'There are only two values: 58° and 180° − 58° = 122°. Four angles are <b>58°</b>, four are <b>122°</b>.') },
      { q: L('a ∥ b. Ichki bir tomonli burchaklardan biri ikkinchisidan 40° katta. Ularni toping.', 'a ∥ b. Один из односторонних углов на 40° больше другого. Найдите их.', 'a ∥ b. One co-interior angle is 40° bigger than the other. Find them.'), s: L('x + (x + 40) = 180, 2x = 140, x = <b>70°</b>, ikkinchisi <b>110°</b>.', 'x + (x + 40) = 180, 2x = 140, x = <b>70°</b>, второй <b>110°</b>.', 'x + (x + 40) = 180, 2x = 140, x = <b>70°</b>; the other is <b>110°</b>.') },
      { q: L('a ∥ b. Mos burchaklar 5x − 20° va 3x + 30°. x ni va burchaklarni toping.', 'a ∥ b. Соответственные углы 5x − 20° и 3x + 30°. Найдите x и углы.', 'a ∥ b. Corresponding angles are 5x − 20° and 3x + 30°. Find x and the angles.'), s: L('Mos burchaklar teng: 5x − 20 = 3x + 30, 2x = 50, x = 25. Burchak: 5 · 25 − 20 = <b>105°</b>.', 'Соответственные равны: 5x − 20 = 3x + 30, 2x = 50, x = 25. Угол: 5 · 25 − 20 = <b>105°</b>.', 'Corresponding angles are equal: 5x − 20 = 3x + 30, 2x = 50, x = 25. Angle: 5 · 25 − 20 = <b>105°</b>.') },
      { q: L('AB ∥ CD. BC kesma AB bilan 35° li burchak hosil qiladi (∠ABC = 35°). ∠BCD ni toping, agar A va D BC ning turli tomonida bo‘lsa.', 'AB ∥ CD. Отрезок BC образует с AB угол ∠ABC = 35°. Найдите ∠BCD, если A и D по разные стороны от BC.', 'AB ∥ CD. Segment BC makes ∠ABC = 35° with AB. Find ∠BCD if A and D are on opposite sides of BC.'), s: L('A va D BC ning turli tomonida — demak ∠ABC va ∠BCD ichki almashinuvchi. Parallel chiziqlarda ular teng: ∠BCD = <b>35°</b>.', 'A и D по разные стороны от BC — значит ∠ABC и ∠BCD накрест лежащие. При параллельных прямых они равны: ∠BCD = <b>35°</b>.', 'A and D are on opposite sides of BC, so ∠ABC and ∠BCD are alternate. At parallel lines they are equal: ∠BCD = <b>35°</b>.') }
    ] },
    { kind: 'table', h: L('Alomat va xossa yonma-yon', 'Признак и свойство рядом', 'Test and property side by side'), table: { head: [L('Juftlik', 'Пара', 'Pair'), L('Alomat (burchak ⇒ ∥)', 'Признак (углы ⇒ ∥)', 'Test (angles ⇒ ∥)'), L('Xossa (∥ ⇒ burchak)', 'Свойство (∥ ⇒ углы)', 'Property (∥ ⇒ angles)')], rows: [
      [L('almashinuvchi', 'накрест лежащие', 'alternate'), L('teng ⇒ a ∥ b', 'равны ⇒ a ∥ b', 'equal ⇒ a ∥ b'), L('a ∥ b ⇒ teng', 'a ∥ b ⇒ равны', 'a ∥ b ⇒ equal')],
      [L('mos', 'соответственные', 'corresponding'), L('teng ⇒ a ∥ b', 'равны ⇒ a ∥ b', 'equal ⇒ a ∥ b'), L('a ∥ b ⇒ teng', 'a ∥ b ⇒ равны', 'a ∥ b ⇒ equal')],
      [L('bir tomonli', 'односторонние', 'co-interior'), L('180° ⇒ a ∥ b', '180° ⇒ a ∥ b', '180° ⇒ a ∥ b'), L('a ∥ b ⇒ 180°', 'a ∥ b ⇒ 180°', 'a ∥ b ⇒ 180°')],
      [L('Isbotda kerak', 'Нужно в доказательстве', 'Needed in proof'), L('aksiomasiz', 'без аксиомы', 'no postulate'), L('parallellik aksiomasi', 'аксиома параллельных', 'the parallel postulate')]
    ] }, after: [
      L('Masalada qaysi teoremani ishlatishni aniqlash oson: agar chiziqlarning parallelligi <i>berilgan</i> bo‘lsa — xossa; agar uni <i>isbotlash kerak</i> bo‘lsa — alomat.', 'Какую теорему применить, определить легко: если параллельность прямых <i>дана</i> — свойство; если её <i>нужно доказать</i> — признак.', 'Choosing the theorem is easy: if parallelism is <i>given</i>, use a property; if it must be <i>proved</i>, use a test.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Parallellik berilmagan holda xossani ishlatish.</b> Chiziqlar parallel ekani ma’lum bo‘lmasa, almashinuvchi burchaklar teng bo‘lmasligi mumkin.', '<b>Применять свойство без данной параллельности.</b> Если не известно, что прямые параллельны, накрест лежащие углы могут быть не равны.', '<b>Using a property without given parallelism.</b> If the lines are not known to be parallel, alternate angles need not be equal.'),
      L('<b>Bir tomonli burchaklarni tenglashtirish.</b> 5x − 20 = 3x + 30 tenglama faqat mos yoki almashinuvchi burchaklar uchun. Bir tomonlilar uchun: (5x − 20) + (3x + 30) = 180.', '<b>Приравнивать односторонние углы.</b> Уравнение 5x − 20 = 3x + 30 — только для соответственных или накрест лежащих. Для односторонних: (5x − 20) + (3x + 30) = 180.', '<b>Setting co-interior angles equal.</b> The equation 5x − 20 = 3x + 30 is only for corresponding or alternate angles. For co-interior: (5x − 20) + (3x + 30) = 180.'),
      L('<b>Noto‘g‘ri kesuvchini tanlash.</b> Chizmada bir nechta chiziq bo‘lsa, qaysi ikkitasi parallel va qaysi biri kesuvchi ekanini aniq belgilang.', '<b>Выбирать «не ту» секущую.</b> Если на чертеже несколько прямых, чётко отметьте, какие две параллельны и какая — секущая.', '<b>Choosing the wrong transversal.</b> With several lines in the figure, mark clearly which two are parallel and which is the transversal.'),
      L('<b>Teskari teoremani avtomatik to‘g‘ri deb hisoblash.</b> Har bir teskari tasdiq alohida isbot talab qiladi.', '<b>Считать обратную теорему верной автоматически.</b> Каждое обратное утверждение требует отдельного доказательства.', '<b>Assuming a converse is automatically true.</b> Every converse needs its own proof.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Zinapoyada.</b> Zina pog‘onalari o‘zaro parallel, panjara esa ularni kesuvchi. Shuning uchun panjaraning har bir pog‘ona bilan hosil qilgan burchagi bir xil — usta faqat bitta burchakni o‘lchaydi.', '<b>На лестнице.</b> Ступени параллельны друг другу, а перила — секущая. Поэтому угол между перилами и каждой ступенью одинаков — мастер измеряет только один угол.', '<b>On a staircase.</b> The steps are parallel and the handrail is a transversal. So the rail makes the same angle with every step — the builder measures only one angle.'),
      L('<b>Optikada.</b> Quyosh nurlari Yerga deyarli parallel tushadi. Qadimgi olim <b>Eratosfen</b> Siyena va Iskandariyada nurlarning tushish burchaklarini taqqoslab, parallel chiziqlardagi almashinuvchi burchaklar tengligidan foydalanib Yer aylanasini o‘lchagan.', '<b>В оптике.</b> Солнечные лучи падают на Землю почти параллельно. Древний учёный <b>Эратосфен</b>, сравнив углы падения лучей в Сиене и Александрии, по равенству накрест лежащих углов при параллельных измерил окружность Земли.', '<b>In optics.</b> Sunlight reaches the Earth in nearly parallel rays. The ancient scholar <b>Eratosthenes</b> compared the angle of the sun’s rays in Syene and Alexandria and, using equal alternate angles at parallel lines, measured the Earth’s circumference.'),
      L('<b>Shaharsozlikda.</b> Parallel ko‘chalarni kesib o‘tuvchi diagonal ko‘cha har bir chorrahada bir xil burchak hosil qiladi — svetofor va belgilarni joylashtirish shu bilimga tayanadi.', '<b>В градостроительстве.</b> Диагональная улица, пересекающая параллельные улицы, образует на каждом перекрёстке один и тот же угол — расстановка светофоров и знаков опирается на это знание.', '<b>In town planning.</b> A diagonal street crossing parallel streets makes the same angle at every junction — placing traffic lights and signs relies on that.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Eratosfen (mil. avv. III asr) Yer aylanasini taxminan 250 000 stadiya deb topgan — zamonaviy hisob-kitoblarga ko‘ra bu haqiqiy qiymatga juda yaqin.', 'Эратосфен (III век до н. э.) получил окружность Земли около 250 000 стадиев — по современным оценкам это очень близко к истинному значению.', 'Eratosthenes (3rd century BC) found the Earth’s circumference to be about 250 000 stadia — by modern estimates very close to the true value.'),
      L('<b>Beruniy</b> Yer radiusini o‘lchashda ham parallel nurlar va burchaklar g‘oyasidan foydalangan; uning natijasi taxminan 6340 km chiqqan, hozirgi qiymat esa 6371 km atrofida.', '<b>Беруни</b> при измерении радиуса Земли тоже опирался на идею углов; его результат — около 6340 км, современное значение — около 6371 км.', '<b>Biruni</b> also relied on angles when measuring the Earth’s radius; his result was about 6 340 km, against a modern value of about 6 371 km.'),
      L('Ko‘z aldanishlarining eng mashhurlaridan biri — Tsollner illyuziyasi: kichik qiya chiziqchalar bilan kesilgan parallel chiziqlar qiyshaygan ko‘rinadi.', 'Одна из самых известных оптических иллюзий — иллюзия Цёлльнера: параллельные прямые, пересечённые короткими косыми штрихами, кажутся непараллельными.', 'One of the best-known optical illusions is the Zöllner illusion: parallel lines crossed by short slanted ticks look as if they are not parallel.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('a ∥ b. Bir tomonli burchaklar nisbati 2 : 7. Ularni toping.', 'a ∥ b. Односторонние углы относятся как 2 : 7. Найдите их.', 'a ∥ b. The co-interior angles are in the ratio 2 : 7. Find them.'),
      L('a ∥ b. Kesuvchi bilan hosil bo‘lgan sakkiz burchakdan ikkitasining yig‘indisi 250°. Barcha burchaklarni toping.', 'a ∥ b. Сумма двух из восьми углов равна 250°. Найдите все углы.', 'a ∥ b. Two of the eight angles add to 250°. Find all the angles.'),
      L('Nima uchun «teng burchaklar vertikal» degan tasdiq noto‘g‘ri? Misol keltiring.', 'Почему утверждение «равные углы вертикальны» неверно? Приведите пример.', 'Why is “equal angles are vertical” false? Give an example.')
    ], after: [
      L('Javoblar: 1) 40° va 140°. 2) 250° ikki o‘tmas teng burchak: 125° va 125°; o‘tkirlari 55°. 3) Masalan, parallel chiziqlardagi mos burchaklar teng, lekin vertikal emas.', 'Ответы: 1) 40° и 140°. 2) 250° — два равных тупых: по 125°; острые — по 55°. 3) Например, соответственные углы при параллельных равны, но не вертикальны.', 'Answers: 1) 40° and 140°. 2) 250° is two equal obtuse angles of 125°; the acute ones are 55°. 3) For example, corresponding angles at parallel lines are equal but not vertical.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Teskari teoremada shart va xulosa o‘rin almashadi; u alohida isbotlanadi.', 'В обратной теореме условие и заключение меняются местами; её доказывают отдельно.', 'A converse swaps hypothesis and conclusion; it is proved separately.'),
      L('a ∥ b bo‘lsa: almashinuvchi burchaklar teng, mos burchaklar teng, bir tomonlilar yig‘indisi 180°.', 'Если a ∥ b: накрест лежащие равны, соответственные равны, сумма односторонних 180°.', 'If a ∥ b: alternate angles are equal, corresponding angles are equal, co-interior angles sum to 180°.'),
      L('Isbotda parallellik aksiomasi ishlatiladi.', 'В доказательстве используется аксиома параллельных.', 'The proof uses the parallel postulate.'),
      L('Sakkiz burchak faqat ikki qiymatga ega: α va 180° − α.', 'У восьми углов только два значения: α и 180° − α.', 'The eight angles take only two values: α and 180° − α.'),
      L('Parallellik berilgan — xossa; isbotlash kerak — alomat.', 'Параллельность дана — свойство; нужно доказать — признак.', 'Parallelism given — property; to be proved — test.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t9. Uchburchak ichki burchaklari yig‘indisi. Tashqi burchak ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Har qanday uchburchakning siri', 'Секрет любого треугольника', 'The secret of every triangle'), p: [
      L('Qog‘ozdan istalgan uchburchak qirqing — kichik yoki katta, cho‘zinchoq yoki teng tomonli. Uning uchta burchagini yirtib oling va uchlarini bir nuqtaga qo‘yib, yonma-yon tering. Har safar bir xil natija chiqadi: burchaklar birgalikda <b>yoyiq burchak</b> — 180° hosil qiladi! Bu tasodif emas, balki geometriyaning eng mashhur teoremalaridan biri.', 'Вырежьте из бумаги любой треугольник — маленький или большой, вытянутый или равносторонний. Оторвите его три угла и приложите их вершинами к одной точке, рядом друг с другом. Каждый раз результат одинаков: вместе углы образуют <b>развёрнутый угол</b> — 180°! Это не случайность, а одна из самых знаменитых теорем геометрии.', 'Cut any triangle out of paper — small or large, long and thin or equilateral. Tear off its three corners and place them side by side with their tips at one point. Every time the result is the same: together they form a <b>straight angle</b> — 180°! This is no accident but one of the most famous theorems in geometry.'),
      L('Lekin qog‘oz tajribasi isbot emas: biz faqat bir nechta uchburchakni tekshirdik, ular esa cheksiz ko‘p. Bu mavzuda teoremani parallel chiziqlar yordamida <b>barcha</b> uchburchaklar uchun bir yo‘la isbotlaymiz va undan muhim natija — tashqi burchak haqidagi teoremani keltirib chiqaramiz.', 'Но бумажный опыт — не доказательство: мы проверили лишь несколько треугольников, а их бесконечно много. В этой теме докажем теорему для <b>всех</b> треугольников сразу с помощью параллельных прямых и выведем из неё важное следствие — теорему о внешнем угле.', 'But a paper experiment is not a proof: we checked only a few triangles, and there are infinitely many. In this topic we prove the theorem for <b>all</b> triangles at once using parallel lines, and derive an important corollary — the exterior angle theorem.')
    ] },
    { kind: 'def', h: L('Ichki va tashqi burchaklar', 'Внутренние и внешние углы', 'Interior and exterior angles'), p: [
      L('Uchburchakning ∠A, ∠B, ∠C burchaklari <b>ichki burchaklar</b> deyiladi. Uchburchakning biror uchidagi ichki burchakka <b>qo‘shni</b> bo‘lgan burchak <b>tashqi burchak</b> deyiladi. Uni hosil qilish uchun bir tomonni uch orqasidan davom ettiramiz: masalan, AC tomonni C dan nariga davom ettirsak, BC tomon va davom ettirilgan chiziq orasida C uchdagi tashqi burchak hosil bo‘ladi.', 'Углы ∠A, ∠B, ∠C треугольника называются <b>внутренними</b>. Угол, <b>смежный</b> с внутренним углом при какой-либо вершине, называется <b>внешним углом</b>. Чтобы его получить, продолжают сторону за вершину: например, продолжив AC за точку C, получим между стороной BC и продолжением внешний угол при вершине C.', 'The angles ∠A, ∠B, ∠C of a triangle are its <b>interior angles</b>. An angle <b>adjacent</b> to the interior angle at a vertex is an <b>exterior angle</b>. To form one, extend a side past a vertex: for example, extending AC beyond C gives the exterior angle at C, between side BC and the extension.'),
      L('Har bir uchda ikkita tashqi burchak bor (ikki tomonning har birini davom ettirish mumkin), lekin ular vertikal va o‘zaro teng. Shuning uchun odatda har uchdan bittasini olamiz. Tashqi burchak ichki burchak bilan qo‘shni bo‘lgani uchun: tashqi + ichki = 180°.', 'В каждой вершине два внешних угла (можно продолжить любую из двух сторон), но они вертикальные и равны. Поэтому обычно берут по одному в каждой вершине. Так как внешний угол смежен с внутренним: внешний + внутренний = 180°.', 'Each vertex has two exterior angles (either side can be extended), but they are vertical and equal. So we usually take one per vertex. Since an exterior angle is adjacent to the interior one: exterior + interior = 180°.')
    ] },
    { kind: 'history', h: L('Pifagorchilardan Lobachevskiygacha', 'От пифагорейцев до Лобачевского', 'From the Pythagoreans to Lobachevsky'), p: [
      L('Qadimgi manbalarga ko‘ra, uchburchak burchaklari yig‘indisi ikki to‘g‘ri burchakka tengligini <b>Pifagor</b> maktabi isbotlagan. Yevklid «Negizlar» birinchi kitobining 32-tasdig‘ida aynan bizning usulimizga yaqin isbot keltiradi: tashqi burchakni parallel chiziq yordamida ikki qismga ajratadi.', 'По древним источникам, то, что сумма углов треугольника равна двум прямым, доказала школа <b>Пифагора</b>. Евклид в предложении 32 первой книги «Начал» приводит доказательство, близкое к нашему: делит внешний угол на две части с помощью параллельной прямой.', 'According to ancient sources, the school of <b>Pythagoras</b> proved that a triangle’s angles add up to two right angles. In Proposition 32 of Book I of the <i>Elements</i>, Euclid gives a proof close to ours: he splits the exterior angle into two parts using a parallel line.'),
      L('Bu teorema parallellik aksiomasiga to‘liq bog‘liq. Lobachevskiy geometriyasida uchburchak burchaklari yig‘indisi doim <b>180° dan kichik</b>, shar sirtidagi geometriyada esa <b>180° dan katta</b>. Masalan, Yer globusida Shimoliy qutb va ekvatordagi ikki nuqtadan tuzilgan uchburchakning uchala burchagi ham 90° bo‘lishi mumkin — yig‘indisi 270°!', 'Эта теорема полностью зависит от аксиомы параллельных. В геометрии Лобачевского сумма углов треугольника всегда <b>меньше 180°</b>, а в геометрии на сфере — <b>больше 180°</b>. Например, на глобусе у треугольника с вершинами на Северном полюсе и в двух точках экватора все три угла могут быть по 90° — сумма 270°!', 'This theorem depends entirely on the parallel postulate. In Lobachevsky’s geometry the angles of a triangle always add to <b>less than 180°</b>, and on a sphere to <b>more than 180°</b>. On a globe, for example, a triangle with vertices at the North Pole and two points on the equator can have three 90° angles — a sum of 270°!'),
      L('Nemis matematigi <b>Karl Gauss</b> fazo haqiqatan ham Yevklidcha ekanini tekshirish uchun uchta tog‘ cho‘qqisi orasidagi ulkan uchburchakni o‘lchagan, degan rivoyat bor. Uning o‘lchovlarida yig‘indi o‘lchash xatoligi doirasida 180° ga teng chiqqan.', 'Есть предание, что немецкий математик <b>Карл Гаусс</b>, проверяя, евклидово ли пространство, измерил огромный треугольник между тремя горными вершинами. В его измерениях сумма в пределах погрешности оказалась равной 180°.', 'There is a story that the German mathematician <b>Carl Gauss</b>, testing whether space is Euclidean, measured a huge triangle between three mountain peaks. Within measurement error, the sum came out as 180°.')
    ] },
    { kind: 'rule', h: L('Teorema va uning isboti', 'Теорема и её доказательство', 'The theorem and its proof'), p: [
      L('<b>Teorema.</b> Uchburchak ichki burchaklari yig‘indisi 180° ga teng: ∠A + ∠B + ∠C = 180°.', '<b>Теорема.</b> Сумма внутренних углов треугольника равна 180°: ∠A + ∠B + ∠C = 180°.', '<b>Theorem.</b> The interior angles of a triangle add up to 180°: ∠A + ∠B + ∠C = 180°.'),
      L('<i>Isbot.</i> △ABC ning B uchi orqali AC ga parallel a to‘g‘ri chiziqni o‘tkazamiz (parallellik aksiomasiga ko‘ra u yagona). B nuqtada a chiziqda uchta burchak hosil bo‘ladi: ∠1, ∠B va ∠2, ular birgalikda yoyiq burchakni tashkil qiladi: ∠1 + ∠B + ∠2 = 180°. ∠1 va ∠A — a ∥ AC va AB kesuvchi uchun ichki almashinuvchi, demak ∠1 = ∠A. Xuddi shunday ∠2 = ∠C (BC kesuvchi). O‘rniga qo‘yamiz: ∠A + ∠B + ∠C = 180°. Isbot tugadi.', '<i>Доказательство.</i> Через вершину B треугольника ABC проведём прямую a, параллельную AC (по аксиоме она единственна). В точке B на прямой a образуются три угла: ∠1, ∠B и ∠2, которые вместе составляют развёрнутый угол: ∠1 + ∠B + ∠2 = 180°. ∠1 и ∠A — накрест лежащие при a ∥ AC и секущей AB, значит ∠1 = ∠A. Аналогично ∠2 = ∠C (секущая BC). Подставляем: ∠A + ∠B + ∠C = 180°. Доказано.', '<i>Proof.</i> Through vertex B of △ABC draw line a parallel to AC (by the postulate it is unique). At B, line a forms three angles ∠1, ∠B and ∠2, which together make a straight angle: ∠1 + ∠B + ∠2 = 180°. ∠1 and ∠A are alternate angles for a ∥ AC with transversal AB, so ∠1 = ∠A. Likewise ∠2 = ∠C (transversal BC). Substituting: ∠A + ∠B + ∠C = 180°. Done.'),
      L('<b>Tashqi burchak haqidagi teorema.</b> Uchburchakning tashqi burchagi unga qo‘shni bo‘lmagan ikki ichki burchak yig‘indisiga teng. <i>Isbot:</i> C dagi tashqi burchak 180° − ∠C. Lekin teoremaga ko‘ra 180° − ∠C = ∠A + ∠B. Demak tashqi burchak = ∠A + ∠B. <b>Natija:</b> tashqi burchak unga qo‘shni bo‘lmagan har bir ichki burchakdan katta.', '<b>Теорема о внешнем угле.</b> Внешний угол треугольника равен сумме двух внутренних, не смежных с ним. <i>Доказательство:</i> внешний угол при C равен 180° − ∠C. Но по теореме 180° − ∠C = ∠A + ∠B. Значит, внешний угол = ∠A + ∠B. <b>Следствие:</b> внешний угол больше каждого внутреннего, не смежного с ним.', '<b>Exterior angle theorem.</b> An exterior angle of a triangle equals the sum of the two interior angles not adjacent to it. <i>Proof:</i> the exterior angle at C is 180° − ∠C. By the theorem, 180° − ∠C = ∠A + ∠B. So the exterior angle = ∠A + ∠B. <b>Corollary:</b> an exterior angle is greater than each interior angle not adjacent to it.')
    ] },
    { kind: 'steps', h: L('Noma’lum burchakni topish', 'Как найти неизвестный угол', 'Finding an unknown angle'), list: [
      L('1-qadam. Ichki burchaklardan ikkitasi ma’lum bo‘lsa: uchinchisi = 180° − (birinchisi + ikkinchisi).', 'Шаг 1. Если известны два внутренних угла: третий = 180° − (первый + второй).', 'Step 1. If two interior angles are known: third = 180° − (first + second).'),
      L('2-qadam. Tashqi burchak va bitta ichki burchak (qo‘shni bo‘lmagan) ma’lum bo‘lsa: ikkinchi qo‘shni bo‘lmagan = tashqi − ma’lumi.', 'Шаг 2. Если известны внешний угол и один внутренний (не смежный): второй не смежный = внешний − известный.', 'Step 2. If an exterior angle and one non-adjacent interior angle are known: the other non-adjacent = exterior − known.'),
      L('3-qadam. Tashqi burchak ma’lum bo‘lsa, unga qo‘shni ichki burchak = 180° − tashqi.', 'Шаг 3. Если известен внешний угол, смежный с ним внутренний = 180° − внешний.', 'Step 3. If an exterior angle is known, the interior angle adjacent to it = 180° − exterior.'),
      L('4-qadam. Burchaklar nisbat yoki ayirma bilan berilsa, x orqali tenglama tuzing va yig‘indini 180° ga tenglang.', 'Шаг 4. Если углы заданы отношением или разностью, составьте уравнение через x и приравняйте сумму к 180°.', 'Step 4. If the angles are given by a ratio or difference, write an equation in x with the sum equal to 180°.'),
      L('5-qadam. Javobni tekshiring: hamma burchaklar musbat va yig‘indisi 180°.', 'Шаг 5. Проверьте ответ: все углы положительны, их сумма 180°.', 'Step 5. Check: all angles are positive and they add to 180°.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('△ABC da ∠A = 48°, ∠B = 77°. ∠C ni toping.', 'В △ABC ∠A = 48°, ∠B = 77°. Найдите ∠C.', 'In △ABC, ∠A = 48° and ∠B = 77°. Find ∠C.'), s: L('∠C = 180° − (48° + 77°) = 180° − 125° = <b>55°</b>.', '∠C = 180° − (48° + 77°) = 180° − 125° = <b>55°</b>.', '∠C = 180° − (48° + 77°) = 180° − 125° = <b>55°</b>.') },
      { q: L('Uchburchak burchaklari 2 : 3 : 4 nisbatda. Ularni toping.', 'Углы треугольника относятся как 2 : 3 : 4. Найдите их.', 'The angles of a triangle are in the ratio 2 : 3 : 4. Find them.'), s: L('2x + 3x + 4x = 180, 9x = 180, x = 20. Burchaklar: <b>40°, 60°, 80°</b>.', '2x + 3x + 4x = 180, 9x = 180, x = 20. Углы: <b>40°, 60°, 80°</b>.', '2x + 3x + 4x = 180, 9x = 180, x = 20. Angles: <b>40°, 60°, 80°</b>.') },
      { q: L('Uchburchakning C uchidagi tashqi burchagi 128°, ∠A = 56°. ∠B va ∠C ni toping.', 'Внешний угол при вершине C равен 128°, ∠A = 56°. Найдите ∠B и ∠C.', 'The exterior angle at C is 128° and ∠A = 56°. Find ∠B and ∠C.'), s: L('Tashqi burchak teoremasi: 128° = ∠A + ∠B, ∠B = 128° − 56° = <b>72°</b>. ∠C = 180° − 128° = <b>52°</b>. Tekshiruv: 56 + 72 + 52 = 180.', 'По теореме о внешнем угле: 128° = ∠A + ∠B, ∠B = 128° − 56° = <b>72°</b>. ∠C = 180° − 128° = <b>52°</b>. Проверка: 56 + 72 + 52 = 180.', 'Exterior angle theorem: 128° = ∠A + ∠B, so ∠B = 128° − 56° = <b>72°</b>. ∠C = 180° − 128° = <b>52°</b>. Check: 56 + 72 + 52 = 180.') },
      { q: L('Uchburchakning har bir uchidan bittadan olingan uchta tashqi burchak yig‘indisini toping.', 'Найдите сумму трёх внешних углов треугольника, взятых по одному при каждой вершине.', 'Find the sum of the three exterior angles of a triangle, one at each vertex.'), s: L('Har bir tashqi = 180° − ichki. Yig‘indi: 3 · 180° − (∠A + ∠B + ∠C) = 540° − 180° = <b>360°</b>. Bu har qanday uchburchak uchun to‘g‘ri!', 'Каждый внешний = 180° − внутренний. Сумма: 3 · 180° − (∠A + ∠B + ∠C) = 540° − 180° = <b>360°</b>. Это верно для любого треугольника!', 'Each exterior = 180° − interior. Sum: 3 · 180° − (∠A + ∠B + ∠C) = 540° − 180° = <b>360°</b>. True for every triangle!') }
    ] },
    { kind: 'table', h: L('Teoremadan kelib chiqadigan natijalar', 'Следствия теоремы', 'Consequences of the theorem'), table: { head: [L('Uchburchak', 'Треугольник', 'Triangle'), L('Burchaklar haqida', 'Об углах', 'About its angles')], rows: [
      [L('ixtiyoriy', 'любой', 'any'), L('kamida ikkita burchagi o‘tkir', 'хотя бы два угла острые', 'at least two angles are acute')],
      [L('to‘g‘ri burchakli', 'прямоугольный', 'right'), L('o‘tkir burchaklar yig‘indisi 90°', 'сумма острых углов 90°', 'the acute angles sum to 90°')],
      [L('teng tomonli', 'равносторонний', 'equilateral'), L('har bir burchak 60°', 'каждый угол 60°', 'each angle is 60°')],
      [L('teng yonli, uchidagi β', 'равнобедренный, при вершине β', 'isosceles, apex β'), L('asosdagi (180° − β) : 2', 'при основании (180° − β) : 2', 'base angles (180° − β) : 2')],
      [L('tashqi burchaklar', 'внешние углы', 'exterior angles'), L('yig‘indisi 360°', 'сумма 360°', 'sum to 360°')]
    ] }, after: [
      L('Birinchi qator nega to‘g‘ri? Agar ikkita burchak o‘tkir bo‘lmasa (har biri ≥ 90°), ularning o‘zi 180° ni egallaydi — uchinchi burchakka joy qolmaydi.', 'Почему верна первая строка? Если бы два угла не были острыми (каждый ≥ 90°), они бы уже заняли 180° — для третьего угла места не осталось бы.', 'Why is the first row true? If two angles were not acute (each ≥ 90°), they alone would take 180°, leaving no room for the third.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Tashqi burchakni qo‘shni ichki burchak bilan qo‘shish.</b> Tashqi = qo‘shni <i>bo‘lmagan</i> ikki burchak yig‘indisi.', '<b>Складывать внешний угол со смежным внутренним.</b> Внешний = сумма двух <i>несмежных</i> с ним углов.', '<b>Adding the exterior angle to the adjacent interior one.</b> Exterior = the sum of the two <i>non-adjacent</i> angles.'),
      L('<b>Uchta tashqi burchak yig‘indisini 180° deb o‘ylash.</b> U 360° ga teng.', '<b>Думать, что сумма трёх внешних углов 180°.</b> Она равна 360°.', '<b>Thinking the three exterior angles sum to 180°.</b> They sum to 360°.'),
      L('<b>Qog‘oz tajribasini isbot deb hisoblash.</b> O‘lchash taxminiy va faqat ayrim uchburchaklar uchun; isbot esa hammasi uchun.', '<b>Считать бумажный опыт доказательством.</b> Измерение приближённо и только для отдельных треугольников, а доказательство — для всех.', '<b>Treating the paper experiment as a proof.</b> Measuring is approximate and covers only some triangles; a proof covers all.'),
      L('<b>Imkonsiz uchburchakni qabul qilish.</b> Burchaklari 100° va 90° bo‘lgan uchburchak yo‘q — yig‘indi allaqachon 190°.', '<b>Принимать невозможный треугольник.</b> Треугольника с углами 100° и 90° нет — сумма уже 190°.', '<b>Accepting an impossible triangle.</b> No triangle has angles of 100° and 90° — that is already 190°.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Tom va ko‘priklarda.</b> Muhandis tom fermasining ikki burchagini loyihalaganda uchinchisi o‘z-o‘zidan ma’lum. Masalan, tom nishabi 30° bo‘lsa, cho‘qqidagi burchak 180° − 2 · 30° = 120°.', '<b>В крышах и мостах.</b> Когда инженер проектирует два угла фермы крыши, третий известен сам собой. Например, при уклоне крыши 30° угол в коньке 180° − 2 · 30° = 120°.', '<b>In roofs and bridges.</b> When an engineer designs two angles of a roof truss, the third is automatic. With a 30° roof pitch, the ridge angle is 180° − 2 · 30° = 120°.'),
      L('<b>Navigatsiyada.</b> Kema ikki mayoqqa qarab yo‘nalish burchaklarini o‘lchaydi; uchinchi burchak yig‘indi teoremasidan topiladi va kemaning o‘rni aniqlanadi.', '<b>В навигации.</b> Корабль измеряет углы направлений на два маяка; третий угол находится по теореме о сумме, и определяется положение корабля.', '<b>In navigation.</b> A ship measures the bearings to two lighthouses; the third angle comes from the angle-sum theorem, fixing the ship’s position.'),
      L('<b>Astronomiyada.</b> Samarqanddagi Ulug‘bek rasadxonasida yulduzlar orasidagi burchak masofalar o‘lchanib, ulardan uchburchaklar hisoblangan. Bugun ham astronomlar Yerning orbitadagi ikki holatidan yaqin yulduzgacha bo‘lgan masofani uchburchak orqali topadi (parallaks usuli).', '<b>В астрономии.</b> В обсерватории Улугбека в Самарканде измеряли угловые расстояния между звёздами и по ним рассчитывали треугольники. И сегодня астрономы находят расстояние до близких звёзд через треугольник, вершины которого — два положения Земли на орбите (метод параллакса).', '<b>In astronomy.</b> At Ulugh Beg’s observatory in Samarkand, the angular distances between stars were measured and triangles computed from them. Today astronomers still find the distance to nearby stars through a triangle whose vertices include two positions of the Earth in its orbit (the parallax method).')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Ko‘pburchak ichki burchaklari yig‘indisi (n − 2) · 180°: to‘rtburchakda 360°, beshburchakda 540°. Sababi — ko‘pburchakni bir uchidan n − 2 ta uchburchakka bo‘lish mumkin.', 'Сумма углов многоугольника (n − 2) · 180°: у четырёхугольника 360°, у пятиугольника 540°. Причина — многоугольник можно разрезать из одной вершины на n − 2 треугольника.', 'The angles of a polygon sum to (n − 2) · 180°: 360° for a quadrilateral, 540° for a pentagon. Reason: from one vertex a polygon splits into n − 2 triangles.'),
      L('Qavariq ko‘pburchakning tashqi burchaklari yig‘indisi har doim 360° — tomonlari qancha bo‘lishidan qat’i nazar. Ko‘pburchak atrofida aylanib yursangiz, oxirida aynan bir to‘liq burilish qilasiz.', 'Сумма внешних углов выпуклого многоугольника всегда 360° — независимо от числа сторон. Обойдя многоугольник по периметру, вы в итоге сделаете ровно один полный поворот.', 'The exterior angles of a convex polygon always sum to 360° — however many sides it has. Walk around it and you make exactly one full turn.'),
      L('Yer sirtidagi juda katta uchburchaklarda burchaklar yig‘indisi 180° dan biroz oshadi — Yer sharsimon bo‘lgani uchun. Geodezistlar katta masofalarni o‘lchashda bu tuzatmani hisobga oladi.', 'В очень больших треугольниках на поверхности Земли сумма углов чуть больше 180° — потому что Земля круглая. Геодезисты учитывают эту поправку при больших измерениях.', 'In very large triangles on the Earth’s surface the angles add to slightly more than 180° — because the Earth is round. Surveyors include this correction in large-scale measurements.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Uchburchakning bir burchagi ikkinchisidan 20° katta, uchinchisidan 20° kichik. Burchaklarni toping.', 'Один угол треугольника на 20° больше второго и на 20° меньше третьего. Найдите углы.', 'One angle of a triangle is 20° more than the second and 20° less than the third. Find the angles.'),
      L('Uchburchakda ikkita tashqi burchak 100° va 150°. Uchinchi tashqi burchakni toping.', 'Два внешних угла треугольника 100° и 150°. Найдите третий внешний угол.', 'Two exterior angles of a triangle are 100° and 150°. Find the third.'),
      L('Ikkita o‘tmas burchakli uchburchak bo‘lishi mumkinmi? Nega?', 'Может ли треугольник иметь два тупых угла? Почему?', 'Can a triangle have two obtuse angles? Why?')
    ], after: [
      L('Javoblar: 1) x − 20, x, x + 20; 3x = 180, x = 60: 40°, 60°, 80°. 2) 360° − 250° = 110°. 3) Yo‘q: ikkita o‘tmas burchak yig‘indisi 180° dan katta.', 'Ответы: 1) x − 20, x, x + 20; 3x = 180, x = 60: 40°, 60°, 80°. 2) 360° − 250° = 110°. 3) Нет: сумма двух тупых больше 180°.', 'Answers: 1) x − 20, x, x + 20; 3x = 180, x = 60: 40°, 60°, 80°. 2) 360° − 250° = 110°. 3) No: two obtuse angles exceed 180°.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('∠A + ∠B + ∠C = 180° — har qanday uchburchak uchun.', '∠A + ∠B + ∠C = 180° — для любого треугольника.', '∠A + ∠B + ∠C = 180° — for every triangle.'),
      L('Isbot: uchdan qarshi tomonga parallel chiziq, almashinuvchi burchaklar va yoyiq burchak.', 'Доказательство: прямая через вершину параллельно противоположной стороне, накрест лежащие углы и развёрнутый угол.', 'Proof: a line through a vertex parallel to the opposite side, alternate angles and a straight angle.'),
      L('Tashqi burchak = unga qo‘shni bo‘lmagan ikki ichki burchak yig‘indisi.', 'Внешний угол = сумма двух внутренних, не смежных с ним.', 'Exterior angle = sum of the two non-adjacent interior angles.'),
      L('Tashqi burchaklar yig‘indisi (har uchdan bittadan) 360°.', 'Сумма внешних углов (по одному при каждой вершине) 360°.', 'The exterior angles (one per vertex) sum to 360°.'),
      L('Uchburchakda ko‘pi bilan bitta to‘g‘ri yoki o‘tmas burchak bor.', 'В треугольнике не более одного прямого или тупого угла.', 'A triangle has at most one right or obtuse angle.'),
      L('Teorema parallellik aksiomasiga tayanadi; boshqa geometriyalarda yig‘indi boshqacha.', 'Теорема опирается на аксиому параллельных; в других геометриях сумма иная.', 'The theorem rests on the parallel postulate; in other geometries the sum differs.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t10. To‘g‘ri burchakli uchburchaklar. Bissektrisa xossasi ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Geometriyaning «yulduzi»', '«Звезда» геометрии', 'The star of geometry'), p: [
      L('Narvonni devorga suyang: devor, pol va narvon to‘g‘ri burchakli uchburchak hosil qiladi. Ekran diagonali, tom nishabi, qiyalik bo‘ylab yurgan mashina yo‘li — hammasida to‘g‘ri burchakli uchburchak yashiringan. Bu uchburchakning o‘ziga xos xossalari shunchalik ko‘pki, keyingi sinflarda butun bir bo‘lim — trigonometriya — unga bag‘ishlanadi.', 'Прислоните лестницу к стене: стена, пол и лестница образуют прямоугольный треугольник. Диагональ экрана, скат крыши, путь машины по склону — везде спрятан прямоугольный треугольник. У него столько особых свойств, что в старших классах ему посвящён целый раздел — тригонометрия.', 'Lean a ladder against a wall: the wall, the floor and the ladder form a right triangle. A screen’s diagonal, a roof slope, a car’s path up a hill — a right triangle hides in each. It has so many special properties that a whole subject in later grades — trigonometry — is devoted to it.'),
      L('Bu mavzuda to‘g‘ri burchakli uchburchakning asosiy xossalarini, uning tengligi alomatlarini va mashhur «30° li burchak qarshisidagi katet» xossasini o‘rganamiz. Oxirida burchak bissektrisasining ajoyib xossasini isbotlaymiz: undagi har bir nuqta burchak tomonlaridan bir xil uzoqlikda yotadi.', 'В этой теме изучим основные свойства прямоугольного треугольника, признаки его равенства и знаменитое свойство «катета против угла 30°». В конце докажем замечательное свойство биссектрисы угла: каждая её точка равноудалена от сторон угла.', 'In this topic we study the main properties of right triangles, their congruence tests and the famous “leg opposite 30°” property. Finally we prove a remarkable property of an angle bisector: every point on it is the same distance from both sides of the angle.')
    ] },
    { kind: 'def', h: L('Katet va gipotenuza', 'Катеты и гипотенуза', 'Legs and hypotenuse'), p: [
      L('<b>To‘g‘ri burchakli uchburchak</b> — bir burchagi 90° bo‘lgan uchburchak. To‘g‘ri burchakka yopishgan ikki tomon — <b>katetlar</b>, to‘g‘ri burchak qarshisidagi tomon — <b>gipotenuza</b>. Odatda to‘g‘ri burchak C uchda bo‘ladi: a = BC va b = AC — katetlar, c = AB — gipotenuza.', '<b>Прямоугольный треугольник</b> — треугольник с углом 90°. Две стороны, образующие прямой угол, — <b>катеты</b>, сторона против прямого угла — <b>гипотенуза</b>. Обычно прямой угол при вершине C: a = BC и b = AC — катеты, c = AB — гипотенуза.', 'A <b>right triangle</b> has one 90° angle. The two sides forming the right angle are the <b>legs</b>; the side opposite the right angle is the <b>hypotenuse</b>. Usually the right angle is at C: a = BC and b = AC are the legs, c = AB is the hypotenuse.'),
      L('«Gipotenuza» so‘zi yunoncha «tortilgan» degan ma’noni beradi — qadimda arfaning qiya tortilgan tori nazarda tutilgan. «Katet» esa «shoqul», ya’ni tik tushgan chiziq degani.', 'Слово «гипотенуза» по-гречески значит «натянутая» — имелась в виду косо натянутая струна арфы. А «катет» означает «отвес», то есть отвесную линию.', 'The word “hypotenuse” comes from the Greek for “stretched under” — originally a string stretched across a harp. “Cathetus” (leg) means “plumb line”, a vertical line.')
    ], list: [
      L('O‘tkir burchaklar yig‘indisi 90°: ∠A + ∠B = 90° (chunki 180° − 90° = 90°).', 'Сумма острых углов 90°: ∠A + ∠B = 90° (так как 180° − 90° = 90°).', 'The acute angles sum to 90°: ∠A + ∠B = 90° (since 180° − 90° = 90°).'),
      L('Gipotenuza har qanday katetdan uzun (katta burchak qarshisida katta tomon yotadi — 11-mavzu).', 'Гипотенуза длиннее любого катета (против большего угла лежит большая сторона — тема 11).', 'The hypotenuse is longer than either leg (the larger angle faces the larger side — topic 11).'),
      L('Katetlar bir vaqtda uchburchak balandliklari ham bo‘ladi.', 'Катеты одновременно являются высотами треугольника.', 'The legs are also altitudes of the triangle.')
    ] },
    { kind: 'history', h: L('Pifagor, Misr arqoni va hind olimlari', 'Пифагор, египетская верёвка и индийские учёные', 'Pythagoras, the Egyptian rope and Indian scholars'), p: [
      L('To‘g‘ri burchakli uchburchaklar haqidagi eng mashhur teorema <b>Pifagor</b> nomi bilan bog‘liq: katetlar kvadratlari yig‘indisi gipotenuza kvadratiga teng. Ammo bu bog‘lanishni undan ancha oldin Bobil olimlari bilishgan — miloddan avvalgi XVIII asrga oid «Plimpton 322» loy taxtachasida shunday uchburchaklar tomonlari ro‘yxati bor. Hind olimlari ham «Sulba-sutra» kitoblarida qurbongoh qurish uchun shu qoidadan foydalanishgan.', 'Самая известная теорема о прямоугольных треугольниках связана с именем <b>Пифагора</b>: сумма квадратов катетов равна квадрату гипотенузы. Но эту связь задолго до него знали вавилонские учёные — на глиняной табличке «Плимптон 322» (около XVIII века до н. э.) есть список сторон таких треугольников. Индийские учёные в книгах «Шульба-сутры» тоже пользовались этим правилом при строительстве алтарей.', 'The most famous theorem about right triangles bears the name of <b>Pythagoras</b>: the squares of the legs add up to the square of the hypotenuse. But Babylonian scholars knew this relationship long before him — the clay tablet “Plimpton 322” (around the 18th century BC) lists sides of such triangles. Indian scholars also used the rule in the <i>Sulba Sutras</i> for building altars.'),
      L('Pifagor teoremasini 8-sinfda o‘rganasiz. Hozir esa undan oddiyroq, ammo juda foydali xossa bilan tanishamiz — u ham qadimgi yunonlarga ma’lum bo‘lgan: 30° li burchak qarshisidagi katet gipotenuzaning yarmiga teng. <b>Beruniy</b> o‘zining astronomik hisob-kitoblarida to‘g‘ri burchakli uchburchaklardan doimiy ravishda foydalangan.', 'Теорему Пифагора вы изучите в 8 классе. А сейчас познакомимся с более простым, но очень полезным свойством — оно тоже было известно древним грекам: катет против угла 30° равен половине гипотенузы. <b>Беруни</b> в своих астрономических расчётах постоянно пользовался прямоугольными треугольниками.', 'You will study the Pythagorean theorem in grade 8. For now we meet a simpler but very useful property, also known to the ancient Greeks: the leg opposite a 30° angle is half the hypotenuse. <b>Biruni</b> used right triangles constantly in his astronomical calculations.')
    ] },
    { kind: 'rule', h: L('Asosiy xossalar va isbotlar', 'Основные свойства и доказательства', 'Key properties and proofs'), p: [
      L('<b>1-xossa.</b> 30° li burchak qarshisidagi katet gipotenuzaning yarmiga teng. <i>Isbot:</i> △ABC da ∠C = 90°, ∠A = 30°, demak ∠B = 60°. B nuqtani AC to‘g‘ri chiziqqa nisbatan B′ nuqtaga aks ettiramiz (CB′ = CB). △ABC = △AB′C (TBT: AC umumiy, CB = CB′, C dagi burchaklar 90° dan). △ABB′ da ∠ABB′ = ∠AB′B = 60° va ∠BAB′ = 2 · 30° = 60°. Uchala burchak 60° — uchburchak teng tomonli, demak BB′ = AB. Lekin BB′ = 2 · BC. Demak <b>BC = AB : 2</b>.', '<b>Свойство 1.</b> Катет против угла 30° равен половине гипотенузы. <i>Доказательство:</i> в △ABC ∠C = 90°, ∠A = 30°, значит ∠B = 60°. Отразим точку B относительно прямой AC в точку B′ (CB′ = CB). △ABC = △AB′C (СУС: AC общая, CB = CB′, углы при C по 90°). В △ABB′: ∠ABB′ = ∠AB′B = 60° и ∠BAB′ = 2 · 30° = 60°. Все три угла по 60° — треугольник равносторонний: BB′ = AB. Но BB′ = 2 · BC. Значит, <b>BC = AB : 2</b>.', '<b>Property 1.</b> The leg opposite a 30° angle is half the hypotenuse. <i>Proof:</i> in △ABC, ∠C = 90° and ∠A = 30°, so ∠B = 60°. Reflect B in line AC to B′ (CB′ = CB). △ABC ≅ △AB′C (SAS: AC common, CB = CB′, both angles at C are 90°). In △ABB′: ∠ABB′ = ∠AB′B = 60° and ∠BAB′ = 2 · 30° = 60°. All three angles are 60°, so the triangle is equilateral: BB′ = AB. But BB′ = 2 · BC. Therefore <b>BC = AB : 2</b>.'),
      L('<b>Teskari xossa:</b> agar katet gipotenuzaning yarmiga teng bo‘lsa, uning qarshisidagi burchak 30°.', '<b>Обратное свойство:</b> если катет равен половине гипотенузы, то угол против него 30°.', '<b>Converse:</b> if a leg is half the hypotenuse, the angle opposite it is 30°.'),
      L('<b>To‘g‘ri burchakli uchburchaklar tengligi alomatlari:</b> 1) ikki kateti bo‘yicha (TBT); 2) katet va unga yopishgan o‘tkir burchak bo‘yicha (BTB); 3) gipotenuza va o‘tkir burchak bo‘yicha; 4) gipotenuza va katet bo‘yicha. To‘g‘ri burchak doim teng bo‘lgani uchun faqat ikki element kifoya!', '<b>Признаки равенства прямоугольных треугольников:</b> 1) по двум катетам (СУС); 2) по катету и прилежащему острому углу (УСУ); 3) по гипотенузе и острому углу; 4) по гипотенузе и катету. Прямые углы всегда равны, поэтому хватает двух элементов!', '<b>Congruence tests for right triangles:</b> 1) two legs (SAS); 2) a leg and the adjacent acute angle (ASA); 3) the hypotenuse and an acute angle; 4) the hypotenuse and a leg. Since the right angles are always equal, two parts are enough!'),
      L('<b>Bissektrisa xossasi.</b> Burchak bissektrisasidagi har bir nuqta burchak tomonlaridan teng uzoqlikda yotadi. <i>Isbot:</i> M nuqta ∠O bissektrisasida; MA va MB — tomonlarga perpendikulyarlar. △OAM va △OBM to‘g‘ri burchakli, OM — umumiy gipotenuza, ∠AOM = ∠BOM. Gipotenuza va o‘tkir burchak bo‘yicha ular teng, demak <b>MA = MB</b>. Teskarisi ham to‘g‘ri: tomonlardan teng uzoqlikdagi nuqta bissektrisada yotadi.', '<b>Свойство биссектрисы.</b> Каждая точка биссектрисы угла равноудалена от его сторон. <i>Доказательство:</i> точка M на биссектрисе ∠O; MA и MB — перпендикуляры к сторонам. △OAM и △OBM прямоугольные, OM — общая гипотенуза, ∠AOM = ∠BOM. По гипотенузе и острому углу они равны, значит <b>MA = MB</b>. Верно и обратное: точка, равноудалённая от сторон угла, лежит на биссектрисе.', '<b>Bisector property.</b> Every point on an angle bisector is equidistant from the sides of the angle. <i>Proof:</i> M is on the bisector of ∠O; MA and MB are perpendiculars to the sides. △OAM and △OBM are right triangles with common hypotenuse OM and ∠AOM = ∠BOM. By hypotenuse and acute angle they are congruent, so <b>MA = MB</b>. The converse holds too: a point equidistant from the sides lies on the bisector.')
    ] },
    { kind: 'steps', h: L('To‘g‘ri burchakli uchburchakda masala yechish', 'Решение задач в прямоугольном треугольнике', 'Solving right-triangle problems'), list: [
      L('1-qadam. To‘g‘ri burchakni toping va kvadratcha bilan belgilang. Gipotenuza — uning qarshisidagi tomon.', 'Шаг 1. Найдите прямой угол и отметьте квадратиком. Гипотенуза — сторона напротив него.', 'Step 1. Find the right angle and mark it with a square. The hypotenuse is the side opposite it.'),
      L('2-qadam. Bitta o‘tkir burchak ma’lum bo‘lsa, ikkinchisi = 90° − birinchisi.', 'Шаг 2. Если известен один острый угол, второй = 90° − первый.', 'Step 2. If one acute angle is known, the other = 90° − the first.'),
      L('3-qadam. 30° li burchak bormi? Uning qarshisidagi katet = gipotenuza : 2. 60° li burchak bo‘lsa, unga yopishgan katet ham gipotenuzaning yarmi.', 'Шаг 3. Есть угол 30°? Катет против него = гипотенуза : 2. Если есть угол 60°, прилежащий к нему катет тоже половина гипотенузы.', 'Step 3. Is there a 30° angle? The leg opposite it = hypotenuse : 2. If there is a 60° angle, the leg adjacent to it is also half the hypotenuse.'),
      L('4-qadam. Tenglikni isbotlash kerak bo‘lsa — to‘g‘ri burchakli uchburchaklar alomatlaridan birini tanlang (ikki element yetarli).', 'Шаг 4. Если нужно доказать равенство — выберите признак для прямоугольных треугольников (достаточно двух элементов).', 'Step 4. To prove congruence, choose a right-triangle test (two parts are enough).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('To‘g‘ri burchakli uchburchakning bir o‘tkir burchagi 37°. Ikkinchisini toping.', 'Один острый угол прямоугольного треугольника 37°. Найдите второй.', 'One acute angle of a right triangle is 37°. Find the other.'), s: L('O‘tkir burchaklar yig‘indisi 90°: 90° − 37° = <b>53°</b>.', 'Сумма острых углов 90°: 90° − 37° = <b>53°</b>.', 'The acute angles sum to 90°: 90° − 37° = <b>53°</b>.') },
      { q: L('△ABC da ∠C = 90°, ∠B = 60°, AB = 18 cm. BC ni toping.', 'В △ABC ∠C = 90°, ∠B = 60°, AB = 18 см. Найдите BC.', 'In △ABC, ∠C = 90°, ∠B = 60°, AB = 18 cm. Find BC.'), s: L('∠A = 90° − 60° = 30°. BC katet ∠A ning qarshisida, demak BC = AB : 2 = <b>9 cm</b>.', '∠A = 90° − 60° = 30°. Катет BC лежит против ∠A, значит BC = AB : 2 = <b>9 см</b>.', '∠A = 90° − 60° = 30°. Leg BC is opposite ∠A, so BC = AB : 2 = <b>9 cm</b>.') },
      { q: L('To‘g‘ri burchakli uchburchakda gipotenuza va kichik katet yig‘indisi 27 cm, o‘tkir burchaklardan biri 60°. Gipotenuzani toping.', 'В прямоугольном треугольнике сумма гипотенузы и меньшего катета 27 см, один острый угол 60°. Найдите гипотенузу.', 'In a right triangle the hypotenuse plus the shorter leg is 27 cm, and one acute angle is 60°. Find the hypotenuse.'), s: L('Ikkinchi o‘tkir burchak 30°, uning qarshisida kichik katet = c : 2. c + c : 2 = 27, 1,5c = 27, c = <b>18 cm</b> (kichik katet 9 cm).', 'Второй острый угол 30°, против него меньший катет = c : 2. c + c : 2 = 27, 1,5c = 27, c = <b>18 см</b> (меньший катет 9 см).', 'The other acute angle is 30°; the shorter leg opposite it is c : 2. c + c : 2 = 27, 1.5c = 27, c = <b>18 cm</b> (shorter leg 9 cm).') },
      { q: L('M nuqta ∠AOB bissektrisasida, M dan OA gacha masofa 5 cm. M dan OB gacha masofa qancha?', 'Точка M на биссектрисе ∠AOB, расстояние от M до OA равно 5 см. Чему равно расстояние от M до OB?', 'Point M is on the bisector of ∠AOB and its distance to OA is 5 cm. What is its distance to OB?'), s: L('Bissektrisa nuqtalari tomonlardan teng uzoqlikda: <b>5 cm</b>.', 'Точки биссектрисы равноудалены от сторон: <b>5 см</b>.', 'Points on the bisector are equidistant from the sides: <b>5 cm</b>.') }
    ] },
    { kind: 'table', h: L('To‘g‘ri burchakli uchburchaklar tengligi', 'Равенство прямоугольных треугольников', 'Congruence of right triangles'), table: { head: [L('Alomat', 'Признак', 'Test'), L('Nima teng', 'Что равно', 'What is equal'), L('Qaysi umumiy alomatdan', 'Из какого общего признака', 'Comes from')], rows: [
      [L('ikki katet', 'два катета', 'two legs'), L('a = a₁, b = b₁', 'a = a₁, b = b₁', 'a = a₁, b = b₁'), L('TBT', 'СУС', 'SAS')],
      [L('katet va o‘tkir burchak', 'катет и острый угол', 'leg and acute angle'), L('a = a₁, ∠B = ∠B₁', 'a = a₁, ∠B = ∠B₁', 'a = a₁, ∠B = ∠B₁'), L('BTB', 'УСУ', 'ASA')],
      [L('gipotenuza va o‘tkir burchak', 'гипотенуза и острый угол', 'hypotenuse and acute angle'), L('c = c₁, ∠A = ∠A₁', 'c = c₁, ∠A = ∠A₁', 'c = c₁, ∠A = ∠A₁'), L('BTB (uchinchi burchak ham teng)', 'УСУ (третий угол тоже равен)', 'ASA (third angle equal too)')],
      [L('gipotenuza va katet', 'гипотенуза и катет', 'hypotenuse and leg'), L('c = c₁, a = a₁', 'c = c₁, a = a₁', 'c = c₁, a = a₁'), L('alohida isbotlanadi', 'доказывается отдельно', 'proved separately')]
    ] } },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Gipotenuzani adashtirish.</b> Gipotenuza — doim to‘g‘ri burchak qarshisidagi, eng uzun tomon. Chizmada «pastda» turgan tomon emas.', '<b>Путать гипотенузу.</b> Гипотенуза — всегда сторона против прямого угла, самая длинная. Не «нижняя» сторона на чертеже.', '<b>Misidentifying the hypotenuse.</b> It is always the side opposite the right angle, the longest side — not the “bottom” side in the drawing.'),
      L('<b>30° qoidasini noto‘g‘ri katetga qo‘llash.</b> Gipotenuzaning yarmi — faqat 30° <i>qarshisidagi</i> katet. 30° ga yopishgan katet boshqacha.', '<b>Применять правило 30° к «не тому» катету.</b> Половина гипотенузы — только катет <i>против</i> 30°. Прилежащий к 30° катет — другой.', '<b>Applying the 30° rule to the wrong leg.</b> Half the hypotenuse is only the leg <i>opposite</i> 30°. The leg next to 30° is different.'),
      L('<b>Masofani og‘ma bo‘ylab o‘lchash.</b> Bissektrisa nuqtasidan tomongacha masofa — perpendikulyar, istalgan kesma emas.', '<b>Мерить расстояние по наклонной.</b> Расстояние от точки биссектрисы до стороны — перпендикуляр, а не любой отрезок.', '<b>Measuring along an oblique.</b> The distance from a bisector point to a side is the perpendicular, not any segment.'),
      L('<b>Gipotenuza va katet yig‘indisida qaysi katetligini aniqlamaslik.</b> 30° qarshisidagi — kichik katet.', '<b>Не уточнять, какой катет.</b> Против 30° лежит меньший катет.', '<b>Not saying which leg.</b> The leg opposite 30° is the shorter one.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Qiyalikda.</b> Pandus (nogironlar aravachasi uchun qiyalik) 30° nishab bilan qurilsa, 4 metrlik pandus 2 metr balandlikka ko‘taradi. Lekin bu juda tik! Qoidalarga ko‘ra pandus ancha yotiq — taxminan 5° atrofida bo‘ladi.', '<b>На склоне.</b> Если пандус построить с уклоном 30°, пандус длиной 4 м поднимет на 2 м. Но это слишком круто! По нормам пандус гораздо положе — около 5°.', '<b>On a slope.</b> A ramp at 30° that is 4 m long rises 2 m. But that is far too steep! Building codes require ramps to be much gentler — around 5°.'),
      L('<b>Uchishda.</b> Samolyot 30° burchak ostida ko‘tarilsa, har 1000 m yo‘lda 500 m balandlikka chiqadi. Uchuvchilar bunday hisobni tezda bajarishadi.', '<b>В полёте.</b> Если самолёт набирает высоту под углом 30°, на каждые 1000 м пути он поднимается на 500 м. Пилоты делают такой расчёт мгновенно.', '<b>In flight.</b> A plane climbing at 30° gains 500 m of height for every 1 000 m flown. Pilots make such estimates quickly.'),
      L('<b>Futbolda.</b> Darvozabon to‘pni kutayotganda, u burchak bissektrisasida turishga harakat qiladi — shunda ikkala darvoza ustunigacha masofa bir xil bo‘ladi va har ikki tomonga bir xil tez yetadi.', '<b>В футболе.</b> Вратарь старается стоять на биссектрисе угла обстрела — тогда до обеих штанг одинаково далеко, и он одинаково быстро успевает в обе стороны.', '<b>In football.</b> A goalkeeper tries to stand on the bisector of the shooting angle — then both posts are equally far, and he can reach either side equally fast.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Uchburchak bissektrisalari kesishgan nuqta uchala tomondan teng uzoqlikda yotadi — shuning uchun undan uchala tomonga tegadigan aylana chizish mumkin (ichki chizilgan aylana).', 'Точка пересечения биссектрис треугольника равноудалена от всех трёх сторон — поэтому из неё можно провести окружность, касающуюся всех сторон (вписанную окружность).', 'The point where a triangle’s bisectors meet is equidistant from all three sides — so a circle touching all three sides can be drawn from it (the incircle).'),
      L('Chizmachilar ishlatadigan uchburchak go‘nyolar odatda ikki xil: 45°–45°–90° va 30°–60°–90°. Ikkinchisida qisqa katet gipotenuzaning aynan yarmi.', 'Чертёжные угольники обычно бывают двух видов: 45°–45°–90° и 30°–60°–90°. У второго короткий катет ровно половина гипотенузы.', 'Drawing set squares usually come in two kinds: 45°–45°–90° and 30°–60°–90°. In the second, the short leg is exactly half the hypotenuse.'),
      L('Qadimgi Bobil taxtachasi «Plimpton 322» ga 3800 yilga yaqin — u matematika tarixidagi eng qadimgi «jadval»lardan biri.', 'Вавилонской табличке «Плимптон 322» около 3800 лет — это одна из древнейших «таблиц» в истории математики.', 'The Babylonian tablet Plimpton 322 is about 3 800 years old — one of the oldest “tables” in the history of mathematics.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('To‘g‘ri burchakli uchburchakning o‘tkir burchaklari 1 : 2 nisbatda, gipotenuzasi 14 cm. Kichik katetni toping.', 'Острые углы прямоугольного треугольника относятся как 1 : 2, гипотенуза 14 см. Найдите меньший катет.', 'The acute angles of a right triangle are in the ratio 1 : 2 and the hypotenuse is 14 cm. Find the shorter leg.'),
      L('Teng yonli uchburchakning uchidagi burchagi 120°, asosga tushirilgan balandligi 6 cm. Yon tomonini toping.', 'Угол при вершине равнобедренного треугольника 120°, высота к основанию 6 см. Найдите боковую сторону.', 'An isosceles triangle has apex angle 120° and altitude to the base 6 cm. Find a leg.'),
      L('Burchak ichidagi nuqta uning tomonlaridan 3 cm va 3 cm uzoqlikda. U bissektrisada yotadimi?', 'Точка внутри угла удалена от его сторон на 3 см и 3 см. Лежит ли она на биссектрисе?', 'A point inside an angle is 3 cm from each side. Does it lie on the bisector?')
    ], after: [
      L('Javoblar: 1) 30° va 60°; kichik katet 7 cm. 2) Asosdagi burchak 30°, balandlik uning qarshisida: yon tomon 12 cm. 3) Ha — teskari xossaga ko‘ra.', 'Ответы: 1) 30° и 60°; меньший катет 7 см. 2) Угол при основании 30°, высота лежит против него: боковая сторона 12 см. 3) Да — по обратному свойству.', 'Answers: 1) 30° and 60°; the shorter leg is 7 cm. 2) The base angle is 30° and the altitude is opposite it: the leg is 12 cm. 3) Yes — by the converse property.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('To‘g‘ri burchakli uchburchakda katetlar to‘g‘ri burchakni hosil qiladi, gipotenuza uning qarshisida va eng uzun.', 'В прямоугольном треугольнике катеты образуют прямой угол, гипотенуза лежит против него и самая длинная.', 'In a right triangle the legs form the right angle; the hypotenuse is opposite it and is the longest.'),
      L('O‘tkir burchaklar yig‘indisi 90°.', 'Сумма острых углов 90°.', 'The acute angles sum to 90°.'),
      L('30° qarshisidagi katet = gipotenuza : 2 (va teskarisi).', 'Катет против 30° = гипотенуза : 2 (и обратно).', 'Leg opposite 30° = hypotenuse : 2 (and conversely).'),
      L('Tenglik uchun ikki element yetarli: ikki katet; katet va burchak; gipotenuza va burchak; gipotenuza va katet.', 'Для равенства хватает двух элементов: два катета; катет и угол; гипотенуза и угол; гипотенуза и катет.', 'Two parts suffice for congruence: two legs; leg and angle; hypotenuse and angle; hypotenuse and leg.'),
      L('Bissektrisa nuqtalari burchak tomonlaridan teng uzoqlikda yotadi.', 'Точки биссектрисы равноудалены от сторон угла.', 'Points on a bisector are equidistant from the sides of the angle.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t11. Tomonlar va burchaklar munosabati. Uchburchak tengsizligi ----------
  T.add(P, 't11', { sections: [
    { kind: 'intro', h: L('Har qanday uchta tayoqchadan uchburchak chiqadimi?', 'Получится ли треугольник из любых трёх палочек?', 'Can any three sticks make a triangle?'), p: [
      L('Uzunligi 3 cm, 4 cm va 10 cm bo‘lgan uchta tayoqcha oling va ulardan uchburchak yasashga urinib ko‘ring. Hech narsa chiqmaydi: ikki qisqa tayoqcha uzunini «yopa olmaydi» — ular uchlarida uchrasha olmaydi. 5, 6 va 7 cm li tayoqchalardan esa uchburchak osongina yasaladi. Qachon uchburchak bo‘ladi, qachon bo‘lmaydi? Javobni <b>uchburchak tengsizligi</b> beradi.', 'Возьмите три палочки длиной 3 см, 4 см и 10 см и попробуйте сложить треугольник. Ничего не выйдет: две короткие палочки не могут «перекрыть» длинную — их концы не встретятся. А из палочек 5, 6 и 7 см треугольник складывается легко. Когда треугольник получается, а когда нет? Ответ даёт <b>неравенство треугольника</b>.', 'Take three sticks 3 cm, 4 cm and 10 cm long and try to make a triangle. It won’t work: the two short sticks cannot “span” the long one — their ends never meet. Sticks of 5, 6 and 7 cm make a triangle easily. When does it work and when not? The answer is the <b>triangle inequality</b>.'),
      L('Bu mavzuda yana bir muhim bog‘lanishni o‘rganamiz: uchburchakda katta tomon qarshisida doim katta burchak yotadi. Bu ikki natija birgalikda uchburchak tomonlari va burchaklari haqida juda ko‘p narsani oldindan aytib berishga imkon beradi — hatto hech narsani o‘lchamasdan ham.', 'В этой теме изучим и ещё одну важную связь: в треугольнике против большей стороны всегда лежит больший угол. Вместе эти два результата позволяют многое заранее сказать о сторонах и углах треугольника — даже ничего не измеряя.', 'In this topic we also study another key link: in a triangle the larger side always faces the larger angle. Together these two results let us predict a great deal about a triangle’s sides and angles — without measuring anything.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), p: [
      L('Uchburchakda har bir tomon bitta burchakning <b>qarshisida</b> yotadi: BC tomon ∠A qarshisida, AC tomon ∠B qarshisida, AB tomon ∠C qarshisida. Odatda tomonlar qarshisidagi uchning kichik harfi bilan belgilanadi: a = BC, b = AC, c = AB.', 'В треугольнике каждая сторона лежит <b>против</b> одного угла: BC — против ∠A, AC — против ∠B, AB — против ∠C. Обычно стороны обозначают строчной буквой противолежащей вершины: a = BC, b = AC, c = AB.', 'In a triangle each side lies <b>opposite</b> one angle: BC opposite ∠A, AC opposite ∠B, AB opposite ∠C. Sides are often named by the small letter of the opposite vertex: a = BC, b = AC, c = AB.'),
      L('<b>Tengsizlik</b> — ikki miqdordan qaysi biri katta ekanini ko‘rsatuvchi munosabat (&lt;, &gt;). Geometriyada tengsizliklar tengliklar kabi muhim: ular nimaning mumkin, nimaning mumkin emasligini ko‘rsatadi.', '<b>Неравенство</b> — соотношение, показывающее, какая из двух величин больше (&lt;, &gt;). В геометрии неравенства так же важны, как равенства: они показывают, что возможно, а что нет.', 'An <b>inequality</b> is a relation showing which of two quantities is larger (&lt;, &gt;). In geometry inequalities are as important as equalities: they show what is possible and what is not.'),
      L('Uchta nuqta A, B, C uchun AB + BC ≥ AC har doim bajariladi; tenglik faqat B nuqta AC kesmada yotgan holda bo‘ladi — u holda uchburchak «yassilanib» kesmaga aylanadi.', 'Для трёх точек A, B, C всегда AB + BC ≥ AC; равенство бывает только тогда, когда B лежит на отрезке AC, — тогда треугольник «сплющивается» в отрезок.', 'For any three points A, B, C, AB + BC ≥ AC always holds; equality happens only when B lies on segment AC — then the triangle “flattens” into a segment.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Uchburchak tengsizligi Yevklid «Negizlar» birinchi kitobining 20-tasdig‘ida isbotlangan. Qiziq rivoyat bor: qadimgi yunon faylasuflari epikurchilar bu teoremani masxara qilishgan — ularning aytishicha, uni hatto eshak ham biladi, chunki ochiq maydonda eshak ovqatga doim to‘g‘ri yo‘l bilan boradi, aylanib o‘tmaydi! Ammo matematiklar uchun «hamma biladi» degani isbot emas.', 'Неравенство треугольника доказано в предложении 20 первой книги «Начал» Евклида. Есть любопытное предание: древнегреческие философы-эпикурейцы высмеивали эту теорему — мол, её знает даже осёл, ведь на открытом поле осёл всегда идёт к еде напрямик, а не в обход! Но для математиков «все знают» — не доказательство.', 'The triangle inequality is proved in Proposition 20 of Book I of Euclid’s <i>Elements</i>. A curious story says the Epicurean philosophers mocked this theorem — even a donkey knows it, they said, since in an open field a donkey always walks straight to its food, never around! But for mathematicians “everyone knows” is not a proof.'),
      L('Bugun uchburchak tengsizligi matematikaning ko‘p sohalarida «masofa» tushunchasining asosiy talabi hisoblanadi. Navigatsiya dasturlari va xaritalar eng qisqa yo‘lni hisoblashda aynan shu tamoyilga tayanadi.', 'Сегодня неравенство треугольника — главное требование к понятию «расстояние» во многих областях математики. Навигаторы и карты, рассчитывая кратчайший путь, опираются именно на этот принцип.', 'Today the triangle inequality is the key requirement for any notion of “distance” in many areas of mathematics. Navigation apps and maps rely on exactly this principle when computing the shortest route.')
    ] },
    { kind: 'rule', h: L('Teoremalar va isbot g‘oyalari', 'Теоремы и идеи доказательств', 'Theorems and proof ideas'), p: [
      L('<b>1-teorema.</b> Uchburchakda katta tomon qarshisida katta burchak yotadi. <i>Isbot g‘oyasi:</i> △ABC da AB &gt; AC bo‘lsin. AB tomonga AD = AC kesmani qo‘yamiz (D nuqta AB da). △ADC teng yonli, demak ∠ADC = ∠ACD. ∠ADC — △BDC uchun tashqi burchak, shuning uchun u ∠B dan katta. ∠C esa ∠ACD dan katta (uni o‘z ichiga oladi). Demak ∠C &gt; ∠ACD = ∠ADC &gt; ∠B, ya’ni <b>∠C &gt; ∠B</b>.', '<b>Теорема 1.</b> В треугольнике против большей стороны лежит больший угол. <i>Идея доказательства:</i> пусть в △ABC AB &gt; AC. Отложим на AB отрезок AD = AC (D на AB). △ADC равнобедренный, значит ∠ADC = ∠ACD. ∠ADC — внешний угол △BDC, поэтому он больше ∠B. А ∠C больше ∠ACD (содержит его). Значит, ∠C &gt; ∠ACD = ∠ADC &gt; ∠B, то есть <b>∠C &gt; ∠B</b>.', '<b>Theorem 1.</b> In a triangle the larger side faces the larger angle. <i>Proof idea:</i> in △ABC let AB &gt; AC. Mark D on AB with AD = AC. △ADC is isosceles, so ∠ADC = ∠ACD. ∠ADC is an exterior angle of △BDC, so it is greater than ∠B. And ∠C is greater than ∠ACD (it contains it). So ∠C &gt; ∠ACD = ∠ADC &gt; ∠B, that is, <b>∠C &gt; ∠B</b>.'),
      L('<b>2-teorema (teskarisi).</b> Katta burchak qarshisida katta tomon yotadi. (Teskarisidan faraz bilan isbotlanadi.) <b>Natijalar:</b> to‘g‘ri burchakli uchburchakda gipotenuza katetlardan uzun; teng burchaklar qarshisida teng tomonlar yotadi.', '<b>Теорема 2 (обратная).</b> Против большего угла лежит большая сторона. (Доказывается от противного.) <b>Следствия:</b> в прямоугольном треугольнике гипотенуза длиннее катетов; против равных углов лежат равные стороны.', '<b>Theorem 2 (converse).</b> The larger angle faces the larger side. (Proved by contradiction.) <b>Corollaries:</b> in a right triangle the hypotenuse is longer than the legs; equal angles face equal sides.'),
      L('<b>3-teorema (uchburchak tengsizligi).</b> Uchburchakning har bir tomoni qolgan ikki tomoni yig‘indisidan kichik: a &lt; b + c, b &lt; a + c, c &lt; a + b. <i>Isbot g‘oyasi:</i> AC tomonni C dan nariga davom ettirib, CD = CB qo‘yamiz. △BCD teng yonli: ∠CBD = ∠CDB. △ABD da ∠ABD = ∠ABC + ∠CBD &gt; ∠CDB = ∠ADB. Katta burchak qarshisida katta tomon: AD &gt; AB. Lekin AD = AC + CD = AC + CB. Demak <b>AB &lt; AC + CB</b>.', '<b>Теорема 3 (неравенство треугольника).</b> Каждая сторона треугольника меньше суммы двух других: a &lt; b + c, b &lt; a + c, c &lt; a + b. <i>Идея доказательства:</i> продолжим AC за точку C и отложим CD = CB. △BCD равнобедренный: ∠CBD = ∠CDB. В △ABD ∠ABD = ∠ABC + ∠CBD &gt; ∠CDB = ∠ADB. Против большего угла — большая сторона: AD &gt; AB. Но AD = AC + CD = AC + CB. Значит, <b>AB &lt; AC + CB</b>.', '<b>Theorem 3 (triangle inequality).</b> Each side of a triangle is less than the sum of the other two: a &lt; b + c, b &lt; a + c, c &lt; a + b. <i>Proof idea:</i> extend AC beyond C and mark CD = CB. △BCD is isosceles: ∠CBD = ∠CDB. In △ABD, ∠ABD = ∠ABC + ∠CBD &gt; ∠CDB = ∠ADB. The larger angle faces the larger side: AD &gt; AB. But AD = AC + CD = AC + CB. Therefore <b>AB &lt; AC + CB</b>.')
    ] },
    { kind: 'steps', h: L('Uchburchak bo‘ladimi — tekshirish', 'Проверка: получится ли треугольник', 'Checking whether a triangle exists'), list: [
      L('1-qadam. Uchta uzunlikni o‘sish tartibida yozing: a ≤ b ≤ c.', 'Шаг 1. Запишите три длины по возрастанию: a ≤ b ≤ c.', 'Step 1. Write the three lengths in increasing order: a ≤ b ≤ c.'),
      L('2-qadam. Faqat bitta tengsizlikni tekshiring: <b>c &lt; a + b</b> (eng katta tomon ikki kichigi yig‘indisidan kichikmi?). Qolgan ikkitasi o‘z-o‘zidan bajariladi.', 'Шаг 2. Проверьте лишь одно неравенство: <b>c &lt; a + b</b> (наибольшая сторона меньше суммы двух меньших?). Остальные два выполняются автоматически.', 'Step 2. Check only one inequality: <b>c &lt; a + b</b> (is the largest side less than the sum of the other two?). The other two hold automatically.'),
      L('3-qadam. Agar c &lt; a + b bo‘lsa — uchburchak bor; c = a + b yoki c &gt; a + b bo‘lsa — yo‘q.', 'Шаг 3. Если c &lt; a + b — треугольник существует; если c = a + b или c &gt; a + b — нет.', 'Step 3. If c &lt; a + b, the triangle exists; if c = a + b or c &gt; a + b, it does not.'),
      L('Uchinchi tomon chegaralari: ikki tomon a va b ma’lum bo‘lsa, uchinchi tomon x uchun <b>|a − b| &lt; x &lt; a + b</b>.', 'Границы третьей стороны: если известны стороны a и b, то для третьей стороны x: <b>|a − b| &lt; x &lt; a + b</b>.', 'Range of the third side: if sides a and b are known, the third side x satisfies <b>|a − b| &lt; x &lt; a + b</b>.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Tomonlari 4 cm, 7 cm va 12 cm bo‘lgan uchburchak bormi?', 'Существует ли треугольник со сторонами 4 см, 7 см и 12 см?', 'Is there a triangle with sides 4 cm, 7 cm and 12 cm?'), s: L('Eng katta tomon 12. 4 + 7 = 11 &lt; 12. Tengsizlik bajarilmaydi — <b>bunday uchburchak yo‘q</b>.', 'Наибольшая сторона 12. 4 + 7 = 11 &lt; 12. Неравенство не выполняется — <b>такого треугольника нет</b>.', 'The largest side is 12. 4 + 7 = 11 &lt; 12. The inequality fails — <b>no such triangle</b>.') },
      { q: L('Uchburchakning ikki tomoni 6 cm va 10 cm. Uchinchi tomon qanday butun qiymatlarni qabul qila oladi?', 'Две стороны треугольника 6 см и 10 см. Какие целые значения может принимать третья сторона?', 'Two sides of a triangle are 6 cm and 10 cm. What whole-number values can the third side take?'), s: L('10 − 6 &lt; x &lt; 10 + 6, ya’ni 4 &lt; x &lt; 16. Butun qiymatlar: <b>5, 6, …, 15</b> (11 ta qiymat).', '10 − 6 &lt; x &lt; 10 + 6, то есть 4 &lt; x &lt; 16. Целые значения: <b>5, 6, …, 15</b> (11 значений).', '10 − 6 &lt; x &lt; 10 + 6, so 4 &lt; x &lt; 16. Whole values: <b>5, 6, …, 15</b> (11 values).') },
      { q: L('△ABC da AB = 5, BC = 8, AC = 7. Eng katta va eng kichik burchakni toping.', 'В △ABC AB = 5, BC = 8, AC = 7. Найдите наибольший и наименьший углы.', 'In △ABC, AB = 5, BC = 8, AC = 7. Find the largest and smallest angles.'), s: L('Eng katta tomon BC = 8, uning qarshisida ∠A — <b>eng katta</b>. Eng kichik tomon AB = 5, uning qarshisida ∠C — <b>eng kichik</b>.', 'Наибольшая сторона BC = 8, против неё ∠A — <b>наибольший</b>. Наименьшая сторона AB = 5, против неё ∠C — <b>наименьший</b>.', 'The largest side is BC = 8, opposite ∠A — the <b>largest</b> angle. The smallest side is AB = 5, opposite ∠C — the <b>smallest</b>.') },
      { q: L('Teng yonli uchburchakning ikki tomoni 5 cm va 11 cm. Perimetrini toping.', 'Две стороны равнобедренного треугольника 5 см и 11 см. Найдите периметр.', 'Two sides of an isosceles triangle are 5 cm and 11 cm. Find the perimeter.'), s: L('Agar yon tomonlar 5 bo‘lsa: 5 + 5 = 10 &lt; 11 — uchburchak yo‘q. Demak yon tomonlar 11, asos 5: 11 &lt; 11 + 5 — bor. P = 11 + 11 + 5 = <b>27 cm</b>.', 'Если боковые стороны 5: 5 + 5 = 10 &lt; 11 — треугольника нет. Значит, боковые 11, основание 5: 11 &lt; 11 + 5 — существует. P = 11 + 11 + 5 = <b>27 см</b>.', 'If the legs were 5: 5 + 5 = 10 &lt; 11 — no triangle. So the legs are 11 and the base 5: 11 &lt; 11 + 5 — it exists. P = 11 + 11 + 5 = <b>27 cm</b>.') }
    ] },
    { kind: 'table', h: L('Tekshiruv jadvali', 'Таблица проверки', 'Checking table'), table: { head: [L('Tomonlar', 'Стороны', 'Sides'), L('Ikki kichigi yig‘indisi', 'Сумма двух меньших', 'Sum of two smaller'), L('Eng kattasi', 'Наибольшая', 'Largest'), L('Uchburchakmi?', 'Треугольник?', 'Triangle?')], rows: [
      ['3, 4, 5', '7', '5', L('ha', 'да', 'yes')],
      ['2, 3, 5', '5', '5', L('yo‘q (kesma)', 'нет (отрезок)', 'no (a segment)')],
      ['3, 4, 10', '7', '10', L('yo‘q', 'нет', 'no')],
      ['6, 6, 11', '12', '11', L('ha', 'да', 'yes')],
      ['1, 1, 1', '2', '1', L('ha (teng tomonli)', 'да (равносторонний)', 'yes (equilateral)')]
    ] }, after: [
      L('Ikkinchi qatorga e’tibor bering: yig‘indi aynan teng bo‘lsa, uchburchak «yassilanib» qoladi — uchala nuqta bir to‘g‘ri chiziqda yotadi. Shuning uchun tengsizlik qat’iy: &lt;, ≤ emas.', 'Обратите внимание на вторую строку: если сумма в точности равна, треугольник «сплющивается» — три точки лежат на одной прямой. Поэтому неравенство строгое: &lt;, а не ≤.', 'Note the second row: if the sum is exactly equal, the triangle “flattens” — the three points lie on one line. That is why the inequality is strict: &lt;, not ≤.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Noto‘g‘ri tengsizlikni tekshirish.</b> Ikki <i>kichik</i> tomon yig‘indisini <i>katta</i> tomon bilan solishtiring. 3 + 10 &gt; 4 deb tekshirish hech narsa bermaydi.', '<b>Проверять «не то» неравенство.</b> Сравнивайте сумму двух <i>меньших</i> сторон с <i>большей</i>. Проверка 3 + 10 &gt; 4 ничего не даёт.', '<b>Checking the wrong inequality.</b> Compare the sum of the two <i>smaller</i> sides with the <i>largest</i>. Checking 3 + 10 &gt; 4 tells you nothing.'),
      L('<b>Tenglik holini qabul qilish.</b> 2, 3, 5 — uchburchak emas, chunki 2 + 3 = 5.', '<b>Принимать случай равенства.</b> 2, 3, 5 — не треугольник, ведь 2 + 3 = 5.', '<b>Accepting the equality case.</b> 2, 3, 5 is not a triangle because 2 + 3 = 5.'),
      L('<b>Burchakni noto‘g‘ri tomonga bog‘lash.</b> Katta burchak katta tomonning <i>qarshisida</i>, unga yopishgan emas.', '<b>Связывать угол не с той стороной.</b> Больший угол лежит <i>против</i> большей стороны, а не прилежит к ней.', '<b>Linking the angle to the wrong side.</b> The larger angle is <i>opposite</i> the larger side, not next to it.'),
      L('<b>Teng yonli masalada ikki holni tekshirmaslik.</b> 4-namunadagidek, ba’zi variant uchburchak tengsizligini buzadi va chiqarib tashlanadi.', '<b>Не проверять два случая в задаче о равнобедренном.</b> Как в примере 4, один вариант может нарушать неравенство треугольника и отбрасывается.', '<b>Not checking both cases for an isosceles triangle.</b> As in example 4, one option may break the triangle inequality and must be rejected.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Yo‘l tanlashda.</b> Maktabdan uyga to‘g‘ri yo‘l doim aylanma yo‘ldan qisqa. Shuning uchun maysazorlarda odamlar burchakni kesib o‘tadigan so‘qmoq paydo bo‘ladi — ular intuitiv ravishda uchburchak tengsizligidan foydalanadi.', '<b>При выборе пути.</b> Прямая дорога от школы до дома всегда короче обходной. Поэтому на газонах появляются тропинки, срезающие угол, — люди интуитивно пользуются неравенством треугольника.', '<b>Choosing a route.</b> The straight road from school to home is always shorter than a detour. That is why paths appear across lawns, cutting corners — people use the triangle inequality by instinct.'),
      L('<b>Navigatorlarda.</b> Yandeks yoki Google xaritalari eng qisqa yo‘lni izlaganda, «A dan C ga to‘g‘ridan-to‘g‘ri borish B orqali borishdan uzoq emas» qoidasidan foydalanib, keraksiz variantlarni tez chiqarib tashlaydi.', '<b>В навигаторах.</b> Карты, ища кратчайший путь, используют правило «прямо из A в C — не длиннее, чем через B», чтобы быстро отбрасывать лишние варианты.', '<b>In navigation apps.</b> Map apps searching for the shortest route use the rule “straight from A to C is never longer than via B” to discard useless options quickly.'),
      L('<b>Qurilishda.</b> Usta uchta to‘sindan ferma yig‘ishdan oldin ularning uzunliklarini tekshiradi: agar eng uzuni qolgan ikkitasi yig‘indisidan uzun bo‘lsa, ferma yig‘ilmaydi.', '<b>В строительстве.</b> Прежде чем собрать ферму из трёх балок, мастер проверяет длины: если самая длинная больше суммы двух других, ферма не соберётся.', '<b>In building.</b> Before assembling a truss from three beams, the builder checks the lengths: if the longest exceeds the sum of the other two, it won’t fit together.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Yorug‘lik ikki nuqta orasida eng tez yo‘lni tanlaydi (Ferma tamoyili). Bir jinsli muhitda bu — to‘g‘ri chiziq, uchburchak tengsizligi tufayli eng qisqa yo‘l.', 'Свет выбирает между двумя точками самый быстрый путь (принцип Ферма). В однородной среде это прямая — кратчайший путь благодаря неравенству треугольника.', 'Light takes the fastest path between two points (Fermat’s principle). In a uniform medium that is a straight line — the shortest path, thanks to the triangle inequality.'),
      L('Uchburchak tomonlari 1, 2, 3, … kabi ketma-ket sonlar bo‘lishi uchun eng kichik variant 2, 3, 4 (1, 2, 3 — yassi). Tomonlari ketma-ket sonlar bo‘lgan eng mashhur uchburchak — 3, 4, 5, u to‘g‘ri burchakli.', 'Самый маленький треугольник со сторонами — последовательными числами: 2, 3, 4 (1, 2, 3 — вырожденный). Самый знаменитый треугольник с последовательными сторонами — 3, 4, 5, он прямоугольный.', 'The smallest triangle with consecutive whole-number sides is 2, 3, 4 (1, 2, 3 is flat). The most famous one is 3, 4, 5, and it is a right triangle.'),
      L('Arilar gullar orasida uchganda ham eng qisqa marshrutni tanlashga harakat qiladi — olimlar buni tajribalarda kuzatgan.', 'Пчёлы, летая между цветками, тоже стараются выбрать кратчайший маршрут — учёные наблюдали это в опытах.', 'Bees flying between flowers also try to choose the shortest route — scientists have observed this in experiments.')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Tomonlari 5, 9 va x bo‘lgan uchburchakda x butun son. x ning eng kichik va eng katta qiymatlari?', 'В треугольнике со сторонами 5, 9 и x число x целое. Наименьшее и наибольшее значения x?', 'In a triangle with sides 5, 9 and x, x is a whole number. Smallest and largest x?'),
      L('△ABC da ∠A = 50°, ∠B = 60°. Qaysi tomon eng uzun?', 'В △ABC ∠A = 50°, ∠B = 60°. Какая сторона самая длинная?', 'In △ABC, ∠A = 50°, ∠B = 60°. Which side is longest?'),
      L('Perimetri 20 cm bo‘lgan uchburchak tomoni 10 cm bo‘lishi mumkinmi?', 'Может ли сторона треугольника с периметром 20 см быть равна 10 см?', 'Can a triangle with perimeter 20 cm have a side of 10 cm?')
    ], after: [
      L('Javoblar: 1) 4 &lt; x &lt; 14: eng kichik 5, eng katta 13. 2) ∠C = 70° — eng katta, demak AB eng uzun. 3) Yo‘q: qolgan ikkitasi yig‘indisi ham 10 bo‘lardi, 10 &lt; 10 bajarilmaydi.', 'Ответы: 1) 4 &lt; x &lt; 14: наименьшее 5, наибольшее 13. 2) ∠C = 70° — наибольший, значит AB самая длинная. 3) Нет: сумма двух других тоже была бы 10, а 10 &lt; 10 неверно.', 'Answers: 1) 4 &lt; x &lt; 14: smallest 5, largest 13. 2) ∠C = 70° is largest, so AB is longest. 3) No: the other two would also sum to 10, and 10 &lt; 10 is false.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Katta tomon qarshisida katta burchak, katta burchak qarshisida katta tomon yotadi.', 'Против большей стороны лежит больший угол, против большего угла — большая сторона.', 'The larger side faces the larger angle, and the larger angle faces the larger side.'),
      L('Teng tomonlar qarshisida teng burchaklar (va aksincha).', 'Против равных сторон — равные углы (и наоборот).', 'Equal sides face equal angles (and vice versa).'),
      L('Uchburchak tengsizligi: har bir tomon qolgan ikkitasi yig‘indisidan kichik.', 'Неравенство треугольника: каждая сторона меньше суммы двух других.', 'Triangle inequality: each side is less than the sum of the other two.'),
      L('Tekshirish uchun eng katta tomonni ikki kichigi yig‘indisi bilan solishtirish yetarli.', 'Для проверки достаточно сравнить наибольшую сторону с суммой двух меньших.', 'To check, compare the largest side with the sum of the two smaller ones.'),
      L('Uchinchi tomon: |a − b| &lt; x &lt; a + b.', 'Третья сторона: |a − b| &lt; x &lt; a + b.', 'Third side: |a − b| &lt; x &lt; a + b.')
    ] }
  ] });
})(this);
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '7-3';

  // ---------- t12. Sirkul va chizg‘ich yordamida yasash ----------
  T.add(P, 't12', { sections: [
    { kind: 'intro', h: L('Ikki asbob — cheksiz imkoniyat', 'Два инструмента — бесконечные возможности', 'Two tools, endless possibilities'), p: [
      L('Tasavvur qiling: sizga faqat sirkul va belgisiz chizg‘ich berildi — o‘lchov shkalasi ham, transportir ham yo‘q. Shu ikki asbob bilan kesmani aniq teng ikkiga bo‘lish, burchakni teng ikkiga bo‘lish, perpendikulyar o‘tkazish, berilgan uchburchakka teng uchburchak chizish mumkinmi? Ha! Qadimgi yunonlar aynan shu o‘yinni o‘ynashgan va undan geometriyaning butun bir bo‘limi — <b>yasashga doir masalalar</b> paydo bo‘lgan.', 'Представьте: вам дали только циркуль и линейку без делений — ни шкалы, ни транспортира. Можно ли этими двумя инструментами точно разделить отрезок пополам, разделить угол пополам, провести перпендикуляр, начертить треугольник, равный данному? Да! Древние греки играли именно в эту игру, и из неё вырос целый раздел геометрии — <b>задачи на построение</b>.', 'Imagine you are given only a compass and an unmarked straightedge — no scale, no protractor. Can you split a segment exactly in half, bisect an angle, draw a perpendicular, copy a triangle with these two tools? Yes! The ancient Greeks played exactly this game, and a whole branch of geometry grew out of it: <b>construction problems</b>.'),
      L('Yasash — bu chizish emas, balki isbot. Har bir qadam aksioma yoki teoremaga tayanadi, natija esa mutlaqo aniq — o‘lchash xatoligi bo‘lmaydi. Bu mavzuda beshta asosiy yasashni o‘rganamiz va har birining nima uchun to‘g‘ri ishlashini uchburchaklar tengligi alomatlari orqali tushuntiramiz.', 'Построение — это не просто рисование, а доказательство. Каждый шаг опирается на аксиому или теорему, а результат абсолютно точен — без погрешности измерения. В этой теме изучим пять основных построений и объясним, почему каждое из них работает, с помощью признаков равенства треугольников.', 'A construction is not just drawing — it is a proof. Every step rests on an axiom or theorem, and the result is exact, with no measuring error. In this topic we learn five basic constructions and explain why each works using the congruence tests.')
    ] },
    { kind: 'def', h: L('Yasash qoidalari', 'Правила построений', 'The rules of construction'), p: [
      L('<b>Aylana</b> — tekislikning berilgan nuqtadan (markazdan) bir xil masofada yotgan barcha nuqtalari. Bu masofa — <b>radius</b>. Aylananing bir qismi — <b>yoy</b>. Sirkul aynan aylana va yoylarni chizadi.', '<b>Окружность</b> — все точки плоскости, удалённые от данной точки (центра) на одно и то же расстояние. Это расстояние — <b>радиус</b>. Часть окружности — <b>дуга</b>. Циркуль чертит именно окружности и дуги.', 'A <b>circle</b> is the set of all points in the plane at the same distance from a given point (the centre). That distance is the <b>radius</b>. Part of a circle is an <b>arc</b>. A compass draws exactly circles and arcs.')
    ], list: [
      L('<b>Chizg‘ich</b> bilan faqat ikki berilgan nuqta orqali to‘g‘ri chiziq o‘tkazish mumkin. U bilan uzunlik o‘lchanmaydi!', '<b>Линейкой</b> можно только провести прямую через две данные точки. Длины ею не измеряют!', 'With the <b>straightedge</b> you may only draw a line through two given points. It is not used to measure lengths!'),
      L('<b>Sirkul</b> bilan berilgan markaz va berilgan radiusli aylana (yoki yoy) chizish mumkin. Radius sifatida chizmadagi kesma uzunligini olish mumkin.', '<b>Циркулем</b> можно провести окружность (или дугу) с данным центром и данным радиусом. Радиусом может служить длина отрезка на чертеже.', 'With the <b>compass</b> you may draw a circle (or arc) with a given centre and given radius. The radius can be taken from a segment in the drawing.'),
      L('Yangi nuqtalar faqat chiziqlar va aylanalarning <b>kesishishidan</b> olinadi.', 'Новые точки получают только как <b>точки пересечения</b> прямых и окружностей.', 'New points come only from <b>intersections</b> of lines and circles.')
    ], after: [
      L('Yasash masalasi to‘rt qismdan iborat: <b>tahlil</b> (izlanayotgan shaklni tayyor deb faraz qilib, uni qanday hosil qilish kerakligini o‘ylash), <b>yasash</b> (qadamlar), <b>isbot</b> (nega to‘g‘ri) va <b>tekshirish</b> (yechim doim bormi, nechta).', 'Задача на построение состоит из четырёх частей: <b>анализ</b> (считаем искомую фигуру построенной и думаем, как её получить), <b>построение</b> (шаги), <b>доказательство</b> (почему верно) и <b>исследование</b> (всегда ли есть решение и сколько их).', 'A construction problem has four parts: <b>analysis</b> (imagine the figure is done and work out how to get it), <b>construction</b> (the steps), <b>proof</b> (why it is right) and <b>discussion</b> (is there always a solution, and how many).')
    ] },
    { kind: 'history', h: L('Uchta mashhur imkonsiz masala', 'Три знаменитые невозможные задачи', 'Three famous impossible problems'), p: [
      L('Yevklid «Negizlar»ning birinchi kitobi yasash masalasi bilan boshlanadi: berilgan kesma ustida teng tomonli uchburchak yasash. Yunonlar sirkul va chizg‘ich bilan juda ko‘p narsani yasashni o‘rganishgan, ammo uchta masala ming yillar davomida yechilmay qolgan: <b>burchak triseksiyasi</b> (ixtiyoriy burchakni teng uchga bo‘lish), <b>kubni ikkilantirish</b> (hajmi berilgan kubdan ikki marta katta kub qirrasini yasash) va <b>doira kvadraturasi</b> (doiraga tengdosh kvadrat yasash).', 'Первая книга «Начал» Евклида начинается с задачи на построение: построить равносторонний треугольник на данном отрезке. Греки научились строить циркулем и линейкой очень многое, но три задачи оставались нерешёнными тысячи лет: <b>трисекция угла</b> (разделить любой угол на три равные части), <b>удвоение куба</b> (построить ребро куба вдвое большего объёма) и <b>квадратура круга</b> (построить квадрат, равновеликий кругу).', 'Book I of Euclid’s <i>Elements</i> opens with a construction problem: build an equilateral triangle on a given segment. The Greeks learned to construct a great deal with compass and straightedge, but three problems stayed unsolved for thousands of years: <b>trisecting an angle</b> (dividing any angle into three equal parts), <b>doubling the cube</b> (constructing the edge of a cube with twice the volume) and <b>squaring the circle</b> (constructing a square with the same area as a circle).'),
      L('Faqat XIX asrda algebra yordamida bu masalalar <b>yechimsiz</b> ekani isbotlandi. 1837-yili fransuz matematigi <b>Pyer Vansel</b> triseksiya va kubni ikkilantirish imkonsizligini, 1882-yili nemis matematigi <b>Ferdinand Lindeman</b> esa π sonining xossasini isbotlab, doira kvadraturasi ham imkonsizligini ko‘rsatdi. Undan oldin, 1796-yili 19 yoshli <b>Karl Gauss</b> muntazam 17-burchakni sirkul va chizg‘ich bilan yasash mumkinligini kashf etgan.', 'Лишь в XIX веке с помощью алгебры было доказано, что эти задачи <b>неразрешимы</b>. В 1837 году французский математик <b>Пьер Ванцель</b> доказал невозможность трисекции и удвоения куба, а в 1882 году немецкий математик <b>Фердинанд Линдеман</b>, доказав особое свойство числа π, показал невозможность квадратуры круга. А ещё раньше, в 1796 году, 19-летний <b>Карл Гаусс</b> открыл, что правильный 17-угольник можно построить циркулем и линейкой.', 'Only in the 19th century did algebra prove these problems <b>impossible</b>. In 1837 the French mathematician <b>Pierre Wantzel</b> proved that trisection and doubling the cube cannot be done, and in 1882 the German mathematician <b>Ferdinand von Lindemann</b>, by proving a special property of π, showed that squaring the circle is impossible too. Earlier, in 1796, the 19-year-old <b>Carl Gauss</b> discovered that a regular 17-gon can be constructed with compass and straightedge.'),
      L('Sharq olimlari ham yasashlar bilan shug‘ullangan: <b>Abu-l-Vafo Buzjoniy</b> (X asr) ustalar uchun yasashlar haqida maxsus kitob yozgan, unda sirkulning ochilishi o‘zgarmas bo‘lgan holdagi yasashlar ham bor. <b>Beruniy</b> esa triseksiya masalasini tekshirib, uni yechish uchun boshqa usullardan foydalangan.', 'Учёные Востока тоже занимались построениями: <b>Абу-ль-Вафа аль-Бузджани</b> (X век) написал для ремесленников особую книгу о построениях, в том числе циркулем с неизменным раствором. <b>Беруни</b> исследовал задачу о трисекции и решал её другими средствами.', 'Scholars of the East worked on constructions too: <b>Abu al-Wafa al-Buzjani</b> (10th century) wrote a special book on constructions for craftsmen, including some with a compass of fixed opening. <b>Biruni</b> studied the trisection problem and solved it by other means.')
    ] },
    { kind: 'rule', h: L('Beshta asosiy yasash', 'Пять основных построений', 'Five basic constructions'), list: [
      L('<b>1. Berilgan burchakka teng burchak yasash.</b> ∠A uchidan ixtiyoriy radiusli yoy chizamiz, u tomonlarni B va C da kesadi. Yangi nur OM ning boshi O dan xuddi shu radiusli yoy chizamiz, u OM ni B₁ da kesadi. B₁ dan BC radiusli yoy chizamiz, kesishish — C₁. OC₁ nurini o‘tkazamiz. <i>Nega to‘g‘ri:</i> △ABC = △OB₁C₁ (TTT), demak ∠B₁OC₁ = ∠A.', '<b>1. Построение угла, равного данному.</b> Из вершины ∠A проводим дугу произвольного радиуса, она пересекает стороны в B и C. Из начала O нового луча OM проводим дугу того же радиуса, она пересекает OM в B₁. Из B₁ проводим дугу радиуса BC, пересечение — C₁. Проводим луч OC₁. <i>Почему верно:</i> △ABC = △OB₁C₁ (ССС), значит ∠B₁OC₁ = ∠A.', '<b>1. Copying an angle.</b> From vertex A draw an arc of any radius, cutting the sides at B and C. From O, the start of the new ray OM, draw an arc of the same radius, cutting OM at B₁. From B₁ draw an arc of radius BC; the crossing is C₁. Draw ray OC₁. <i>Why it works:</i> △ABC ≅ △OB₁C₁ (SSS), so ∠B₁OC₁ = ∠A.'),
      L('<b>2. Burchak bissektrisasini yasash.</b> Uchidan yoy chizib, tomonlarda B va C nuqtalarni olamiz. B va C dan bir xil radiusli yoylar chizamiz, ular burchak ichida D da kesishadi. AD — bissektrisa. <i>Nega:</i> △ABD = △ACD (TTT: AB = AC, BD = CD, AD umumiy).', '<b>2. Построение биссектрисы угла.</b> Из вершины проводим дугу, получаем на сторонах точки B и C. Из B и C проводим дуги одного радиуса, они пересекаются внутри угла в D. AD — биссектриса. <i>Почему:</i> △ABD = △ACD (ССС: AB = AC, BD = CD, AD общая).', '<b>2. Bisecting an angle.</b> From the vertex draw an arc, getting points B and C on the sides. From B and C draw arcs of equal radius meeting inside the angle at D. AD is the bisector. <i>Why:</i> △ABD ≅ △ACD (SSS: AB = AC, BD = CD, AD common).'),
      L('<b>3. Kesmaning o‘rtasini (o‘rta perpendikulyarni) yasash.</b> A va B uchlaridan AB ning yarmidan katta bir xil radiusli yoylar chizamiz; ular P va Q da kesishadi. PQ to‘g‘ri chiziq AB ni o‘rtasi M da va 90° ostida kesadi. <i>Nega:</i> △APQ = △BPQ (TTT) ⇒ ∠APM = ∠BPM, so‘ng △APM = △BPM (TBT) ⇒ AM = MB va ∠AMP = ∠BMP = 90°.', '<b>3. Построение середины отрезка (серединного перпендикуляра).</b> Из концов A и B проводим дуги одного радиуса, большего половины AB; они пересекаются в P и Q. Прямая PQ пересекает AB в середине M под углом 90°. <i>Почему:</i> △APQ = △BPQ (ССС) ⇒ ∠APM = ∠BPM, затем △APM = △BPM (СУС) ⇒ AM = MB и ∠AMP = ∠BMP = 90°.', '<b>3. Finding the midpoint (perpendicular bisector).</b> From ends A and B draw arcs of equal radius, more than half of AB; they meet at P and Q. Line PQ cuts AB at its midpoint M at 90°. <i>Why:</i> △APQ ≅ △BPQ (SSS) ⇒ ∠APM = ∠BPM, then △APM ≅ △BPM (SAS) ⇒ AM = MB and ∠AMP = ∠BMP = 90°.'),
      L('<b>4. Nuqta orqali to‘g‘ri chiziqqa perpendikulyar.</b> Berilgan O nuqtadan (chiziqda yoki undan tashqarida) yoy chizib, chiziqda A va B nuqtalarni olamiz (OA = OB). So‘ng AB kesmaning o‘rta perpendikulyarini yasaymiz — u O dan o‘tadi va izlanayotgan perpendikulyar bo‘ladi.', '<b>4. Перпендикуляр к прямой через точку.</b> Из данной точки O (на прямой или вне её) проводим дугу и получаем на прямой точки A и B (OA = OB). Затем строим серединный перпендикуляр к AB — он проходит через O и является искомым.', '<b>4. A perpendicular through a point.</b> From the given point O (on the line or off it) draw an arc to get points A and B on the line (OA = OB). Then construct the perpendicular bisector of AB — it passes through O and is the required perpendicular.'),
      L('<b>5. Uch tomoni bo‘yicha uchburchak yasash.</b> To‘g‘ri chiziqda a ga teng BC kesmani qo‘yamiz. B markazdan c radiusli, C markazdan b radiusli aylanalar chizamiz; kesishish nuqtasi — A. Bu faqat uchburchak tengsizligi bajarilganda mumkin: aks holda aylanalar kesishmaydi.', '<b>5. Построение треугольника по трём сторонам.</b> На прямой откладываем отрезок BC, равный a. Из центра B проводим окружность радиуса c, из центра C — радиуса b; точка пересечения — A. Это возможно, только если выполнено неравенство треугольника: иначе окружности не пересекутся.', '<b>5. A triangle from three sides.</b> Lay off BC = a on a line. Draw a circle of radius c about B and a circle of radius b about C; their crossing is A. This works only if the triangle inequality holds — otherwise the circles do not meet.')
    ] },
    { kind: 'steps', h: L('Yasashni bajarish tartibi', 'Порядок выполнения построения', 'How to carry out a construction'), list: [
      L('1-qadam. <b>Tahlil:</b> izlanayotgan shaklni qo‘lda taxminiy chizing va undagi qaysi elementlar berilganini belgilang.', 'Шаг 1. <b>Анализ:</b> от руки сделайте примерный чертёж искомой фигуры и отметьте, какие элементы даны.', 'Step 1. <b>Analysis:</b> sketch the required figure roughly by hand and mark which parts are given.'),
      L('2-qadam. Asosiy yasashlardan qaysilari kerakligini aniqlang (burchak ko‘chirish, bissektrisa, o‘rta perpendikulyar va hokazo).', 'Шаг 2. Определите, какие из основных построений понадобятся (копирование угла, биссектриса, серединный перпендикуляр и т. д.).', 'Step 2. Decide which basic constructions you need (copying an angle, bisector, perpendicular bisector, and so on).'),
      L('3-qadam. <b>Yasash:</b> ingichka qalam bilan aniq bajaring, sirkul ochilishini qadamlar orasida tasodifan o‘zgartirmang.', 'Шаг 3. <b>Построение:</b> выполняйте аккуратно тонким карандашом, не сбивайте раствор циркуля между шагами.', 'Step 3. <b>Construction:</b> work carefully with a sharp pencil and don’t accidentally change the compass opening between steps.'),
      L('4-qadam. <b>Isbot:</b> hosil bo‘lgan teng uchburchaklarni ko‘rsating va alomatni ayting.', 'Шаг 4. <b>Доказательство:</b> укажите получившиеся равные треугольники и назовите признак.', 'Step 4. <b>Proof:</b> point out the congruent triangles that appear and name the test.'),
      L('5-qadam. <b>Tekshirish:</b> masala doim yechimga egami? Nechta yechim bor? (Masalan, uch tomoni bo‘yicha uchburchak faqat tengsizlik bajarilsa bor.)', 'Шаг 5. <b>Исследование:</b> всегда ли есть решение? Сколько их? (Например, треугольник по трём сторонам есть, только если выполнено неравенство.)', 'Step 5. <b>Discussion:</b> does a solution always exist? How many? (A triangle from three sides exists only if the inequality holds.)')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Разобранные примеры', 'Worked examples'), ex: [
      { q: L('Sirkul va chizg‘ich bilan 60° li burchak yasang.', 'Постройте циркулем и линейкой угол 60°.', 'Construct a 60° angle with compass and straightedge.'), s: L('Ixtiyoriy AB kesma chizamiz. A va B markazlardan AB radiusli yoylar chizamiz, ular C da kesishadi. △ABC teng tomonli (AB = AC = BC), demak ∠CAB = <b>60°</b>. Bu Yevklidning birinchi yasashi.', 'Чертим произвольный отрезок AB. Из центров A и B проводим дуги радиуса AB, они пересекаются в C. △ABC равносторонний (AB = AC = BC), значит ∠CAB = <b>60°</b>. Это первое построение Евклида.', 'Draw any segment AB. With centres A and B draw arcs of radius AB meeting at C. △ABC is equilateral (AB = AC = BC), so ∠CAB = <b>60°</b>. This is Euclid’s very first construction.') },
      { q: L('30° va 15° li burchaklarni yasang.', 'Постройте углы 30° и 15°.', 'Construct angles of 30° and 15°.'), s: L('Avval 60° yasaymiz (1-namuna), so‘ng uning bissektrisasini yasaymiz — <b>30°</b>. 30° ning bissektrisasi — <b>15°</b>. Har bir bissektrisa burchakni aniq teng ikkiga bo‘ladi.', 'Сначала строим 60° (пример 1), затем его биссектрису — <b>30°</b>. Биссектриса 30° даёт <b>15°</b>. Каждая биссектриса делит угол точно пополам.', 'First construct 60° (example 1), then its bisector — <b>30°</b>. The bisector of 30° gives <b>15°</b>. Each bisector halves the angle exactly.') },
      { q: L('Tomonlari 4 cm, 5 cm va 10 cm bo‘lgan uchburchak yasang.', 'Постройте треугольник со сторонами 4 см, 5 см и 10 см.', 'Construct a triangle with sides 4 cm, 5 cm and 10 cm.'), s: L('BC = 10 cm qo‘yamiz. B dan 4 cm, C dan 5 cm radiusli aylanalar chizamiz. 4 + 5 = 9 &lt; 10 — aylanalar kesishmaydi. <b>Yechim yo‘q</b>: bunday uchburchak mavjud emas.', 'Откладываем BC = 10 см. Из B проводим окружность радиуса 4 см, из C — 5 см. 4 + 5 = 9 &lt; 10 — окружности не пересекаются. <b>Решения нет</b>: такого треугольника не существует.', 'Lay off BC = 10 cm. Draw a 4 cm circle about B and a 5 cm circle about C. 4 + 5 = 9 &lt; 10 — the circles do not meet. <b>No solution</b>: such a triangle does not exist.') },
      { q: L('To‘g‘ri burchak va 45° li burchakni yasang.', 'Постройте прямой угол и угол 45°.', 'Construct a right angle and a 45° angle.'), s: L('Kesma chizib, uning o‘rta perpendikulyarini yasaymiz — kesishishda <b>90°</b> hosil bo‘ladi. 90° ning bissektrisasi — <b>45°</b>.', 'Чертим отрезок и строим его серединный перпендикуляр — при пересечении получается <b>90°</b>. Биссектриса 90° — <b>45°</b>.', 'Draw a segment and construct its perpendicular bisector — it makes <b>90°</b>. The bisector of 90° gives <b>45°</b>.') }
    ] },
    { kind: 'table', h: L('Qaysi burchaklarni yasash mumkin?', 'Какие углы можно построить?', 'Which angles can be constructed?'), table: { head: [L('Burchak', 'Угол', 'Angle'), L('Qanday yasaladi', 'Как построить', 'How'), L('Mumkinmi', 'Можно?', 'Possible?')], rows: [
      ['60°', L('teng tomonli uchburchak', 'равносторонний треугольник', 'equilateral triangle'), L('ha', 'да', 'yes')],
      ['90°', L('o‘rta perpendikulyar', 'серединный перпендикуляр', 'perpendicular bisector'), L('ha', 'да', 'yes')],
      ['30°, 45°, 15°', L('bissektrisa', 'биссектриса', 'bisector'), L('ha', 'да', 'yes')],
      ['120°, 135°, 75°', L('yig‘indi yoki qo‘shni burchak', 'сумма или смежный угол', 'sum or adjacent angle'), L('ha', 'да', 'yes')],
      ['20°', L('60° ning uchdan biri', 'треть от 60°', 'a third of 60°'), L('yo‘q (triseksiya imkonsiz)', 'нет (трисекция невозможна)', 'no (trisection impossible)')],
      ['1°', L('—', '—', '—'), L('yo‘q', 'нет', 'no')]
    ] }, after: [
      L('Diqqat: ba’zi burchaklarni teng uchga bo‘lish mumkin — masalan, 90° ni (30° ni yasay olamiz). Imkonsizlik <i>ixtiyoriy</i> burchak uchun umumiy usul yo‘qligini bildiradi.', 'Внимание: некоторые углы разделить на три можно — например, 90° (ведь 30° мы строим). Невозможность означает, что нет общего способа для <i>любого</i> угла.', 'Note: some angles can be trisected — 90°, for example (we can construct 30°). The impossibility means there is no general method for <i>every</i> angle.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Chizg‘ich shkalasidan foydalanish.</b> Klassik yasashda chizg‘ich faqat to‘g‘ri chiziq o‘tkazadi. Kesmani o‘lchab, ikkiga bo‘lish — yasash emas.', '<b>Пользоваться делениями линейки.</b> В классическом построении линейка только проводит прямые. Измерить отрезок и поделить пополам — не построение.', '<b>Using the ruler’s scale.</b> In a classical construction the straightedge only draws lines. Measuring and halving is not a construction.'),
      L('<b>Juda kichik radius olish.</b> O‘rta perpendikulyar uchun radius AB ning yarmidan katta bo‘lishi shart, aks holda yoylar kesishmaydi.', '<b>Брать слишком малый радиус.</b> Для серединного перпендикуляра радиус обязан быть больше половины AB, иначе дуги не пересекутся.', '<b>Taking too small a radius.</b> For the perpendicular bisector the radius must exceed half of AB, or the arcs won’t meet.'),
      L('<b>Sirkul ochilishini o‘zgartirib yuborish.</b> Ikki yoy bir xil radiusli bo‘lishi kerak bo‘lsa, sirkulni qayta sozlamang.', '<b>Сбивать раствор циркуля.</b> Если две дуги должны быть одного радиуса, не перенастраивайте циркуль.', '<b>Changing the compass opening.</b> If two arcs must have the same radius, don’t reset the compass.'),
      L('<b>Isbotni tashlab ketish.</b> Yasash chizma bilan tugamaydi — nega natija to‘g‘ri ekanini teng uchburchaklar orqali ko‘rsating.', '<b>Пропускать доказательство.</b> Построение не заканчивается чертежом — покажите через равные треугольники, почему результат верен.', '<b>Skipping the proof.</b> A construction doesn’t end with the drawing — show with congruent triangles why it is correct.'),
      L('<b>Yechim bor-yo‘qligini tekshirmaslik.</b> 3-namunadagidek, ba’zi ma’lumotlar bilan shakl umuman mavjud emas.', '<b>Не проверять существование решения.</b> Как в примере 3, при некоторых данных фигура вообще не существует.', '<b>Not checking existence.</b> As in example 3, with some data the figure doesn’t exist at all.')
    ] },
    { kind: 'life', h: L('Hayotda qayerda kerak?', 'Где это нужно в жизни?', 'Where is it used in life?'), p: [
      L('<b>Naqqoshlikda.</b> Samarqanddagi Registon va Shohi Zinda majmualaridagi girih naqshlari sirkul va chizg‘ich bilan chizilgan. Ustalar aylanani teng qismlarga bo‘lib, 6, 8, 10, 12 nurli yulduzlar yasashgan — har biri ma’lum yasashlarga asoslangan.', '<b>В орнаменте.</b> Узоры гирих на Регистане и в ансамбле Шахи-Зинда в Самарканде начерчены циркулем и линейкой. Мастера делили окружность на равные части и строили 6-, 8-, 10-, 12-лучевые звёзды — каждая основана на определённых построениях.', '<b>In ornament.</b> The girih patterns on the Registan and in the Shah-i-Zinda ensemble in Samarkand were drawn with compass and straightedge. Craftsmen divided circles into equal parts to make 6-, 8-, 10- and 12-pointed stars — each based on particular constructions.'),
      L('<b>Duradgorlik va metallga ishlov berishda.</b> Usta taxtadagi burchakni teng ikkiga bo‘lishi yoki teshik markazini topishi kerak bo‘lsa, aynan shu yasashlardan foydalanadi — o‘lchov asbobi aniq bo‘lmasa ham natija aniq chiqadi.', '<b>В столярном деле и слесарном деле.</b> Когда мастеру нужно разделить угол на заготовке пополам или найти центр отверстия, он использует именно эти построения — результат точен даже без точного мерительного инструмента.', '<b>In woodwork and metalwork.</b> When a craftsman needs to bisect an angle on a workpiece or find the centre of a hole, he uses these very constructions — the result is exact even without precise measuring tools.'),
      L('<b>Kompyuter dasturlarida.</b> GeoGebra kabi dasturlar aynan «sirkul va chizg‘ich» qoidalari asosida ishlaydi: siz nuqta, chiziq va aylanalarni yasaysiz, dastur esa kesishish nuqtalarini topadi.', '<b>В компьютерных программах.</b> Программы вроде GeoGebra работают по правилам «циркуля и линейки»: вы строите точки, прямые и окружности, а программа находит точки пересечения.', '<b>In software.</b> Programs like GeoGebra follow the “compass and straightedge” rules: you construct points, lines and circles, and the program finds the intersections.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('1797-yili italyan matematigi <b>Lorenso Maskeroni</b> isbotlaganki, sirkul va chizg‘ich bilan yasaladigan har qanday nuqtani <b>faqat sirkul</b> bilan ham yasash mumkin! Keyinroq ma’lum bo‘ldiki, daniyalik <b>Georg Mor</b> buni 1672-yildayoq isbotlagan ekan.', 'В 1797 году итальянский математик <b>Лоренцо Маскерони</b> доказал, что любую точку, построимую циркулем и линейкой, можно построить <b>одним циркулем</b>! Позже выяснилось, что датчанин <b>Георг Мор</b> доказал это ещё в 1672 году.', 'In 1797 the Italian mathematician <b>Lorenzo Mascheroni</b> proved that any point constructible with compass and straightedge can be constructed with <b>the compass alone</b>! It later turned out that the Dane <b>Georg Mohr</b> had proved this as early as 1672.'),
      L('Gauss muntazam 17-burchakni yasash mumkinligini kashf etganidan shunchalik faxrlanganki, rivoyatga ko‘ra uni qabr toshiga o‘yib qo‘yishni so‘ragan.', 'Гаусс так гордился открытием построимости правильного 17-угольника, что, по преданию, просил высечь его на своём надгробии.', 'Gauss was so proud of discovering that the regular 17-gon is constructible that, according to legend, he asked for it to be carved on his tombstone.'),
      L('Origami (qog‘oz buklash) bilan sirkul va chizg‘ichdan ham ko‘proq narsa qilish mumkin: buklash orqali burchakni teng uchga bo‘lish va kubni ikkilantirish masalalari yechiladi!', 'Оригами (складывание бумаги) умеет даже больше, чем циркуль и линейка: сгибами можно разделить угол на три части и удвоить куб!', 'Origami (paper folding) can do even more than compass and straightedge: folds can trisect an angle and double a cube!')
    ] },
    { kind: 'practice', h: L('O‘ylab ko‘ring', 'Подумай', 'Think about it'), list: [
      L('Kesmani teng to‘rt qismga qanday bo‘lasiz?', 'Как разделить отрезок на четыре равные части?', 'How do you divide a segment into four equal parts?'),
      L('75° li burchakni qanday yasash mumkin?', 'Как построить угол 75°?', 'How can you construct a 75° angle?'),
      L('Uchburchakning ichida uchala tomondan teng uzoqlikdagi nuqtani qanday yasaysiz?', 'Как построить точку внутри треугольника, равноудалённую от всех трёх сторон?', 'How do you construct a point inside a triangle that is equidistant from all three sides?')
    ], after: [
      L('Javoblar: 1) O‘rta perpendikulyarni ikki marta yasang: avval butun kesma uchun, so‘ng har bir yarmi uchun. 2) 60° + 15° (yoki 90° − 15°). 3) Ikkita burchak bissektrisasini yasang — ular kesishgan nuqta (10-mavzudagi bissektrisa xossasi).', 'Ответы: 1) Постройте серединный перпендикуляр дважды: сначала ко всему отрезку, затем к каждой половине. 2) 60° + 15° (или 90° − 15°). 3) Постройте биссектрисы двух углов — их точка пересечения (свойство биссектрисы из темы 10).', 'Answers: 1) Construct the perpendicular bisector twice: first for the whole segment, then for each half. 2) 60° + 15° (or 90° − 15°). 3) Construct the bisectors of two angles — their crossing point (the bisector property from topic 10).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итог', 'Summary'), list: [
      L('Klassik yasashda faqat sirkul (aylana, yoy) va belgisiz chizg‘ich (to‘g‘ri chiziq) ishlatiladi.', 'В классических построениях используют только циркуль (окружности, дуги) и линейку без делений (прямые).', 'Classical constructions use only a compass (circles, arcs) and an unmarked straightedge (lines).'),
      L('Asosiy yasashlar: teng burchak, bissektrisa, kesma o‘rtasi, perpendikulyar, uch tomoni bo‘yicha uchburchak.', 'Основные построения: равный угол, биссектриса, середина отрезка, перпендикуляр, треугольник по трём сторонам.', 'Basic constructions: copying an angle, bisector, midpoint, perpendicular, triangle from three sides.'),
      L('Har bir yasash uchburchaklar tengligi alomatlari bilan isbotlanadi.', 'Каждое построение доказывается признаками равенства треугольников.', 'Each construction is justified by the congruence tests.'),
      L('Masala: tahlil, yasash, isbot, tekshirish.', 'Задача: анализ, построение, доказательство, исследование.', 'A problem has analysis, construction, proof and discussion.'),
      L('Ixtiyoriy burchak triseksiyasi, kubni ikkilantirish va doira kvadraturasi — imkonsiz (XIX asrda isbotlangan).', 'Трисекция любого угла, удвоение куба и квадратура круга невозможны (доказано в XIX веке).', 'Trisecting any angle, doubling the cube and squaring the circle are impossible (proved in the 19th century).')
    ] }
  ] });
})(this);
